L["A bird on the world map at each flight master you can use: blue for Alliance, red for Horde, gold for both."] = "Ein Vogel auf der Weltkarte bei jedem Flugmeister, den du nutzen kannst: blau für Allianz, rot für Horde, gold für beide."
