L["A dot ( · )"] = "Ein Punkt ( · )"
L["A dragon wrapped around the end of an elite's or boss's bar, in gold, or silver for a rare."] = "Ein Drache, der sich um das Ende der Leiste eines Elites oder Bosses windet, in Gold, oder Silber für einen Seltenen."
L["A frame dropped in unlock mode, a spell placed in the Cooldown Manager editor, a click-cast bound. The game has no sound of its own for these."] = "Ein im Entsperrmodus abgelegter Rahmen, ein im Cooldown-Manager-Editor platzierter Zauber, ein zugewiesener Klickzauber. Das Spiel hat dafür keinen eigenen Sound."
L["A framed panel behind the bar."] = "Ein gerahmtes Panel hinter der Leiste."
L["A friendly player's <guild> under their name, smaller."] = "Die <Gilde> eines befreundeten Spielers unter seinem Namen, kleiner."
L["A gradient per point (Gradients page)"] = "Ein Verlauf pro Punkt (Verläufe-Seite)"
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "Ein grüner Streifen auf der Gesundheitsleiste für ankommende Heilungen, wie die Einheitenrahmen sie zeigen."
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "Ein Kill oder Gegenstand für eine Quest erscheint kurz oben auf dem Bildschirm, klein, mit einer Fortschrittsleiste. Schalte es aus, um stattdessen die gelbe Linie des Spiels zu sehen. Verschiebe es im Entsperrmodus."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "Eine Linie auf feindlichen Gesundheitsleisten, ab der deine Tötungszauber wirken. Das Ende der Leiste bis dorthin leuchtet in deiner Akzentfarbe auf, sobald der Feind so niedrig ist. Deine Klasse: Krieger (Hinrichten) und Paladine (Zornige Vergeltung)."
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "Eine Mana-, Wut- oder Energieleiste unter der Gesundheit. Wenn aus, ist der Rahmen nur Gesundheit."
L["A mark just left of the bar of anything your quests still need. Not inside instances."] = "Eine Markierung links neben der Leiste von allem, was deine Quests noch brauchen. Nicht in Instanzen."
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "Ein Marker über der gewählten Quest und Wegweiser am Boden, die dorthin führen. Mit dem QuestieDB-Addon auch ein Pfeil zum nächsten Ziel."
L["A member's border turns red while something is attacking them."] = "Der Rand eines Mitglieds wird rot, während etwas es angreift."
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "Der Ring eines Mitglieds (oder der Namens-Tab ohne Porträt) wird rot, während etwas es angreift."
L["A name for the new group:"] = "Ein Name für die neue Gruppe:"
L["A name for the new profile (a copy of %s):"] = "Ein Name für das neue Profil (eine Kopie von %s):"
L["A new profession"] = "Ein neuer Beruf"
L["A new profile, made from %s with your picks."] = "Ein neues Profil, erstellt aus %s mit deinen Auswahlen."
L["A new whisper shows its first words above the tiles for a few seconds. Click it to answer."] = "Ein neues Flüstern zeigt seine ersten Worte ein paar Sekunden über den Kacheln. Klicke darauf, um zu antworten."
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "Der Name einer neuen Zone steigt oben auf dem Bildschirm auf mit einer dünnen Linie darunter, dann die Unterzone und der PvP-Status; eine Unterzone zeigt nur ihren Namen, klein. Ersetzt den Zonentext des Spiels. Folgt den Bewegungseffekten (Allgemein > Erscheinungsbild)."
L["A note about this player"] = "Eine Notiz über diesen Spieler"
L["A note for %s:"] = "Eine Notiz für %s:"
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "Ein blasser Streifen auf der Gesundheitsleiste für einen Absorptionsschild, wie die Einheitenrahmen sie zeigen."
L["A panel behind the whole bar, so its buttons sit on one strip."] = "Ein Panel hinter der gesamten Leiste, damit ihre Buttons auf einem Streifen sitzen."
L["A panel behind the whole bar."] = "Ein Panel hinter der gesamten Leiste."
L["A player's <guild> under their name, smaller."] = "Die <Gilde> eines Spielers unter seinem Namen, kleiner."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "Die Zauber eines Spielers in seiner Klassenfarbe oder dem Verlauf seiner Klasse mit zweistufiger Füllung. Zauber von Kreaturen behalten den Füllstil. Nicht mit dem Daylight-Verlauf."
L["A player's name in their class color; other units in their reaction's color."] = "Der Name eines Spielers in seiner Klassenfarbe; andere Einheiten in der Farbe ihrer Reaktion."
L["A pressed button's icon sinks in a little and springs back as you let go."] = "Das Symbol eines gedrückten Buttons sinkt etwas ein und federt zurück, wenn du loslässt."
L["A profile per character or talent set, and a share string for your whole setup."] = "Ein Profil pro Charakter oder Talentbaum und ein Teilen-String für dein gesamtes Setup."
L["A pulsing border while the spell's proc alert is up."] = "Ein pulsierender Rand, während die Proc-Warnung des Zaubers aktiv ist."
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "Eine abgabebereite Quest zeigt nur ihren Titel. Eine zeitlich begrenzte Quest klappt nie ein."
L["A quest you've failed, like a timed one that ran out."] = "Eine Quest, die du fehlgeschlagen hast, wie eine zeitlich begrenzte, deren Zeit abgelaufen ist."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "Ein Ring über dem äußeren Ende. Klassensymbole für Spieler; NSCs zeigen ihr Gesicht. Benötigt einen Rahmen von mindestens 20 Höhe."
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "Ein rundes Abzeichen mit ihrem Porträt oder eine schlanke Leiste mit dem Porträt daneben und dem Namen darüber."
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "Ein zweiter Schadensmeter in einem eigenen Fenster, für zwei Listen gleichzeitig: z. B. Heilung neben Schaden. Bewege die Maus darüber für dieselben Buttons."
L["A set already has that name."] = "Ein Satz hat bereits diesen Namen."
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "Ein Schild: Die Leiste leert sich, während er Schaden absorbiert, mit der verbleibenden Menge. Oder nach seiner Zeit, wie jeder Stärkungszauber."
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "Eine Fertigkeit, die steigt, zeigt ihren neuen Rang bis zum Maximum: Schneiderei 152 / 225. Weitere Steigerungen aktualisieren dieselbe Zeile."
L["A slash ( / )"] = "Ein Schrägstrich ( / )"
L["A slim bar under the tooltip of a player or creature."] = "Eine schlanke Leiste unter dem Tooltip eines Spielers oder einer Kreatur."
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "Ein Platz mit dieser oder weniger Haltbarkeit bekommt einen bernsteinfarbenen Punkt und sagt „Bald reparieren“."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "Ein kleines BoE (gebunden beim Anlegen) oder BoU (gebunden beim Benutzen) in der oberen linken Ecke von Bankgegenständen, bis der Gegenstand an dich gebunden ist."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "Ein kleines BoE (gebunden beim Anlegen) oder BoU (gebunden beim Benutzen) in der oberen linken Ecke, bis der Gegenstand an dich gebunden ist."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "Ein kleines BoE (gebunden beim Anlegen) oder BoU (gebunden beim Benutzen) in der oberen linken Ecke, bis der Gegenstand gebunden ist."
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "Ein kleiner Kopieren-Button oben rechts im Chat. Er öffnet den Text des Tabs, damit du ihn markieren und Strg+C drücken kannst. /dui copy macht dasselbe."
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "Ein kleines Abzeichen am Fuß des Porträts (oder in der Ecke des Rahmens ohne eines), gefärbt nach der Schwierigkeit der Einheit für dich."
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "Ein kleines Abzeichen am Fuß des Porträts, gefärbt nach der Schwierigkeit der Einheit für dich. Benötigt das Porträt oder den Namens-Tab."
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "Eine kleine Leiste neben jedem Gruppenmitglied, das einen Begleiter draußen hat. Dein eigener Begleiter behält seinen eigenen Rahmen."
L["A small crown on the raid leader's tile."] = "Eine kleine Krone auf der Kachel des Schlachtzugsanführers."
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "Ein kleiner Kronen-Tab neben deinen Gruppen- oder Schlachtzugsrahmen, während du die Gruppe anführst oder im Schlachtzug assistierst. Er öffnet Bereitschaftscheck, Rollenprüfung, einen Pull-Timer, Ziel- und Weltmarker sowie „Jeder ist Assistent“. Wenn aus, sind diese nur über die Slash-Befehle des Spiels erreichbar."
L["A small dot in front of each quest you're tracking."] = "Ein kleiner Punkt vor jeder Quest, die du verfolgst."
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "Ein kleiner Punkt in der oberen rechten Ecke auf Bankgegenständen, die Teil eines deiner Ausrüstungssätze sind."
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "Ein kleiner Punkt in der oberen rechten Ecke auf Gegenständen, die Teil eines deiner Ausrüstungssätze sind."
L["A small gray line at the bottom of spell and item tooltips with its ID: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "Eine kleine graue Zeile unten in Zauber- und Gegenstand-Tooltips mit ihrer ID: nützlich für Makros, andere Addons und Fehlerberichte. Stärkungs- und Schwächungszauber-Symbole nutzen den eigenen Tooltip des Spiels, der sie nicht anzeigen kann."
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "Ein kleines Symbol in einer Ecke für einen Schwächungszauber, den du entfernen kannst, umrandet in der Farbe seines Typs."
L["A small mana, rage or energy number on the power bar."] = "Eine kleine Mana-, Wut- oder Energiezahl auf der Ressourcenleiste."
L["A small number in your accent color after a tab's name: how many new messages landed in it since you last looked."] = "Eine kleine Zahl in deiner Akzentfarbe nach dem Namen eines Tabs: wie viele neue Nachrichten seit dem letzten Blick angekommen sind."
L["A small pet bar beside each party member whose pet is out."] = "Eine kleine Begleiterleiste neben jedem Gruppenmitglied, dessen Begleiter draußen ist."
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "Ein kleiner Totenkopf auf dem Porträt, sobald dein Schaden über Zeit ausreicht, um das Ziel zu beenden."
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "Ein kleiner Totenkopf hinter dem Ende der Leiste, sobald dein Schaden über Zeit ausreicht, um diesen Feind zu beenden."
L["A small soft drop shadow under text."] = "Ein kleiner weicher Schlagschatten unter Text."
L["A small speech bubble at the top-right of the chat that counts your unread whispers and opens all your conversations. /dui whispers does the same."] = "Eine kleine Sprechblase oben rechts im Chat, die deine ungelesenen Flüstern zählt und alle deine Gespräche öffnet. /dui whispers macht dasselbe."
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "Ein kleines Quadrat links vom Rahmen: rot, während dein Begleiter unglücklich ist, gelb, während zufrieden, grün, während glücklich. Bewege die Maus darüber für seinen Schaden, Treue und Ernährung."
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "Ein kleines Etikett nach dem Titel einer Elite-, Dungeon-, Schlachtzugs- oder PvP-Quest, hier und im Questlog auf der Karte."
L["A small time at the bottom of the map. Hover it for both local and server time."] = "Eine kleine Uhrzeit unten auf der Karte. Bewege die Maus darüber für Orts- und Serverzeit."
L["A small zone name over each group of quests, the zone you're in first."] = "Ein kleiner Zonenname über jeder Questgruppe, die Zone, in der du bist, zuerst."
L["A soft chime when talents are applied, a talent set is switched, a spell is learned at a trainer or a letter is sent."] = "Ein sanfter Glockenton, wenn Talente angewendet, ein Talentbaum gewechselt, ein Zauber bei einem Lehrer gelernt oder ein Brief gesendet wird."
L["A soft glow behind a message that says your name or one of your words."] = "Ein sanfter Glow hinter einer Nachricht, die deinen Namen oder eines deiner Wörter enthält."
L["A soft glow in the threat color around the health bar."] = "Ein sanfter Glow in der Bedrohungsfarbe um die Gesundheitsleiste."
L["A soft light behind the arrow, in its color."] = "Ein sanftes Licht hinter dem Pfeil, in seiner Farbe."
L["A soft light in the line's color runs across it as it comes in or adds up."] = "Ein sanftes Licht in der Farbe der Zeile läuft darüber, wenn sie erscheint oder sich erhöht."
L["A soft light round the frame in the debuff's type color."] = "Ein sanftes Licht um den Rahmen in der Farbe des Schwächungszauber-Typs."
L["A soft light round the tile in the debuff's type color."] = "Ein sanftes Licht um die Kachel in der Farbe des Schwächungszauber-Typs."
L["A soft shadow round each button."] = "Ein weicher Schatten um jeden Button."
L["A soft sound when your name or one of your words shows up."] = "Ein leiser Sound, wenn dein Name oder eines deiner Wörter erscheint."
L["A soft, minimal interface."] = "Eine weiche, minimale Oberfläche."
L["A soft, warm chime when a tracked quest is ready to hand in."] = "Ein sanfter, warmer Glockenton, wenn eine verfolgte Quest abgabebereit ist."
L["A space"] = "Ein Leerzeichen"
L["A spell that just lit up, like Overpower or Execute."] = "Ein Zauber, der gerade aufgeleuchtet ist, wie Überwältigen oder Hinrichten."
L["A spell with charges: the bar is cut into one piece per charge."] = "Ein Zauber mit Ladungen: Die Leiste ist in ein Segment pro Ladung unterteilt."
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "Das Symbol eines Zaubers springt und leuchtet einmal auf, wenn er von einer echten Abklingzeit kommt (nie für die globale Abklingzeit). Benötigt Bewegungseffekte (Allgemein > Erscheinungsbild)."
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "Das Symbol eines Zaubers wird grau, während er auf Abklingzeit ist. Die globale Abklingzeit zählt nicht."
L["A square minimap in the panel. Scroll to zoom."] = "Eine quadratische Minikarte im Panel. Scrollen zum Zoomen."
L["A stun, fear, polymorph and the like, as a bigger icon beside the bar's end."] = "Eine Betäubung, Furcht, Verwandlung und Ähnliches als größeres Symbol neben dem Ende der Leiste."
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "Ein Symbol auf der Weltkarte an jedem Bootsanleger und Zeppelinturm. Bewege die Maus darüber, um zu sehen, wohin es geht."
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "Ein Symbol auf der Weltkarte an jedem Dungeon- und Schlachtzugseingang. Bewege die Maus darüber für den Namen."
L["A thin bar under the name."] = "Eine dünne Leiste unter dem Namen."
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "Eine dünne Linie über die Leisten, wo deine Bedrohung sie ziehen würde: 110% der des Tanks im Nahkampf, 130% auf Distanz. Nicht auf einem Boss gezeigt, dessen Zahlen das Spiel verborgen hält."
L["A thin line in your accent color along the top of the chat."] = "Eine dünne Linie in deiner Akzentfarbe entlang der Oberseite des Chats."
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "Ein dünner Mana-Streifen am unteren Rand der Ressourcenleiste, während eine Form dein Mana versteckt."
L["A thin mana, rage or energy bar at the foot of each tile."] = "Eine dünne Mana-, Wut- oder Energieleiste am Fuß jeder Kachel."
L["A thin outline on chat text."] = "Ein dünner Umriss auf Chat-Text."
L["A thin power bar under each pet's health."] = "Eine dünne Ressourcenleiste unter der Gesundheit jedes Begleiters."
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "Ein dünner Streifen unter der Minikarte: Gold, Ausrüstung, Taschenplatz, online Freunde. Bewege die Maus über eines für Details, klicke, um sein Fenster zu öffnen."
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "Ein dünnerer Umriss lässt mehr von jedem Punkt für die Farbe. Auf 0 setzen für keinen."
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "Ein Tooltip für etwas in der Welt (eine Kreatur, ein Spieler, ein Briefkasten) blendet langsam aus, nachdem die Maus ihn verlässt, wie im Spiel. Wenn aus, ist er sofort weg."
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "Eine Spur aus kleinen Rauten von deinen Füßen zum Marker, die darauf zutreibt. Wie der Marker verblasst sie, sobald du im Questgebiet auf der Karte bist."
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "Eine zweiminütige Tour durch alles, was DaylightUI macht, mit Auswahlen unterwegs. Nichts wird gespeichert, bis du fertig bist."
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "Eine warme Lichtlinie breitet sich oben auf dem Bildschirm aus, deine neue Stufe rollt herein und was du erhalten hast, blendet darunter ein, anstelle des Banners des Spiels. Folgt den Bewegungseffekten (Allgemein > Erscheinungsbild)."
L["A warning when your health or mana drops low."] = "Eine Warnung, wenn deine Gesundheit oder dein Mana niedrig wird."
L["A word when a fight starts and ends."] = "Ein Wort, wenn ein Kampf beginnt und endet."
L["AFK"] = "AFK"
L["AVOIDABLE"] = "VERMEIDBAR"
L["AWAY"] = "ABWESEND"
L["Abandon"] = "Aufgeben"
L["Abandon \"%s\"?"] = "„%s“ aufgeben?"
L["Abandon?"] = "Aufgeben?"
L["About 1 in %d of your attacks hits for double damage."] = "Etwa 1 von %d deiner Angriffe trifft für doppelten Schaden."
L["About 1 in %d of your shots hits for double damage."] = "Etwa 1 von %d deiner Schüsse trifft für doppelten Schaden."
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "Etwa 1 von %d deiner Zauber landet einen kritischen Treffer für die Hälfte mehr."
L["Above"] = "Darüber"
L["Above or below the frame, the bar is as wide as the frame. Off: the Width below."] = "Über oder unter dem Rahmen ist die Leiste so breit wie der Rahmen. Aus: die Breite darunter."
L["Above or below the frame: moves the bar sideways from the middle."] = "Über oder unter dem Rahmen: verschiebt die Leiste seitlich von der Mitte."
L["Above or below the frame: moves the bar up or down."] = "Über oder unter dem Rahmen: verschiebt die Leiste nach oben oder unten."
L["Above the frame"] = "Über dem Rahmen"
L["Above the health bar"] = "Über der Gesundheitsleiste"
L["Above the name tab by default, running inward. Yours come first."] = "Standardmäßig über dem Namens-Tab, nach innen. Deine kommen zuerst."
L["Above your debuffs, from the right."] = "Über deinen Schwächungszaubern, von rechts."
L["Absorb shields"] = "Absorptionsschilde"
L["Absorbs"] = "Absorptionen"
L["Accent"] = "Akzent"
L["Accent color"] = "Akzentfarbe"
L["Accent follows Appearance, including the Daylight gradient."] = "Akzent folgt dem Erscheinungsbild, einschließlich des Daylight-Verlaufs."
L["Accent follows the accent color on the Appearance page. Class uses your class's gradient (set on the Gradients page). Reputation keeps its standing's colors."] = "Akzent folgt der Akzentfarbe auf der Erscheinungsbild-Seite. Klasse verwendet den Verlauf deiner Klasse (eingestellt auf der Verläufe-Seite). Ruf behält die Farben seines Rangs."
L["Accent follows the accent you picked on the General page, gradient and all."] = "Akzent folgt dem Akzent, den du auf der Allgemein-Seite gewählt hast, inklusive Verlauf."
L["Accent follows your accent color (General > Appearance), or pick your own."] = "Akzent folgt deiner Akzentfarbe (Allgemein > Erscheinungsbild), oder wähle deine eigene."
L["Accent line on top"] = "Akzentlinie oben"
L["Accept"] = "Annehmen"
L["Accept key"] = "Annehmen-Taste"
L["Accept quests automatically"] = "Quests automatisch annehmen"
L["Account"] = "Account"
L["Achievement announcements."] = "Erfolgsankündigungen."
L["Achievement color"] = "Erfolgsfarbe"
L["Achievements"] = "Erfolge"
L["Across"] = "Quer"
L["Across the bar"] = "Quer über die Leiste"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "Quer über die Leiste hält es innen. Jede andere Position setzt es dort, auf oder um den Rahmen, damit ein langer Name Platz hat. Du kannst es auch im Design-Modus ziehen."
L["Across the bar keeps the alignment below. Beside the tile needs space between tiles."] = "Quer über die Leiste behält die Ausrichtung darunter. Neben der Kachel braucht Platz zwischen den Kacheln."
L["Across, you shown, by role, icons in corners"] = "Quer, du angezeigt, nach Rolle, Symbole in Ecken"
L["Action Bar 1"] = "Aktionsleiste 1"
L["Action Bar 2"] = "Aktionsleiste 2"
L["Action Bar 3"] = "Aktionsleiste 3"
L["Action Bar 4"] = "Aktionsleiste 4"
L["Action Bar 5"] = "Aktionsleiste 5"
L["Action Bar 6"] = "Aktionsleiste 6"
L["Action Bar 7"] = "Aktionsleiste 7"
L["Action Bar 8"] = "Aktionsleiste 8"
L["Action Bars"] = "Aktionsleisten"
L["Action bars"] = "Aktionsleisten"
L["Activate"] = "Aktivieren"
L["Activate this set first."] = "Aktiviere zuerst diesen Satz."
L["Active spell"] = "Aktiver Zauber"
L["Active spell color"] = "Farbe des aktiven Zaubers"
L["Active spell opacity"] = "Deckkraft des aktiven Zaubers"
L["Add"] = "Hinzufügen"
L["Add a friend: a BattleTag (Name#1234) or a character's name."] = "Einen Freund hinzufügen: einen BattleTag (Name#1234) oder den Namen eines Charakters."
L["Add a group"] = "Eine Gruppe hinzufügen"
L["Add friend"] = "Freund hinzufügen"
L["Add to favorites"] = "Zu Favoriten hinzufügen"
L["AddOns"] = "AddOns"
L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "Hinzugefügt mit „Teil hinzufügen“ im Design-Modus. Ziehe es auf der Vorschau, um es zu verschieben. Bis zu drei Teile in einer Zeile, jedes in seiner eigenen Farbe."
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "Hinzugefügt mit „Teil hinzufügen“ im Design-Modus: eine weitere Aura-Reihe mit eigenem Filter."
L["Addon button drawer"] = "Addon-Button-Schublade"
L["Addon options (Ace3)"] = "Addon-Optionen (Ace3)"
L["Addons' minimap buttons and the game's addon menu are gathered into one drawer. The button in the map's bottom-right corner opens it."] = "Die Minikarten-Buttons der Addons und das Addon-Menü des Spiels sind in einer Schublade gesammelt. Der Button in der unteren rechten Ecke der Karte öffnet sie."
L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "Fügt ein warmes Band innerhalb des schwarzen Umrisses hinzu, oben beleuchtet. Wenn aus, ist der Rand eine einfache dunkle Linie."
L["Adds about %.0f damage per second to your melee attacks."] = "Fügt deinen Nahkampfangriffen etwa %.0f Schaden pro Sekunde hinzu."
L["Adds about %.0f damage per second to your shots."] = "Fügt deinen Schüssen etwa %.0f Schaden pro Sekunde hinzu."
L["Adds up to %.0f to your heals."] = "Fügt deinen Heilungen bis zu %.0f hinzu."
L["Adds up to %.0f to your spells' damage."] = "Fügt dem Schaden deiner Zauber bis zu %.0f hinzu."
