L["Affliction"] = "Gebrechen"
L["After /reload, the last messages in each chat tab come back, above a gray line."] = "Nach einem /reload kommen die letzten Nachrichten in jedem Chat-Tab zurück, über einer grauen Linie."
L["After a login or /reload the UI starts invisible and glides in. Anything set to fade ends faded."] = "Nach einem Login oder /reload startet die UI unsichtbar und gleitet herein. Alles, was auf Ausblenden eingestellt ist, endet ausgeblendet."
