L["An Item Level line on weapon and armor tooltips, in soft gold."] = "Eine Gegenstandsstufe-Zeile in Waffen- und Rüstungs-Tooltips, in weichem Gold."
L["An arrow on your screen that points to the nearest mob or object you still need for the quest you picked, then to the quest giver once it's ready, with the yards under it. Nothing goes on the map. Needs the QuestieDB addon."] = "Ein Pfeil auf deinem Bildschirm, der auf den nächsten Gegner oder Gegenstand zeigt, den du für die gewählte Quest noch brauchst, dann auf den Questgeber, sobald sie fertig ist, mit den Metern darunter. Nichts kommt auf die Karte. Benötigt das QuestieDB-Addon."
L["An item link shows your equipped item beside it, as the game's own compare setting says. Off, only while Shift is held."] = "Ein Gegenstandslink zeigt deinen ausgerüsteten Gegenstand daneben, wie die Vergleichseinstellung des Spiels sagt. Aus, nur während Umschalt gehalten wird."
L["An item's green Equip lines in a few words (\"Improves your chance to hit by 1%\" reads \"+1% Hit\"), and every stat in a color of its own: each school, hit, crit, spell power, healing, the base stats. Procs and use effects stay as they are."] = "Die grünen Anlegen-Zeilen eines Gegenstands in wenigen Worten („Erhöht eure Trefferchance um 1%“ wird zu „+1% Treffer“), und jede Statistik in ihrer eigenen Farbe: jede Schule, Treffer, Krit, Zaubermacht, Heilung, die Basiswerte. Procs und Verwendungseffekte bleiben wie sie sind."
L["An objective you've finished."] = "Ein Ziel, das du abgeschlossen hast."
L["An outline around its bar, a soft glow around it, or nothing."] = "Ein Umriss um seine Leiste, ein sanfter Glow darum oder nichts."
L["And %d more"] = "Und %d weitere"
L["And %d more: keep typing to narrow it down."] = "Und %d weitere: Tippe weiter, um einzugrenzen."
