L["Another layout to copy: your other talent set, your other characters', or a layout from before layouts were per character."] = "Ein weiteres Layout zum Kopieren: dein anderer Talentbaum, der deiner anderen Charaktere oder ein Layout von bevor Layouts pro Charakter waren."
L["Another player's gear and talents in one window, in DaylightUI style."] = "Die Ausrüstung und Talente eines anderen Spielers in einem Fenster, im DaylightUI-Stil."
L["Another thing after the first on the same line, like the level after a name."] = "Ein weiteres Ding nach dem ersten in derselben Zeile, wie die Stufe nach einem Namen."
