L["Class and profession trainers open in the NPC window too, with what you can learn now and what's coming up. Pick a spell, then press Train or Train all: a click or a key alone never spends gold. Turn it off to use the game's trainer window."] = "Klassen- und Berufslehrer öffnen sich auch im NSC-Fenster, mit dem, was du jetzt lernen kannst und was als Nächstes kommt. Wähle einen Zauber, dann drücke Lernen oder Alle lernen: Ein Klick oder eine Taste allein gibt nie Gold aus. Schalte es aus, um das Lehrerfenster des Spiels zu nutzen."
