L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "Schneidet beide Enden jeder Zeile schräg. Wenn aus, sind die Enden gerade."
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "Schneidet das rechte Ende jeder Kachel schräg, wie deinen eigenen Rahmen; die Leisten folgen ihm."
L["Cuts one end of each pet bar at an angle. When off, the ends are straight."] = "Schneidet ein Ende jeder Begleiterleiste schräg. Wenn aus, sind die Enden gerade."
L["Cuts the end of the bar at an angle. When off, the end is straight."] = "Schneidet das Ende der Leiste schräg. Wenn aus, ist das Ende gerade."
L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Schneidet das Ende der Zauberleiste deines Fokus schräg. Wenn aus, ist das Ende gerade. Nicht, solange sie im Rahmen sitzt."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "Schneidet das Ende der Zauberleiste deines Ziels schräg. Wenn aus, ist das Ende gerade. Nicht, solange sie im Rahmen sitzt."
L["Cuts the frame's inner end at an angle; the bars follow it."] = "Schneidet das innere Ende des Rahmens schräg; die Leisten folgen ihm."
L["Cuts the left end at an angle; the bars follow it."] = "Schneidet das linke Ende schräg; die Leisten folgen ihm."
L["Cuts the right end at an angle; the bars and an attached cast bar follow it."] = "Schneidet das rechte Ende schräg; die Leisten und eine angehängte Zauberleiste folgen ihm."
L["Cuts the right end at an angle; the bars follow it."] = "Schneidet das rechte Ende schräg; die Leisten folgen ihm."
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "Zwischensequenzen und Introfilme enden sofort. Halte Umschalt, wenn einer startet, um ihn anzuschauen."
