L["DPS / Tank"] = "DPS / Tank"
L["DPS / Tank (as it comes)"] = "DPS / Tank (wie es kommt)"
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tank ruhig zum Questen: deine Aktionsleisten und dein eigener Rahmen blenden eine Weile nach einem Kampf aus (zurück unter die Maus, im Kampf oder wenn du verletzt bist), der Schadensmeter startet eingeklappt (ein Klick auf den Tab des Panels holt ihn hervor), die Minikarte ist etwas kleiner und die EP-Leiste zeigt ihren Prozentsatz. Nichts blendet in Dungeons, Schlachtzügen, Schlachtfeldern oder Arenen aus (Allgemein > Erscheinungsbild, Fade nur in der offenen Welt). Wähle es oben, um es zu nutzen. Wenn das aktuelle Profil Aktionsleisten verschoben hat, bietet es an, sie mitzunehmen."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "DPS/Tank mit deiner Gruppe und deinem Schlachtzug als quadratische Kacheln unter dir (du inklusive, fehlende Gesundheit auf ihnen, Dispels gut sichtbar) und deinem Rahmen sowie dem deines Ziels etwas angehoben. Alles, was es einstellt, steht auf den Gruppen- und Schlachtzugsseiten; verschiebe sie im Entsperrmodus. Wähle es oben, um es zu nutzen. Wenn das aktuelle Profil Aktionsleisten verschoben hat, bietet es an, sie mitzunehmen."
