L["Daylight"] = "Daylight"
L["Daylight UI couldn't skin %s %s: it's left as it is."] = "Daylight UI konnte %s %s nicht skinnen: es bleibt wie es ist."
L["Daylight UI's chat box in the bottom-left corner, with whispers as conversations beside it. Chat style: Classic keeps the game's own chat windows instead."] = "Die Chatbox von Daylight UI in der unteren linken Ecke, mit Flüstern als Gespräche daneben. Chat-Stil: Klassisch behält stattdessen die Chatfenster des Spiels."
L["Daylight UI's journal, marker and arrow stay either way. You can change it later on the Quests options page."] = "Das Tagebuch, der Marker und der Pfeil von Daylight UI bleiben in beiden Fällen. Du kannst es später auf der Quest-Optionsseite ändern."
L["Daylight gradient"] = "Daylight-Verlauf"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "Daylight ist das warme Band innerhalb eines dunklen Umrisses, Flat ein schlichter Umriss. Bei Keine füllt das Symbol den ganzen Button."
L["Daylight look"] = "Daylight-Aussehen"
L["Daylight: Daylight UI's own chat box, with its own tabs. Classic: the game's chat windows and tabs in the Daylight look. Switching is instant, and both keep every message."] = "Daylight: Die eigene Chatbox von Daylight UI mit eigenen Tabs. Klassisch: die Chatfenster und Tabs des Spiels im Daylight-Look. Das Umschalten ist sofort, und beide behalten jede Nachricht."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame (Extras > Frame style). Each style keeps its own heights."] = "Daylight: der Rahmen mit seinem Namen in einem Tab darüber und der Ressourcenleiste innen. Ribbon: eine schlanke Leiste mit Name und Gesundheit darüber schwebend und der Ressource als dünne Linie darunter. Standard verwendet den Stil, der für jeden Rahmen eingestellt ist (Extras > Rahmenstil). Jeder Stil behält seine eigenen Höhen."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight: der Rahmen mit seinem Namen in einem Tab darüber und der Ressourcenleiste innen. Ribbon: eine schlanke Leiste mit Name und Gesundheit darüber schwebend und der Ressource als dünne Linie darunter. Jeder Rahmen kann auf seiner Seite seinen eigenen wählen."
L["DaylightMogul's mailbox is in use."] = "Der Briefkasten von DaylightMogul ist in Verwendung."
L["DaylightMogul's profession window is in use."] = "Das Beruf-Fenster von DaylightMogul ist in Verwendung."
L["DaylightMogul's vendor window is in use."] = "Das Händlerfenster von DaylightMogul ist in Verwendung."
L["DaylightUI"] = "DaylightUI"
L["DaylightUI (General)"] = "DaylightUI (Allgemein)"
L["DaylightUI Discord"] = "DaylightUI Discord"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "DaylightUI hat einen neuen Einrichtungsassistenten. Mach die Tour, um alles zu sehen, was es kann, oder behalte dein Setup so, wie es ist."
L["DaylightUI is set up on this character. Reload to put it in place?"] = "DaylightUI ist auf diesem Charakter eingerichtet. Neu laden, um es anzuwenden?"
L["DaylightUI look for speech bubbles (say, yell, party). Instances keep the game's bubbles, since addons can't change them there."] = "DaylightUI-Aussehen für Sprechblasen (sagen, schreien, Gruppe). Instanzen behalten die Sprechblasen des Spiels, da Addons sie dort nicht ändern können."
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "DaylightUI hat den Questverfolger verschoben, damit er zum Panel passt. Neu laden, um es anzuwenden?"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "DaylightUI hat das Bearbeitungsmodus-Layout dieses Profils angewendet. Neu laden, um es zu nutzen?"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "DaylightUI ersetzt deine Rahmen, Leisten, Taschen, Chat und mehr durch ein weiches, minimales Aussehen. Lass uns diesen Charakter einrichten."
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "DaylightUI hat die Position des Beutefensters gespeichert. Neu laden, um es anzuwenden?"
L["DaylightUI saved the quest tracker's position. Reload to put it in place?"] = "DaylightUI hat die Position des Questverfolgers gespeichert. Neu laden, um es anzuwenden?"
