L["Drag a piece to move it. Click it for its settings; the arrow keys then nudge it."] = "Ziehe ein Teil, um es zu verschieben. Klicke es für seine Einstellungen; die Pfeiltasten schieben es dann."
L["Drag a tab to move it. Right-click: what it shows, rename, remove"] = "Ziehe einen Tab, um ihn zu verschieben. Rechtsklick: was er zeigt, umbenennen, entfernen"
L["Drag it to an action bar."] = "Ziehe es auf eine Aktionsleiste."
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "Ziehe die Teile der Vorschau, um sie zu verschieben: jedes bleibt, wo du es loslässt, oder rastet an einem Punkt direkt daneben ein. Klicke eines, und die Pfeiltasten schieben es (Umschalt für größere Schritte). Jede Bewegung ändert dieselben Einstellungen wie die Karten darunter."
L["Drag to move it, or click for its settings."] = "Ziehen zum Verschieben, oder klicken für seine Einstellungen."
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "Ziehen zum Verschieben. Lege es neben ein anderes Teil, um es anzuhängen, ziehe es weg, um es zu lösen. Löschen entfernt es."
