L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "Während eines Bereitschaftschecks ein Haken, ein Kreuz oder ein Fragezeichen auf jedem Mitglied: bereit, nicht bereit oder noch keine Antwort. Sie bleiben ein paar Sekunden, nachdem der Check endet."
L["ENEMY TAKEN"] = "ERLITTENER SCHADEN (FEIND)"
L["Each bar in its player's class color, or all in one color."] = "Jede Leiste in der Klassenfarbe ihres Spielers oder alle in einer Farbe."
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "Die Hand jeder Leiste (oder der Angriff in der Warteschlange) und die Zeit bis zum nächsten Schlag, auf der Leiste geschrieben."
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "Die Form jeder Leiste und wann sie angezeigt wird. Änderungen gelten sofort. Verschiebe Leisten im Entsperrmodus."
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "Größe, Form und Wann-Anzeige jeder Leiste. Wähle die Leiste mit Einstellungen für."
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "Jeder Charakter verwendet ein Profil (eines pro Talentbaum, mit dualer Spezialisierung). Alles auf jeder Seite ändert das aktuelle Profil."
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere: right-click the bag icon at the top of your bags, or /dui bank. When off, Alts leaves that menu and nothing new is saved."] = "Die Taschen jedes Charakters werden gespeichert, wenn du dich ausloggst, und seine Bank jedes Mal, wenn du einen Bankier besuchst. Sieh sie überall: Rechtsklick auf das Taschensymbol oben in deinen Taschen, oder /dui bank. Wenn aus, verschwindet Twinks aus diesem Menü und nichts Neues wird gespeichert."
L["Each combo point you build on your target."] = "Jeder Combopunkt, den du auf deinem Ziel aufbaust."
L["Each icon darkens like a clock as its time runs out."] = "Jedes Symbol dunkelt wie eine Uhr ab, während seine Zeit abläuft."
L["Each icon's width and height."] = "Breite und Höhe jedes Symbols."
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "Der Name und die Gegenstandsstufe jedes Gegenstands neben seinem Symbol. Wenn aus, werden nur die Symbole angezeigt, mit der Gegenstandsstufe in jeder Ecke und mehr Platz für das Modell."
L["Each its own"] = "Jeder seine eigene"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "Jeder Haupthand-Schlag trifft für %.0f bis %.0f vor Rüstung."
L["Each member's health written on their tile."] = "Die Gesundheit jedes Mitglieds auf seiner Kachel geschrieben."
L["Each member's name on their tile."] = "Der Name jedes Mitglieds auf seiner Kachel."
L["Each new message fades in instead of appearing at once. Never in a fight."] = "Jede neue Nachricht blendet ein, statt sofort zu erscheinen. Nie im Kampf."
L["Each objective line under a quest."] = "Jede Zielzeile unter einer Quest."
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "Jede Person, die dich anflüstert, bekommt einen Tab neben den anderen, und das Flüstern erscheint auch in deinem Haupt-Tab. Wenn aus, erscheinen Flüstern nur im Haupt-Tab."
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "Jeder Punkt neigt sich wie die abgeschrägten Enden der Rahmen. Wenn aus, sind ihre Enden gerade."
L["Each pip's end cut at an angle, like the health bar's."] = "Das Ende jedes Punkts schräg geschnitten, wie bei der Gesundheitsleiste."
L["Each quest's level in front of its title, like [15]."] = "Die Stufe jeder Quest vor ihrem Titel, wie [15]."
L["Each quest's title in the tracker."] = "Der Titel jeder Quest im Verfolger."
L["Each shot hits for %.0f to %.0f before armor."] = "Jeder Schuss trifft für %.0f bis %.0f vor Rüstung."
L["Each square darkens like a clock as your spell runs out."] = "Jedes Quadrat dunkelt wie eine Uhr ab, während dein Zauber abläuft."
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "Jeder Talentbaum hat sein eigenes Layout. Layout bearbeiten und Kopieren von arbeiten an diesem."
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "Jeder Text aktualisiert sich, wenn er sich ändert. Überfahren für Details: Gold auf jedem Charakter, jedes Ausrüstungsteil, jede Tasche, wer online ist."
L["Each threat bar in its player's class color, or all in one color."] = "Jede Bedrohungsleiste in der Klassenfarbe ihres Spielers oder alle in einer Farbe."
L["Early start"] = "Früher Start"
L["Earned"] = "Verdient"
L["Earned this session"] = "In dieser Sitzung verdient"
L["Eases class, reaction and power colors toward gray for a gentler look."] = "Mildert Klassen-, Reaktions- und Ressourcenfarben in Richtung Grau für ein sanfteres Aussehen."
