L["Enemy pets and totems"] = "Feindliche Begleiter und Totems"
L["Enemy pets and totems get a look of their own, totems in their element's color. In battlegrounds they're all red: the game hides which totem it is. When off, the game's setting for their plates is turned off too."] = "Feindliche Begleiter und Totems bekommen ein eigenes Aussehen, Totems in der Farbe ihres Elements. Auf Schlachtfeldern sind sie alle rot: das Spiel versteckt, welches Totem es ist. Wenn aus, wird auch die Einstellung des Spiels für ihre Plaketten ausgeschaltet."
L["Enemy plates: the health bar, the name under it, casts, your debuffs and crowd control. Friendly plates are simpler."] = "Feindliche Plaketten: die Gesundheitsleiste, der Name darunter, Zauber, deine Schwächungszauber und Kontrollverlust. Freundliche Plaketten sind einfacher."
L["Energy"] = "Energie"
L["Enhancement"] = "Verstärkung"
L["Enter"] = "Eingabe"
L["Enter or Space"] = "Enter oder Leertaste"
L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "Enter sagt ja, wenn dich jemand etwas fragt: eine Gruppeneinladung, eine geteilte Quest, eine Beschwörung, eine Wiederbelebung. Nie bei etwas, das bindet, würfelt oder kostet, und nie im Kampf. Ein Gasthaus zum Zuhause zu machen, nimmt auch deine Annehmen-Taste."
L["Entering and leaving combat"] = "Kampf beginnen und verlassen"
L["Epic (purple) and up"] = "Episch (lila) und höher"
L["Epic mount fund: %d%%. Keep saving!"] = "Episches Reittier-Fonds: %d%%. Weiter sparen!"
L["Equipment sets"] = "Ausrüstungssätze"
L["Error messages"] = "Fehlermeldungen"
L["Error text"] = "Fehlertext"
L["Error text in DaylightUI style"] = "Fehlertext im DaylightUI-Stil"
L["Esc"] = "Esc"
L["Every area's fade in one place: in combat, on mouseover, or always shown."] = "Fade jedes Bereichs an einem Ort: im Kampf, bei Mouseover oder immer angezeigt."
L["Every bag in one window, with search, sorting and categories."] = "Jede Tasche in einem Fenster, mit Suche, Sortierung und Kategorien."
L["Every color in the quest tracker."] = "Jede Farbe im Questverfolger."
L["Every debuff on you, over your frame. Off by default: your buff bars show them too."] = "Jeder Schwächungszauber auf dir, über deinem Rahmen. Standardmäßig aus: deine Stärkungszauber-Leisten zeigen sie auch."
L["Every empty slot"] = "Jeder leere Platz"
L["Every font"] = "Jede Schrift"
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "Die Leiste jeder Hand in deiner Klassenfarbe oder dem Verlauf deiner Klasse mit zweistufiger Füllung. Ein Angriff in der Warteschlange behält seine eigene Farbe. Nicht mit dem Daylight-Verlauf."
L["Every header in this one color."] = "Jede Überschrift in dieser einen Farbe."
L["Every health bar's color when Health bar color is One color."] = "Farbe jeder Gesundheitsleiste, wenn Gesundheitsleistenfarbe auf Eine Farbe steht."
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "Jeder Gegenstand, den du auf eine Gruppe gezogen oder mit Alt-Rechtsklick verschoben hast, geht zurück in seine eigene Gruppe."
L["Every line in the tooltips. General uses the font on General > Appearance."] = "Jede Zeile in den Tooltips. Allgemein verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "Jede Zeile bleibt, bis die Zeit der neuesten abgelaufen ist, dann gehen alle. Wenn aus, verschwindet jede Zeile für sich."
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "Jede zweite Zeile auf einem schwachen Streifen, in den Werten und den langen Listen, damit Zeilen leichter zu verfolgen sind."
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "Jeder Teil von DaylightUI und was er tut. Schalte aus, was du nicht willst; das gilt beim Neuladen."
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "Fade jedes Teils an einem Ort. Jedes ist dieselbe Einstellung wie auf der eigenen Seite dieses Teils."
L["Every power bar's color when Power bar color is One color."] = "Farbe jeder Ressourcenleiste, wenn Ressourcenleistenfarbe auf Eine Farbe steht."
L["Every quest in your log"] = "Jede Quest in deinem Log"
L["Every quest title's color while Quest title color is set to One color."] = "Farbe jedes Questtitels, während Questtitelfarbe auf Eine Farbe steht."
L["Every reward earned."] = "Jede verdiente Belohnung."
L["Every setting for this piece"] = "Jede Einstellung für dieses Teil"
L["Every text in the loot feed. General uses the font on General > Appearance."] = "Jeder Text im Beute-Feed. Allgemein verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["Every text in the quest tracker. General uses the font on General > Appearance."] = "Jeder Text im Questverfolger. Allgemein verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["Every texture"] = "Jede Textur"
L["Every tracked quest, only the zone you're in, or every quest in your log without tracking them. The controls over the list switch the first two."] = "Jede verfolgte Quest, nur die Zone, in der du bist, oder jede Quest in deinem Log ohne sie zu verfolgen. Die Steuerelemente über der Liste schalten die ersten beiden um."
