L["Fade everything at the campfire"] = "Alles am Lagerfeuer ausblenden"
L["Fade in"] = "Einblenden"
L["Fade in combat"] = "Im Kampf ausblenden"
L["Fade in on login"] = "Beim Login einblenden"
