L["Fade other plates"] = "Andere Plaketten ausblenden"
L["Fade out"] = "Ausblenden"
L["Fade out of combat"] = "Außerhalb des Kampfes ausblenden"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "Fade außerhalb des Kampfes: blendet eine Weile nach dem Kampf aus und kommt im Kampf zurück. Fade im Kampf: blendet eine Weile in den Kampf hinein aus und kommt danach zurück. Fade bis Mouseover: bleibt ausgeblendet, bis die Maus darüber ist. Nur wenn sich etwas ändert: weg außerhalb des Kampfes, zurück im Kampf, und kurz zurück, wenn sich etwas ändert (Stärkungszauber gewonnen oder verloren, Gesundheit, Questfortschritt, EP)."
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "Fade außerhalb des Kampfes: blendet eine Weile nach dem Kampf aus und kommt im Kampf zurück. Fade im Kampf: blendet eine Weile in den Kampf hinein aus und kommt danach zurück. Fade bis Mouseover: bleibt ausgeblendet, bis die Maus darüber ist. Nur wenn sich etwas ändert: weg außerhalb des Kampfes, zurück im Kampf, und kurz zurück, wenn sich etwas ändert (Stärkungszauber gewonnen oder verloren, Gesundheit, Questfortschritt, EP). Versteckt (im Kampf, außerhalb des Kampfes oder immer): weg, und seine Buttons können nicht geklickt werden."
L["Fade the UI while talking"] = "Die UI während des Sprechens ausblenden"
L["Fade the icon"] = "Das Symbol ausblenden"
L["Fade to"] = "Ausblenden zu"
L["Fade until mouseover"] = "Ausblenden bis Mouseover"
L["Fade when out of range"] = "Ausblenden wenn außer Reichweite"
L["Faded opacity"] = "Deckkraft im ausgeblendeten Zustand"
L["Fades only while your health is full; comes back as soon as it drops. Show on mouseover still works."] = "Blendet nur aus, während deine Gesundheit voll ist; kommt zurück, sobald sie sinkt. Bei Mouseover anzeigen funktioniert weiter."
L["Fades only while your pet's health is full; comes back as soon as it drops. Show on mouseover still works."] = "Blendet nur aus, während die Gesundheit deines Begleiters voll ist; kommt zurück, sobald sie sinkt. Bei Mouseover anzeigen funktioniert weiter."
