L["Glows while the buff is down, to remind you to cast it, wherever it keeps its spot (Keep its spot, above)."] = "Leuchtet, während der Stärkungszauber abgelaufen ist, um dich an das Wirken zu erinnern, wo immer er seinen Platz behält (Platz behalten, oben)."
