L["Glows while the spell is off cooldown."] = "Leuchtet, während der Zauber außer Abklingzeit ist."
L["Glows while you can cast it and it's off cooldown: Revenge after a block, dodge or parry, Overpower after a dodge, Execute on a low target."] = "Leuchtet, während du es wirken kannst und es außer Abklingzeit ist: Rache nach Block, Ausweichen oder Parieren, Überwältigen nach Ausweichen, Hinrichten auf einem niedrigen Ziel."
