L["Hide cooldown swipe"] = "Abklingzeit-Sweep verstecken"
L["Hide duration swipe"] = "Dauer-Sweep verstecken"
L["Hide global cooldown swipe"] = "Globale Abklingzeit-Sweep verstecken"
L["Hide gold-seller adverts"] = "Goldverkäufer-Werbung verstecken"
L["Hide keeps its gap: the other spells don't move."] = "Verstecken behält den Abstand: die anderen Zauber bewegen sich nicht."
L["Hide lower ranks"] = "Niedrigere Ränge verstecken"
L["Hide repeated messages"] = "Wiederholte Nachrichten verstecken"
L["Hide shows the spell only while it's on cooldown. It keeps its gap: the other spells don't move."] = "Verstecken zeigt den Zauber nur, während er auf Abklingzeit ist. Es behält den Abstand: die anderen Zauber bewegen sich nicht."
L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "Verstecken zeigt den Zauber nur während der Abklingzeit. Nur wenn nutzbar zeigt ihn, sobald du ihn wirken kannst: Riposte nach Parieren, Überwältigen nach Ausweichen, Hinrichten auf niedrigem Ziel. Beide behalten die Lücke: die anderen Zauber bewegen sich nicht."
L["Hide while mounted"] = "Beim Reiten verstecken"
L["Hides the higher raid groups, e.g. 4 for a 20-player raid."] = "Versteckt die höheren Schlachtzugsgruppen, z. B. 4 für einen 20-Spieler-Schlachtzug."
L["Hides the number while a minute or more is left, so long buffs stay quiet."] = "Versteckt die Zahl, solange eine Minute oder mehr übrig ist, damit lange Stärkungszauber ruhig bleiben."
L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "Versteckt den roten Text und die Sprachzeile beim zu frühen Drücken eines Buttons: nicht genug Wut, Mana oder Energie, noch nicht bereit, außer Reichweite, kein Ziel. Die nützlichen erscheinen weiter: Taschen voll, interrupted, Sichtlinie, Questnachrichten."
L["Hiding"] = "Verstecken"
L["Highlight"] = "Hervorheben"
L["Highlight color"] = "Hervorhebungsfarbe"
L["Highlights a spell that is active (an aura, auto attack, a stance) or being cast."] = "Hebt einen Zauber hervor, der aktiv ist (eine Aura, Auto-Angriff, eine Haltung) oder gerade gewirkt wird."
