L["Hooked right of %s"] = "Eingehängt rechts von %s"
L["Horizontal (light at the full end)"] = "Horizontal (hell am vollen Ende)"
L["Hostile"] = "Feindlich"
L["Hover a button and press a key to bind it, or Escape to clear it. Click Okay when you're done. Out of combat only."] = "Über einen Button hovern und eine Taste drücken zum Binden, oder Escape zum Löschen. Okay klicken, wenn fertig. Nur außerhalb des Kampfes."
L["Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Überfahre eine Einstellung, um zu sehen, was sie macht; der Pfeil neben einer geänderten Einstellung setzt sie zurück."
L["Hover delay (seconds)"] = "Hover-Verzögerung (Sekunden)"
L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "Darüber hovern für Buttons: den Kampf (gesamt, aktuell und frühere Kämpfe nach Name), den Modus und Zurücksetzen."
L["Hovering a Questie icon on the map or minimap, or a quest in the quest log, makes that quest's icons a little bigger and fades the other quests' icons."] = "Über ein Questie-Symbol auf Karte oder Minikarte oder eine Quest im Questlog hovern macht die Symbole dieser Quest etwas größer und blendet die Symbole der anderen Quests aus."
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. Off shows it at the mouse."] = "Über eine Quest im Questlog hovern zeigt ihren Tooltip neben dem Log, wie das eigene Log des Spiels. Aus zeigt ihn an der Maus."
L["Hovering an item, spell or quest link in chat shows its tooltip, just above the chat."] = "Überfahren eines Gegenstands-, Zauber- oder Quest-Links im Chat zeigt seinen Tooltip, direkt über dem Chat."
L["Hovering an item, spell or quest link in chat shows its tooltip. Off, clicking a link still opens it."] = "Über einen Gegenstands-, Zauber- oder Quest-Link im Chat hovern zeigt seinen Tooltip. Wenn aus, öffnet Klicken den Link weiterhin."
L["How big a crit on you pops. It starts at half this and settles back. The game's own is 60."] = "Wie groß ein Kritischer Treffer auf dich poppt. Er startet bei der Hälfte und setzt sich zurück. Der des Spiels ist 60."
L["How big each buff icon is."] = "Wie groß jedes Stärkungszauber-Symbol ist."
L["How big each debuff icon is."] = "Wie groß jedes Schwächungszauber-Symbol ist."
L["How big each icon is."] = "Wie groß jedes Symbol ist."
L["How big each item slot is in the Bank and alts window."] = "Wie groß jeder Gegenstandsplatz im Bank- und Alts-Fenster ist."
L["How big each item slot is in the bag."] = "Wie groß jeder Gegenstandsplatz in der Tasche ist."
L["How big each item slot is in the bank."] = "Wie groß jeder Gegenstandsplatz in der Bank ist."
L["How big every square is."] = "Wie groß jedes Quadrat ist."
L["How big it is, as a percent of its normal size. This is Edit Mode's own size setting, kept in your Edit Mode layout."] = "Wie groß es ist, als Prozent seiner normalen Größe. Das ist die eigene Größeneinstellung des Edit Mode, in deinem Edit-Mode-Layout behalten."
L["How big the PvP flag is."] = "Wie groß die PvP-Flagge ist."
L["How big the arrow is on your screen, yards text included."] = "Wie groß der Pfeil auf deinem Bildschirm ist, Meter-Text inklusive."
L["How big the clock is."] = "Wie groß die Uhr ist."
L["How big the corner crown is."] = "Wie groß die Eckenkrone ist."
L["How big the crowd control icon is."] = "Wie groß das Kontrollverlust-Symbol ist."
L["How big the data texts are."] = "Wie groß die Datentexte sind."
L["How big the dispellable debuff's icon is."] = "Wie groß das Symbol des dispellbaren Schwächungszaubers ist."
L["How big the framerate is."] = "Wie groß die Bildrate ist."
L["How big the health text is on this frame."] = "Wie groß der Gesundheitstext auf diesem Rahmen ist."
L["How big the health text on the tiles is."] = "Wie groß der Gesundheitstext auf den Kacheln ist."
L["How big the icons of buffs you can purge or steal are."] = "Wie groß die Symbole von Stärkungszaubern sind, die du entfernen oder stehlen kannst."
L["How big the item names, counts and skill-up text are in the loot feed."] = "Wie groß die Gegenstandsnamen, Anzahlen und Fertigkeitssteigerungstexte im Beute-Feed sind."
L["How big the large health number is."] = "Wie groß die große Gesundheitszahl ist."
L["How big the leader crown is."] = "Wie groß die Anführerkrone ist."
L["How big the leader's crown is."] = "Wie groß die Krone des Anführers ist."
L["How big the name is on this frame."] = "Wie groß der Name auf diesem Rahmen ist."
L["How big the names on the tiles are."] = "Wie groß die Namen auf den Kacheln sind."
L["How big the pets' health text is."] = "Wie groß der Gesundheitstext der Begleiter ist."
L["How big the pets' names are."] = "Wie groß die Namen der Begleiter sind."
L["How big the portrait ring is next to the frame's height."] = "Wie groß der Porträtring im Verhältnis zur Rahmenhöhe ist."
L["How big the quest marker is in the world, distance text included."] = "Wie groß der Questmarker in der Welt ist, Entfernungstext inklusive."
L["How big the raid marker is."] = "Wie groß der Schlachtzugsmarker ist."
L["How big the ready check answer is."] = "Wie groß die Antwort auf den Bereitschaftscheck ist."
L["How big the resting Zzz is."] = "Wie groß das Ruhe-Zzz ist."
L["How big the role icon is."] = "Wie groß das Rollensymbol ist."
L["How big the round badge of an enemy pet or totem is."] = "Wie groß das runde Abzeichen eines feindlichen Begleiters oder Totems ist."
L["How big the square minimap is."] = "Wie groß die quadratische Minikarte ist."
L["How big the window is."] = "Wie groß das Fenster ist."
L["How big the window is. Other windows still open beside it when they fit."] = "Wie groß das Fenster ist. Andere Fenster öffnen sich weiterhin daneben, wenn sie passen."
L["How big this extra text is."] = "Wie groß dieser zusätzliche Text ist."
L["How big your buff icons on friendly plates are."] = "Wie groß deine Stärkungszauber-Symbole auf freundlichen Plaketten sind."
L["How big your debuff icons are."] = "Wie groß deine Schwächungszauber-Symbole sind."
L["How bright the light behind the arrow is."] = "Wie hell das Licht hinter dem Pfeil ist."
L["How bright the pips you haven't filled are, as a share of their color. Lower makes the filled ones stand out more."] = "Wie hell die noch nicht gefüllten Punkte sind, als Anteil ihrer Farbe. Niedriger lässt die gefüllten mehr hervorstechen."
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "Wie hell die unerforschten Gebiete sind. Bei 100% sehen sie aus wie die erforschten Teile."
L["How dark the shade that sweeps over a button on cooldown is."] = "Wie dunkel die Schattierung ist, die über einen Button auf Abklingzeit wischt."
L["How dark the shadow around DaylightUI's frames and windows is."] = "Wie dunkel der Schatten um die Rahmen und Fenster von DaylightUI ist."
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set right here. A queued attack always keeps its own color."] = "Wie die Leiste jeder Hand gefüllt ist: je eine Farbe, der Daylight-Verlauf (vom Blau zum Orange des Logos) oder ein zweistufiger Verlauf pro Hand, hier eingestellt. Ein Angriff in der Warteschlange behält immer seine eigene Farbe."
L["How every cast bar (yours, target's, focus's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set right here."] = "Wie jede Zauberleiste (deine, die des Ziels, die des Fokus) gefüllt ist: je eine Farbe, der Daylight-Verlauf (vom Blau zum Orange des Logos) oder ein zweistufiger Verlauf pro Zauberart, hier eingestellt."
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "Wie weit über dem Cursor die Ecke des Tooltips sitzt (unter null: weiter unten)."
L["How far along that quest objective is (4/10, or 45%), small, beside the !."] = "Wie weit dieses Questziel fortgeschritten ist (4/10 oder 45%), klein, neben dem !."
L["How far away plates show, in yards. 60 is the most the game allows."] = "Wie weit Plaketten angezeigt werden, in Metern. 60 ist das Maximum, das das Spiel erlaubt."
L["How far away the spot is."] = "Wie weit der Ort entfernt ist."
L["How far from the target the numbers start."] = "Wie weit vom Ziel die Zahlen starten."
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "Wie weit es ausblendet. Bei 0 verschwindet es vollständig. Nie mehr als Deckkraft."
L["How far past the name and bar a click still selects the unit."] = "Wie weit über den Namen und die Leiste hinaus ein Klick die Einheit noch auswählt."
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "Wie weit rechts vom Cursor die Ecke des Tooltips sitzt (unter null: nach links)."
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "Wie weit die Kamera herauszoomen kann. 100% ist das normale Limit des Spiels; das rechte Ende ist so weit, wie dieser Client erlaubt. Bei 100% wird die Einstellung des Spiels nicht verändert."
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "Wie weit die abgeschrägten Enden der Rahmen neigen, auf jedem Einheitenrahmen und jeder Zauberleiste. 21% ist das übliche Aussehen."
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "Wie weit der Schatten des Namens-Tabs sich ausbreitet. 0 hinterlässt keinen Schatten."
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "Wie weit die Zahlen zu den Seiten fliegen. Bei 0 gehen sie gerade nach oben, wie im Spiel."
L["How far the panel reaches past the buttons on every side."] = "Wie weit das Panel über die Buttons auf jeder Seite hinausreicht."
L["How far the soft shadow around DaylightUI's frames and windows reaches."] = "Wie weit der weiche Schatten um die Rahmen und Fenster von DaylightUI reicht."
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "Wie weit der Schatten dieses Rahmens sich ausbreitet. 0 hinterlässt keinen Schatten."
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "Wie weit du in der Stufe bist, z. B. 24%. Mit den Zahlen an sitzt es zwischen ihnen und der ausgeruhten EP."
L["How far through the standing you are, e.g. 60%."] = "Wie weit du im Rang bist, z. B. 60%."
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "Wie Gesundheits- und Ressourcenzahlen auf Einheitenrahmen, Extra-Texten und Namensplaketten geschrieben werden. Prozente bleiben wie sie sind."
L["How long a line stays on screen before it fades away."] = "Wie lange eine Zeile auf dem Bildschirm bleibt, bevor sie ausblendet."
L["How long a new item stays in Recent before it goes to its own group."] = "Wie lange ein neuer Gegenstand in Kürzlich bleibt, bevor er in seine eigene Gruppe geht."
L["How long a new whisper's preview stays."] = "Wie lange die Vorschau eines neuen Flüsterns bleibt."
L["How long each buff and debuff has left, on the top edge of its icon."] = "Wie lange jeder Stärkungs- und Schwächungszauber noch hat, am oberen Rand seines Symbols."
L["How long each line stays after your last loot of it."] = "Wie lange jede Zeile bleibt, nachdem du ihn zuletzt geplündert hast."
L["How long it stays before fading, unless the buffs land first."] = "Wie lange es bleibt, bevor es ausblendet, es sei denn, die Stärkungszauber landen zuerst."
L["How long the mouse rests on a link before its tooltip shows, so sweeping across the chat leaves it quiet."] = "Wie lange die Maus auf einem Link ruht, bevor sein Tooltip erscheint, damit schnelles Überfahren des Chats ruhig bleibt."
L["How low the enemy's health has to be."] = "Wie niedrig die Gesundheit des Feindes sein muss."
L["How many bars sit on your screen. Each one can be changed on its own later."] = "Wie viele Leisten auf deinem Bildschirm sitzen. Jede kann später einzeln geändert werden."
L["How many buttons this bar shows."] = "Wie viele Buttons diese Leiste zeigt."
L["How many data texts share the strip. Pick what each shows under Slots."] = "Wie viele Datentexte den Streifen teilen. Unter Plätze wählen, was jeder zeigt."
L["How many of the newest messages per chat tab come back after /reload."] = "Wie viele der neuesten Nachrichten pro Chat-Tab nach /reload zurückkommen."
L["How many people's tiles slide out beside the chat at most."] = "Wie viele Kacheln von Personen höchstens neben dem Chat herausgleiten."
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "In wie viele Reihen die Buttons umbrechen (Spalten, wenn die Leiste vertikal ist)."
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "Wie viele Plätze in jede Reihe der Tasche passen. Mehr Spalten machen sie breiter und kürzer."
L["How many yards away it is."] = "Wie viele Meter entfernt es ist."
L["How much a block, absorb or resist saved you."] = "Wie viel ein Block, Absorbieren oder Widerstehen dich gerettet hat."
L["How much color the empty part of a bar keeps."] = "Wie viel Farbe der leere Teil einer Leiste behält."
L["How much of the health bar's width the row spans, centered."] = "Wie viel von der Breite der Gesundheitsleiste die Reihe überspannt, zentriert."
L["How much the shield can still soak, at the bar's right end."] = "Wie viel der Schild noch absorbieren kann, am rechten Ende der Leiste."
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "Wie viel der Schild noch absorbieren kann, auf dem Symbol anstelle seiner Zeit. Größe und Farbe sind die der Abklingzeit-Zahlen."
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "Wie Zielzeilen ihren Fortschritt zeigen: in den Farben darunter, grün wenn erledigt, oder von rot nach grün schattierend, wenn die Anzahl sich füllt."
L["How round the name tab's corners are. 0 keeps them sharp."] = "Wie rund die Ecken des Namens-Tabs sind. 0 hält sie scharf."
L["How round this frame's corners are. 0 keeps them sharp."] = "Wie rund die Ecken dieses Rahmens sind. 0 hält sie scharf."
L["How see-through a frame gets while its unit is out of range."] = "Wie durchsichtig ein Rahmen wird, während seine Einheit außer Reichweite ist."
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "Wie durchsichtig ein auf Fade gesetzter Zauber wird, bereit oder auf Abklingzeit."
L["How see-through a spell set to Fade gets."] = "Wie durchsichtig ein auf Fade gesetzter Zauber wird."
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "Wie durchsichtig das Symbol eines Zaubers ist, während er auf Abklingzeit ist. Die globale Abklingzeit zählt nicht."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "Wie durchsichtig jedes Fenster und Panel ist: Taschen, Charakter, Zauberbuch, NSC, Gruppensucher, die Fenster des Spiels, die wir umstylen, und Chat, das Info-Panel, die Questbox und die Stärkungszauber-Leisten, sofern sie keine separate auf ihren Seiten haben."
L["How see-through it is while shown, whatever the fade does."] = "Wie durchsichtig es ist, während es angezeigt wird, egal was der Fade macht."
L["How see-through it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "Wie durchsichtig es ist, wann es ausblendet und wie weit. Entsperrt, im Testmodus oder bei geöffneter Seite zeigt es mit seiner Deckkraft."
L["How see-through party and raid frames get while a member is out of range."] = "Wie durchsichtig Gruppen- und Schlachtzugsrahmen werden, während ein Mitglied außer Reichweite ist."
L["How see-through the borders around DaylightUI's frames and windows are."] = "Wie durchsichtig die Ränder um die Rahmen und Fenster von DaylightUI sind."
L["How see-through the info panel's boxes and the meters' own windows are."] = "Wie durchsichtig die Boxen des Info-Panels und die eigenen Fenster der Meter sind."
L["How see-through the other plates get while you have a target."] = "Wie durchsichtig die anderen Plaketten werden, während du ein Ziel hast."
L["How see-through the world map's symbols are. Lower it to see more of the map under them."] = "Wie durchsichtig die Symbole der Weltkarte sind. Senke es, um mehr von der Karte darunter zu sehen."
L["How should it look?"] = "Wie soll es aussehen?"
L["How solid its background is: 0 is fully see-through."] = "Wie solid sein Hintergrund ist: 0 ist vollständig durchsichtig."
L["How solid the dark background is."] = "Wie solid der dunkle Hintergrund ist."
L["How solid the quest log's background is. Lower lets the world show through behind the list."] = "Wie solid der Hintergrund des Questlogs ist. Niedriger lässt die Welt hinter der Liste durchscheinen."
L["How solid the ribbon behind each loot feed line is: 0 is fully see-through."] = "Wie solid das Band hinter jeder Beute-Feed-Zeile ist: 0 ist vollständig durchsichtig."
L["How strong the highlight on an active spell is."] = "Wie stark die Hervorhebung auf einem aktiven Zauber ist."
L["How strong the mouseover color over the icon is."] = "Wie stark die Mouseover-Farbe über dem Symbol ist."
L["How strong the pressed color over the icon is."] = "Wie stark die gedrückte Farbe über dem Symbol ist."
L["How strongly it lights up once the enemy is in range."] = "Wie stark es aufleuchtet, sobald der Feind in Reichweite ist."
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "Wie stark die Farbe des Schwächungszaubers die Gesundheitsleiste tönen. Nur für eine Tönung- oder Beide-Hervorhebung."
L["How strongly the spell cost shows on your power bar."] = "Wie stark die Zauberkosten auf deiner Ressourcenleiste angezeigt werden."
L["How tall a friendly plate's health bar is."] = "Wie hoch die Gesundheitsleiste einer freundlichen Plakette ist."
L["How tall each enemy plate's health bar is."] = "Wie hoch die Gesundheitsleiste jeder feindlichen Plakette ist."
L["How tall each line of text over you is. The game's own is 25."] = "Wie hoch jede Textzeile über dir ist. Die des Spiels ist 25."
L["How tall each of the threat meter's bars is."] = "Wie hoch jede Leiste des Bedrohungsmeters ist."
L["How tall each of this meter's bars is."] = "Wie hoch jede Leiste dieses Meters ist."
L["How tall each pet bar is."] = "Wie hoch jede Begleiterleiste ist."
L["How tall each quest's row is in the quest log. Larger text keeps enough room however low this is set."] = "Wie hoch jede Quest-Zeile im Questlog ist. Größerer Text behält genug Platz, egal wie niedrig das gesetzt ist."
L["How tall each raid tile is."] = "Wie hoch jede Schlachtzugskachel ist."
L["How tall each swing timer bar is."] = "Wie hoch jede Schlag-Timer-Leiste ist."
L["How tall each tile's power bar is."] = "Wie hoch die Ressourcenleiste jeder Kachel ist."
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height."] = "Wie hoch die Gesundheitsleiste jeder anderen Plakette ist, während du ein Ziel hast, als Anteil der Gesundheitsleisten-Höhe."
L["How tall the cast bar under an enemy plate is."] = "Wie hoch die Zauberleiste unter einer feindlichen Plakette ist."
L["How tall the experience bar is."] = "Wie hoch die Erfahrungsleiste ist."
L["How tall the health bar is."] = "Wie hoch die Gesundheitsleiste ist."
L["How tall the health bar under the tooltip is."] = "Wie hoch die Gesundheitsleiste unter dem Tooltip ist."
L["How tall the meter's own window is."] = "Wie hoch das eigene Fenster des Meters ist."
L["How tall the pets' power bars are."] = "Wie hoch die Ressourcenleisten der Begleiter sind."
L["How tall the power bar is."] = "Wie hoch die Ressourcenleiste ist."
L["How tall the reputation bar is."] = "Wie hoch die Rufleiste ist."
L["How tall the second meter's window is."] = "Wie hoch das Fenster des zweiten Meters ist."
L["How tall the tab holding the name above the frame is."] = "Wie hoch der Tab ist, der den Namen über dem Rahmen hält."
L["How tall this frame is."] = "Wie hoch dieser Rahmen ist."
L["How tall your cast bar is."] = "Wie hoch deine Zauberleiste ist."
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Wie hoch die Zauberleiste deines Fokus ist. Nicht im Rahmen, wo sie den Platz der Ressourcenleiste einnimmt."
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "Wie hoch die Zauberleiste deines Ziels ist. Nicht im Rahmen, wo sie den Platz der Ressourcenleiste einnimmt."
L["How tall your target's health bar is, as a share of Health bar height."] = "Wie hoch die Gesundheitsleiste deines Ziels ist, als Anteil der Gesundheitsleisten-Höhe."
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "Wie der Gesundheitstext auf freundlichen Plaketten gelesen wird: ein Prozent, die Gesundheit selbst, Gesundheit von max, beides, oder was fehlt."
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "Wie der Gesundheitstext gelesen wird: ein Prozent, die Gesundheit selbst, Gesundheit von max, beides, oder was fehlt."
L["How the pets' health text is written."] = "Wie der Gesundheitstext der Begleiter geschrieben ist."
L["How the power text is written."] = "Wie der Ressourcentext geschrieben ist."
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "Wie der Gesundheitstext der Kacheln geschrieben wird. Fehlende Gesundheit zeigt nichts, während das Mitglied voll ist."
L["How thick the border around each button is."] = "Wie dick der Rand um jeden Button ist."
L["How thick the name tab's outline is. 0 leaves none."] = "Wie dick der Umriss des Namens-Tabs ist. 0 hinterlässt keinen."
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "Wie die Stärkungszauber dieser Kategorie umrandet sind: eine Farbe oder ein Verlauf. Klicken zum Ändern."
L["How this extra text writes the health."] = "Wie dieser zusätzliche Text die Gesundheit schreibt."
L["How this extra text writes the power."] = "Wie dieser zusätzliche Text die Ressource schreibt."
L["How wide a friendly plate's health bar is."] = "Wie breit die Gesundheitsleiste einer freundlichen Plakette ist."
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "Wie breit jeder Combopunkt-Punkt ist. Nicht, während die Punkte der Rahmenbreite entsprechen."
L["How wide each enemy plate's health bar is."] = "Wie breit die Gesundheitsleiste jeder feindlichen Plakette ist."
L["How wide each pet bar is."] = "Wie breit jede Begleiterleiste ist."
L["How wide each raid tile is."] = "Wie breit jede Schlachtzugskachel ist."
L["How wide every other plate is while you have a target, as a share of Width."] = "Wie breit jede andere Plakette ist, während du ein Ziel hast, als Anteil der Breite."
L["How wide the bars are."] = "Wie breit die Leisten sind."
L["How wide the damage meter is, in the panel or in its own window."] = "Wie breit der Schadensmeter ist, im Panel oder in seinem eigenen Fenster."
L["How wide the list is."] = "Wie breit die Liste ist."
L["How wide the name tab is when Name tab width is Fixed width."] = "Wie breit der Namens-Tab ist, wenn Namens-Tab-Breite auf Feste Breite steht."
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "Wie breit die Rufleiste ist. Das Ziehen ihrer Ecke im Entsperrmodus setzt das auch."
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "Wie breit das Fenster des zweiten Meters ist. Das Ziehen seiner Ecke im Entsperrmodus setzt das auch."
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "Wie breit die separate Erfahrungsleiste ist. Das Ziehen ihrer Ecke im Entsperrmodus setzt das auch."
L["How wide the threat meter is."] = "Wie breit der Bedrohungsmeter ist."
L["How wide this frame is."] = "Wie breit dieser Rahmen ist."
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Wie breit die Zauberleiste deines Fokus ist. Nicht im Rahmen, oder während sie der Rahmenbreite entspricht."
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "Wie breit die Zauberleiste deines Ziels ist. Nicht im Rahmen, oder während sie der Rahmenbreite entspricht."
L["How wide your target's plate is, as a share of Width."] = "Wie breit die Plakette deines Ziels ist, als Anteil der Breite."
L["How you find your way to quests, and how they show in the tracker."] = "Wie du den Weg zu Quests findest und wie sie im Verfolger angezeigt werden."
L["How you find your way to quests, how they show in the tracker, and how talking to NPCs looks."] = "Wie du den Weg zu Quests findest, wie sie im Verfolger erscheinen und wie das Sprechen mit NSCs aussieht."
L["How your target's plate stands out from the rest."] = "Wie die Plakette deines Ziels sich vom Rest abhebt."
L["Hunter"] = "Jäger"
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "Jäger: eine Linie auf der Fernkampfleiste, wo der Aufladebeginn von Automatischer Schuss startet, angepasst an Tempo und Ping. Darüber bewegen hält den Schuss zurück, sodass die Leiste voll bleibt und Stopp bewegen sagt, bis du stillstehst."
L["I'd like to train."] = "Ich möchte trainieren."
L["I'm away right now, I'll get back to you soon."] = "Ich bin gerade nicht da, ich melde mich bald zurück."
L["INTERRUPTS"] = "UNTERBRECHUNGEN"
L["Icon"] = "Symbol"
L["Icon (the game's)"] = "Symbol (das des Spiels)"
L["Icon look"] = "Symbol-Aussehen"
L["Icon per class"] = "Symbol pro Klasse"
L["Icon positions and sizes"] = "Symbolpositionen und -größen"
L["Icon size"] = "Symbolgröße"
L["Icon style"] = "Symbolstil"
L["Icon zoom"] = "Symbolzoom"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "Symbole füllen sich vom rechten Rand der Leiste nach links, zur Bildschirmmitte hin."
L["Icons left / right"] = "Symbole links / rechts"
L["Icons on a row before it wraps to the next."] = "Symbole in einer Reihe, bevor es zur nächsten umbricht."
L["Icons on bars"] = "Symbole auf Leisten"
L["Icons per row"] = "Symbole pro Reihe"
L["Icons up / down"] = "Symbole oben / unten"
L["Idle time (seconds)"] = "Leerlaufzeit (Sekunden)"
L["Ignore"] = "Ignorieren"
L["Ignored"] = "Ignoriert"
L["Immersive"] = "Immersiv"
L["Immersive Preset"] = "Immersives Preset"
L["Import"] = "Importieren"
L["Import profile"] = "Profil importieren"
L["Imported the profile %s."] = "Das Profil %s importiert."
L["In a dungeon or raid"] = "In einem Dungeon oder Schlachtzug"
L["In a fight"] = "In einem Kampf"
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "In einer Gruppe oder mit Begleiter ein kleines Tag an der oberen inneren Ecke des Rahmens: deine Bedrohung darauf, wobei 100% bedeutet, dass es sich dir zuwendet. Orange, wenn du näher kommst, rot, sobald es auf dir ist."
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "In einer Gruppe oder mit Begleiter wird der Ring des Ziels (und der Bedrohungs-Tag) diese Farbe, wenn du nahe am Pull bist."
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "In einer Gruppe färbt einen Mob danach, wen er angreift; Solo-Plaketten ändern sich nie. Als Tank: rot wenn er jemand anderen angreift, orange wenn du ihn gerade verlierst, normal während du ihn hältst. Als Schaden oder Heiler: orange wenn du nahe am Pull bist, rot sobald er dich angreift."
L["In a raid, only the leader and assists can use the leader tools."] = "In einem Schlachtzug können nur Anführer und Assistenten die Anführer-Werkzeuge nutzen."
L["In a row above the bar."] = "In einer Reihe über der Leiste."
L["In categories"] = "In Kategorien"
L["In columns"] = "In Spalten"
L["In combat"] = "Im Kampf"
L["In combat in a group or with a pet"] = "Im Kampf in einer Gruppe oder mit einem Begleiter"
L["In combat, when I'm the tank"] = "Im Kampf, wenn ich der Tank bin"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "In Dungeons, Schlachtzügen, Schlachtfeldern und Arenen bleibt alles, was auf Fade steht, sichtbar, als wäre sein Fade Nie. Es blendet wieder aus, sobald du wieder draußen bist."
L["In fights"] = "In Kämpfen"
L["In fights and when idle"] = "In Kämpfen und im Leerlauf"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "Im Kampf: Panel und Tabs schweben weg und die Nachrichten bleiben über der Welt. Im Leerlauf: der ganze Chat blendet auch aus, wenn eine Weile nichts Neues gekommen ist. Immer: kein Panel oder Tabs während du spielst, nur Nachrichten. Maus über dem Chat oder Enter bringt ihn zurück."
L["In progress"] = "In Bearbeitung"
L["In public channels (General, Trade, say...), the same words from the same person again within a minute are hidden. Guild, group and whispers are never hidden."] = "In öffentlichen Kanälen (Allgemein, Handel, Sagen...) werden dieselben Worte derselben Person innerhalb einer Minute erneut versteckt. Gilde, Gruppe und Flüstern werden nie versteckt."
L["In rows"] = "In Reihen"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "In Bildschirmpixeln, damit es bei jeder UI-Skalierung scharf bleibt. Dicker Rand braucht 3 oder mehr."
L["In the Daylight chat box (Chat style: Daylight)."] = "Im Daylight-Chat-Fenster (Chat-Stil: Daylight)."
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "Im Chat-Fenster gehen Hoch und Runter durch das, was du gesendet hast. Alt+Hoch und Alt+Runter funktionieren wie zuvor. Während das Fenster offen ist, drehen die Pfeiltasten deinen Charakter nicht."
L["In the group"] = "In der Gruppe"
L["In the info panel"] = "Im Info-Panel"
L["In the tooltip spot"] = "Am Tooltip-Platz"
L["In use"] = "In Verwendung"
L["In use: %s"] = "In Verwendung: %s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "In deiner Akzentfarbe (Aussehen), folgt ihr bei Änderungen. Wenn aus, wird die Farbe darunter genutzt."
L["In your layout: click to pick it."] = "In deinem Layout: klicke, um es zu wählen."
L["Inactive"] = "Inaktiv"
L["Inbox"] = "Posteingang"
L["Incoming heals"] = "Ankommende Heilungen"
L["Info"] = "Info"
L["Info Panel"] = "Info-Panel"
L["Info panel"] = "Info-Panel"
L["Info panel background opacity"] = "Deckkraft des Info-Panel-Hintergrunds"
L["Inner end"] = "Inneres Ende"
L["Inside the frame"] = "Im Rahmen"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "Im Rahmen bedeckt es die Ressourcenleiste, so breit wie sie (im Band-Stil sitzt es stattdessen unter dem Rahmen). Darüber, darunter oder für sich allein ist es eine Leiste, die du hier dimensionierst; für sich allein verschiebst du sie im Entsperrmodus."
L["Inspect"] = "Betrachten"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "Einen Spieler inspizieren öffnet das Fenster von DaylightUI mit ihrer Ausrüstung und Talenten. Ausschalten, um das Fenster des Spiels zu nutzen."
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "Installiere das Addon Jiberish Fabled Icons, um mehr Klassen-Symbolstile freizuschalten."
L["Instance"] = "Instanz"
L["Instance chat, used in battlegrounds and groups made by the group finder."] = "Instanz-Chat, genutzt in Schlachtfeldern und Gruppen vom Gruppensucher."
L["Instance color"] = "Instanzfarbe"
L["Intellect"] = "Intelligenz"
L["Interrupt animation"] = "Unterbrechungs-Animation"
L["Interrupted"] = "Unterbrochen"
L["Interrupted color"] = "Farbe für unterbrochen"
L["Interrupted gradient"] = "Unterbrochen-Verlauf"
L["Interrupts"] = "Unterbrechungen"
L["Into the Void"] = "In die Leere"
L["Inventory is full."] = "Inventar ist voll."
L["Invert gradients"] = "Verläufe umkehren"
L["Invite"] = "Einladen"
L["Ironforge"] = "Eisenschmiede"
L["It shows when the first meter would: the Damage meter page's \"Show only in a group\" and \"Show only in combat\" count for both. Reset clears the fights in both."] = "Es zeigt, wann der erste Meter es würde: „Nur in einer Gruppe anzeigen“ und „Nur im Kampf anzeigen“ der Schadensmeter-Seite gelten für beide. Zurücksetzen löscht die Kämpfe in beiden."
L["It slides back once the fight ends. A click on its tab overrides this until the next fight starts or ends."] = "Es gleitet zurück, sobald der Kampf endet. Ein Klick auf seinen Tab überschreibt das bis zum nächsten Kampfbeginn oder -ende."
L["It takes a reload."] = "Es braucht ein Neuladen."
L["It's %s. Just one more quest?"] = "Es ist %s. Nur noch eine Quest?"
L["Item"] = "Gegenstand"
L["Item ID"] = "Gegenstands-ID"
L["Item buttons"] = "Gegenstandsbuttons"
L["Item icons"] = "Gegenstandssymbole"
L["Item level"] = "Gegenstandsstufe"
L["Item level %s"] = "Gegenstandsstufe %s"
L["Item level line"] = "Gegenstandsstufen-Zeile"
L["Item names beside icons"] = "Gegenstandsnamen neben Symbolen"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "Gegenstandsnamen in ihrer Qualitätsfarbe oder alles weiß. Der Symbolrand behält die Qualitätsfarbe."
L["Item quality border"] = "Rand der Gegenstandsqualität"
L["Items"] = "Gegenstände"
L["Items and loot"] = "Gegenstände und Beute"
L["Items below this quality don't show, like gray junk."] = "Gegenstände unter dieser Qualität werden nicht angezeigt, wie grauer Schrott."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "Gegenstände nach Typ in Gruppen sortiert. Um einen Gegenstand in eine andere Gruppe zu verschieben, ziehe ihn auf die Überschrift dieser Gruppe oder Alt-Rechtsklick. Klicke auf eine Überschrift zum Einklappen. Alt-Rechtsklick sperrt auch einen Gegenstand, sodass er nie verkauft oder entzaubert wird."
L["Items that are uncommon or better get a border in their quality color."] = "Gegenstände, die ungewöhnlich oder besser sind, bekommen einen Rand in ihrer Qualitätsfarbe."
L["Items you loot, create, buy or get from a quest."] = "Gegenstände, die du plünderst, herstellst, kaufst oder von einer Quest bekommst."
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "Gegenstände, die deine Klasse, Stufe oder Fertigkeiten noch nicht nutzen können, oder die du schon kennst, bekommen ein rotes Symbol, wie beim Händler."
L["Itim"] = "Itim"
L["Its buff or debuff"] = "Sein Stärkungs- oder Schwächungszauber"
L["Its cooldown"] = "Seine Abklingzeit"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "Seine Options- und Meine-Reise-Fenster und seine Questziel-Symbole auf den Karten, jede Quest in eigener Farbe."
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "Eigener Fade, getrennt vom Panel. Bei geöffneter Seite zeigt es eine Beispielgruppe."
L["Its own window"] = "Sein eigenes Fenster"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Eigenes Fenster, anfangs in der unteren rechten Ecke. Im Entsperrmodus (/dui unlock) verschieben und an der Ecke ziehen zum Dimensionieren."
L["Its owner's class"] = "Die Klasse seines Besitzers"
L["Its owner's class tells at a glance whose pet it is."] = "Die Klasse seines Besitzers sagt auf einen Blick, wessen Begleiter es ist."
L["Its ring buttons in your action bar look. The ring, its spin and its options stay OPie's."] = "Seine Ring-Buttons im Aussehen deiner Aktionsleiste. Der Ring, seine Drehung und Optionen bleiben bei OPie."
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "Seine Timer-Leisten in deiner Schrift, Leistentextur und Rand. Größen, Farben und Plätze bleiben bei DBM."
L["Its window, and each attunement chain drawn like the talent trees."] = "Sein Fenster und jede Attunement-Kette, gezeichnet wie die Talentbäume."
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "Jiberish Fabled Icons ist installiert. Wähle unten ein Symbol für jede Klasse, einen beliebigen Stil oder eine ihrer Spezialisierungen. Das erste Symbol in jeder Zeile folgt dem Symbolstil."
L["Join a group to use the leader tools, or try them with /dui leader test."] = "Tritt einer Gruppe bei, um die Anführer-Werkzeuge zu nutzen, oder probiere sie mit /dui leader test."
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "Tritt dem DaylightUI-Discord bei: Strg+C zum Kopieren des Links, dann im Browser einfügen."
L["Junk"] = "Schrott"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Genau links vom Panel, auf Höhe seiner Oberkante, folgt ihm, wenn Minikarte oder Schadensmeter die Größe ändern. Ausschalten, um die Leiste selbst im Entsperrmodus zu verschieben."
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "Genau links vom Panel, die erste Reihe auf seiner Unterkante, folgt ihm, wenn Minikarte oder Schadensmeter die Größe ändern. Ausschalten, um die Leiste selbst im Entsperrmodus zu verschieben."
L["Just this spell, for now"] = "Nur dieser Zauber, vorerst"
