L["Keybinds, stack counts, macro names and cooldown numbers on every bar, the Cooldown Manager and totems. General uses the font on General > Appearance."] = "Tastenbelegungen, Stapelanzahlen, Makronamen und Abklingzeit-Zahlen auf jeder Leiste, dem Cooldown-Manager und Totems. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["Keys"] = "Tasten"
L["Kicked by"] = "Gekickt von"
L["Kinds: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nBinding: boe, bou, soulbound. In an equipment set: set, or the set's name. Locked: locked\nQuality: poor, common, uncommon, rare, epic, legendary, or q>rare, q>=uncommon, q<epic\nItem level: ilvl>20, ilvl<=10, ilvl20-30\nJoin with & (all) or | (any), ! for not: boe & q>common, food | potion, gear & !set\nA word that isn't one of these finds names. Start with # for the keyword only."] = "Arten: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nBindung: boe, bou, soulbound. In einem Ausrüstungsset: set, oder der Name des Sets. Gesperrt: locked\nQualität: poor, common, uncommon, rare, epic, legendary, oder q>rare, q>=uncommon, q<epic\nGegenstandsstufe: ilvl>20, ilvl<=10, ilvl20-30\nVerbinden mit & (alle) oder | (beliebig), ! für nicht: boe & q>common, food | potion, gear & !set\nEin Wort, das keines davon ist, findet Namen. Mit # beginnen nur für das Schlüsselwort."
