L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "Plünderbare Questobjekte funkeln, und Questgeber auch (das Spiel hat keine Einstellung für nur eines). Das Spiel funkelt nur mit seinem Umriss um das, worauf du zeigst, wenn aus – daher hält dies den Umriss aus. Ausschalten stellt den Umriss wieder her; das Funkeln kann bis zum Neustart des Spiels bleiben."
