L["Off hand gradient"] = "Nebenhand-Verlauf"
L["Officer"] = "Offizier"
L["Officer color"] = "Offiziersfarbe"
L["Offline"] = "Offline"
L["Okay"] = "Okay"
L["Old layout: %s, set %d"] = "Altes Layout: %s, Satz %d"
L["On a flight path, a bar at the top of the screen shows where you're going and the time left. Each route's time is learned the first time you fly it, for all your characters. Move it with /dui unlock."] = "Auf einem Flugpfad zeigt eine Leiste oben am Bildschirm, wohin du fliegst und die verbleibende Zeit. Die Zeit jeder Route wird beim ersten Flug gelernt, für alle deine Charaktere. Mit /dui unlock verschieben."
L["On a ready check, and when you enter a dungeon or raid in a group, a short line shows the group buffs you don't have yet: only ones someone in your group can give. It fades once they land. Move it in unlock mode."] = "Bei einem Bereitschaftscheck und wenn du in einer Gruppe einen Dungeon oder Schlachtzug betrittst, zeigt eine kurze Zeile die Gruppen-Stärkungszauber, die du noch nicht hast: nur die, die jemand in deiner Gruppe geben kann. Sie blendet aus, sobald sie landen. Im Entsperrmodus verschieben."
L["On cooldown"] = "Auf Abklingzeit"
L["On in the Healer setup. Each class has its own picks; change them below."] = "Im Heiler-Setup an. Jede Klasse hat eigene Auswahl; ändere sie unten."
L["On its own (unlock to move)"] = "Für sich allein (zum Verschieben entsperren)"
L["On its own, the power bar leaves the frame and you can move it anywhere in unlock mode, like the middle of the screen. The frame is then all health."] = "Für sich allein verlässt die Ressourcenleiste den Rahmen und du kannst sie im Entsperrmodus überallhin verschieben, z. B. in die Bildschirmmitte. Der Rahmen ist dann nur Gesundheit."
L["On the frame"] = "Auf dem Rahmen"
L["On the plate"] = "Auf der Plakette"
L["On the portrait"] = "Auf dem Porträt"
L["On the portrait rings of the player, target and focus frames."] = "Auf den Porträtringen der Spieler-, Ziel- und Fokus-Rahmen."
L["One click sets where the auras and the name sit. Change anything after."] = "Ein Klick setzt, wo die Auren und der Name sitzen. Danach alles änderbar."
L["One color"] = "Eine Farbe"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "Eine Farbe auf jedem Punkt; Farben von Combopunkt-Farbe zu Voller Farbe entlang der Reihe; deine Klassenfarbe; oder Zweifarb-Paare von der Verläufe-Seite (Combopunkte), eine für alle Punkte oder je eine. Die Combopunkte deiner Namensplaketten nutzen dieselben Farben."
L["One custom color, the accent, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Eine eigene Farbe, der Akzent, deine Klassenfarbe, oder die zwei Farben deiner Klasse als Verlauf (von der Verläufe-Seite)."
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "Eine eigene Farbe, deine Klassenfarbe, oder die zwei Farben deiner Klasse als Verlauf (von der Verläufe-Seite)."
L["One gradient (Gradients page)"] = "Ein Verlauf (Verläufe-Seite)"
L["One more thing at the end of the same line, after the second part."] = "Noch eine Sache am Ende derselben Zeile, nach dem zweiten Teil."
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "Eine Zeile pro Gruppenmitglied und deinem Begleiter auf der Bedrohungsliste deines Ziels, höchste zuerst, mit dir immer dabei. Der Prozentwert bezieht sich auf den Pull: bei 100% wendet es sich dir zu."
L["One switch per part of the game's windows."] = "Ein Schalter pro Teil der Spielfenster."
L["One tile with the count"] = "Eine Kachel mit der Anzahl"
L["One tile: each section of the bank shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Eine Kachel: jeder Abschnitt der Bank zeigt einen einzelnen leeren Platz mit der freien Anzahl darauf. Lege einen Gegenstand darauf, um ihn dort abzulegen."
L["One tile: each section shows a single empty slot with the free count on it."] = "Eine Kachel: jeder Abschnitt zeigt einen einzelnen leeren Platz mit der freien Anzahl darauf."
L["One tile: each section shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "Eine Kachel: jeder Abschnitt zeigt einen einzelnen leeren Platz mit der freien Anzahl darauf. Lege einen Gegenstand darauf, um ihn dort abzulegen."
L["Ones that matter in a fight"] = "Die, die im Kampf zählen"
L["Online"] = "Online"
L["Only at full health"] = "Nur bei voller Gesundheit"
L["Only clears this list. Moved buffs stay in their new categories."] = "Löscht nur diese Liste. Verschobene Stärkungszauber bleiben in ihren neuen Kategorien."
L["Only debuffs I can dispel"] = "Nur Schwächungszauber, die ich dispellen kann"
L["Only enemies"] = "Nur Feinde"
L["Only in a group"] = "Nur in einer Gruppe"
L["Only in combat"] = "Nur im Kampf"
L["Only mine"] = "Nur meine"
L["Only ones I can dispel"] = "Nur die, die ich dispellen kann"
L["Only spells you cast can be bound."] = "Nur Zauber, die du wirkst, können gebunden werden."
L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "Nur die Nachrichten des Chats bleiben über der Welt, jede blendet nach einer Weile aus, wie Schwebender Chat (Chat > Schwebend). Es bleibt auch bei „Alles ausblenden am Lagerfeuer“ an."
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "Nur die Schwächungszauber, die du darauf legst, oder zuerst deine und dann die der anderen."
L["Only under a minute"] = "Nur unter einer Minute"
L["Only when detached."] = "Nur wenn gelöst."
L["Only when detached. Main hand at the bottom, the others above it."] = "Nur wenn gelöst. Haupthand unten, die anderen darüber."
L["Only when detached. When attached, the bars match the cast bar's width."] = "Nur wenn gelöst. Wenn angehängt, passen die Leisten zur Breite der Zauberleiste."
L["Only when something changes"] = "Nur wenn sich etwas ändert"
L["Only while the power bar is on its own."] = "Nur während die Ressourcenleiste für sich allein ist."
L["Only while the power bar is on its own. When off, both ends are straight."] = "Nur während die Ressourcenleiste für sich allein ist. Wenn aus, sind beide Enden gerade."
L["Only with a target"] = "Nur mit einem Ziel"
L["Only your group's leader can change the listing."] = "Nur der Anführer deiner Gruppe kann den Eintrag ändern."
L["Only your group's leader can list the group."] = "Nur der Anführer deiner Gruppe kann die Gruppe listen."
L["Opacity"] = "Deckkraft"
L["Opacity & fade"] = "Deckkraft & Fade"
L["Opacity on cooldown"] = "Deckkraft auf Abklingzeit"
L["Open"] = "Öffnen"
L["Open DaylightUI options"] = "DaylightUI-Optionen öffnen"
L["Open a chat box first to link it."] = "Öffne zuerst ein Chat-Fenster, um es zu verlinken."
L["Open spot"] = "Offener Platz"
L["Open stat groups"] = "Wertegruppen öffnen"
L["Open this page at these settings."] = "Diese Seite mit diesen Einstellungen öffnen."
L["Open world only"] = "Nur offene Welt"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "Das Öffnen eines Briefkastens zeigt das Fenster von DaylightUI: deine Briefe, Senden und ein Buch über dein Gold. Ausschalten, um das Fenster des Spiels zu nutzen. Das Buch zählt in beiden Fällen weiter."
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "Das Öffnen eines Berufs zeigt das Fenster von DaylightUI: deine Rezepte links, das gewählte rechts. Im Kampf öffnet sich das eigene Fenster des Spiels. Ausschalten, um das Fenster des Spiels zu nutzen."
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "Das Öffnen eines Händlers verkauft alles in der Schrott-Gruppe: graue Gegenstände und alles, was du selbst zu Schrott verschoben hast. Der Chat zeigt, wie viel du bekommen hast."
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "Das Öffnen eines Händlers, der repariert, repariert deine gesamte Ausrüstung, und der Chat zeigt die Kosten. Nicht im Kampf."
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and DaylightUI's own windows."] = "Öffnen und Schließen von Fenstern: Taschen, Charakter, Zauberbuch, Questlog, das Spielmenü und die eigenen Fenster von DaylightUI."
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "Das Öffnen des Gruppensuchers zeigt das Fenster von DaylightUI: Gruppen zum Beitreten, dich selbst listen und wer da ist. Im Kampf öffnet sich das eigene Fenster des Spiels. Ausschalten, um das Fenster des Spiels zu nutzen."
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "Das Öffnen deiner Tasche füllt Teilstapel desselben Gegenstands auf (15 und 5 Leinenstoff werden 20), sodass kein Platz verschwendet wird. Nicht im Kampf, oder während du handelst oder Briefkasten oder Auktionshaus offen hast."
L["Opens the Gradients page, where the Combo points pairs are."] = "Öffnet die Verläufe-Seite, wo die Combopunkt-Paare sind."
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "Öffnet den Layout-Editor direkt auf dem Bildschirm: ziehe Zauber aus dem Fach, verschiebe sie wohin du willst, hake sie zusammen, klicke einen zum Ändern. Tippe /cdm, um ihn jederzeit zu öffnen. Nur außerhalb des Kampfes."
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "Öffnet dein Zauberbuch mit Click-Cast an: klicke einen Zauber mit der gewünschten Maustaste. Schließe das Zauberbuch, wenn du fertig bist, und diese Seite kommt zurück."
L["Option toggles"] = "Options-Schalter"
L["Options"] = "Optionen"
L["Options (%s): %s"] = "Optionen (%s): %s"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "Optionsfenster von Addons auf Ace3-Basis, in den Spieleinstellungen und ihren eigenen Fenstern: Questie, RestedXP und viele mehr."
L["Or drag the badge in Design mode."] = "Oder ziehe das Abzeichen im Design-Modus."
