L["Outlines the member you have targeted, so you can find them at a glance."] = "Umreißt das Mitglied, das du anvisiert hast, damit du es auf einen Blick findest."
L["Outside spots may need more space between frames."] = "Äußere Plätze brauchen vielleicht mehr Abstand zwischen Rahmen."
