L["Outside: top right"] = "Außerhalb: oben rechts"
L["Over an hour away. Still here, still waiting."] = "Über eine Stunde entfernt. Immer noch hier, immer noch wartend."
L["Over its owner"] = "Über seinem Besitzer"
L["Over or under the frame, the buffs sit nearest it when both share a spot. Outside spots may need room around the frame."] = "Über oder unter dem Rahmen sitzen die Stärkungszauber am nächsten daran, wenn beide einen Platz teilen. Äußere Plätze brauchen vielleicht Platz um den Rahmen."
L["Over, under or beside the health bar. In Design mode on the preview, drag it there."] = "Über, unter oder neben der Gesundheitsleiste. Im Design-Modus auf der Vorschau dorthin ziehen."
L["Over, under or beside the health bar. Rows sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Über, unter oder neben der Gesundheitsleiste. Reihen, die einen Platz teilen, ordnen sich von der Leiste nach außen. Im Design-Modus auf der Vorschau dorthin ziehen."
L["Over, under, beside or on a friendly plate's health bar. Without the health bar the name stays centered."] = "Über, unter, neben oder auf der Gesundheitsleiste einer freundlichen Plakette. Ohne Gesundheitsleiste bleibt der Name zentriert."
L["Over, under, beside or on the health bar. Pieces sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "Über, unter, neben oder auf der Gesundheitsleiste. Teile, die einen Platz teilen, ordnen sich von der Leiste nach außen. Im Design-Modus auf der Vorschau dorthin ziehen."
