L["Paste a DaylightUI profile (Ctrl+V) and name it. It becomes a new profile, chosen for this character (these talents, with dual spec); yours stay as they are."] = "Ein DaylightUI-Profil einfügen (Strg+V) und benennen. Es wird ein neues Profil, gewählt für diesen Charakter (diese Talente, mit Dual-Spec); deine bleiben wie sie sind."
L["Paste a talent string"] = "Einen Talent-String einfügen"
