L["Pick %d activities at most."] = "Höchstens %d Aktivitäten wählen."
L["Pick All bars to change every bar at once, or one bar to give it a look of its own."] = "Alle Leisten wählen, um jede auf einmal zu ändern, oder eine Leiste für ein eigenes Aussehen."
L["Pick a category to look for groups."] = "Eine Kategorie wählen, um nach Gruppen zu suchen."
