L["Pick a page on the left to shape your interface. Changes apply as you make them. Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "Links eine Seite wählen, um deine Oberfläche zu gestalten. Änderungen gelten sofort. Über eine Einstellung hovern, um zu sehen, was sie tut; der Pfeil neben einer geänderten Einstellung setzt sie zurück."
