L["Picks a whole set of colors at once. Colors you changed yourself are kept; a row's reset button sets it back to the palette."] = "Wählt einen ganzen Farbsatz auf einmal. Farben, die du selbst geändert hast, bleiben; der Zurücksetzen-Button einer Zeile setzt sie auf die Palette zurück."
