L["Player, target, party, raid and more."] = "Spieler, Ziel, Gruppe, Schlachtzug und mehr."
L["Players"] = "Spieler"
L["Players' and creatures' tooltips show while you're fighting. When off, they stay hidden in a fight; hold Shift to see one."] = "Tooltips von Spielern und Kreaturen erscheinen, während du kämpfst. Wenn aus, bleiben sie im Kampf versteckt; Umschalt halten, um einen zu sehen."
L["Players' last names after their first, on nameplates. Where the game hides names (in combat, in places) only the first name shows."] = "Nachnamen der Spieler nach dem Vornamen auf Namensplaketten. Wo das Spiel Namen versteckt (im Kampf, an Orten), erscheint nur der Vorname."
L["Players' last names after their first, on this frame only. Where the game hides names (in combat, in places) only the first name shows."] = "Nachnamen der Spieler nach dem Vornamen, nur auf diesem Rahmen. Wo das Spiel Namen versteckt (im Kampf, an Orten), erscheint nur der Vorname."
L["Players' last names after their first, on tooltips. Where the game hides names (in combat, in places) only the first name shows."] = "Nachnamen der Spieler nach dem Vornamen auf Tooltips. Wo das Spiel Namen versteckt (im Kampf, an Orten), erscheint nur der Vorname."
L["Players' last names after their first. When off, first names only, which fit the narrow rows better."] = "Nachnamen der Spieler nach dem Vornamen. Wenn aus, nur Vornamen, die besser in schmale Zeilen passen."
L["Players' names in their class color, in every kind of chat (the game's own setting)."] = "Spielernamen in ihrer Klassenfarbe, in jeder Chat-Art (eigene Einstellung des Spiels)."
