L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "1 bis 9 drücken, um eine Zeile oder Belohnung zu wählen, Leertaste für den nächsten Schritt (annehmen, fortfahren, abschließen), Escape zum Zurück. Leertaste springt nie, während du sprichst. Andere Tasten gehen weiter ans Spiel, und im Kampf ist jede Taste die des Spiels."
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "Binden im Zauberbuch drücken (oder %s öffnen und Click-Cast oben einschalten), dann einen Zauber mit der gewünschten Maustaste klicken (Umschalt, Strg oder Alt halten für mehr). Dieser Klick auf einen deiner Einheitenrahmen wirkt ihn dann auf diese Einheit. Zauberbuch schließen, wenn fertig: diese Seite kommt zurück. Linksklick zielt weiterhin und Rechtsklick öffnet das Menü, sofern du sie nicht gebunden hast."
