L["Puts this font on the game's own text as well: menus, tooltips, quest text, popups, nameplate names. Sizes and outlines stay the game's. Damage numbers follow it too, unless their own page picks a font."] = "Setzt diese Schrift auch auf den eigenen Text des Spiels: Menüs, Tooltips, Questtext, Popups, Namensplaketten-Namen. Größen und Umrisse bleiben die des Spiels. Schadenszahlen folgen ihr auch, sofern ihre eigene Seite keine Schrift wählt."
