L["Sets Visible to Only when something changes on every part that has it: gone out of a fight, back in one, and back for a moment when it changes. Turned off, each goes back to its default. Each part's own Visible on its page still works on its own."] = "Setzt Sichtbar auf Nur wenn sich etwas ändert bei jedem Teil, der das hat: weg außerhalb des Kampfes, zurück im Kampf, und kurz zurück, wenn sich etwas ändert. Ausgeschaltet geht jedes auf seinen Standard zurück. Das eigene Sichtbar jedes Teils auf seiner Seite funktioniert weiterhin für sich."
L["Sets every category to Combine, so each shows as one icon. Click None to set them all back."] = "Setzt jede Kategorie auf Kombinieren, sodass jede als ein Symbol erscheint. Auf Keine klicken, um alle zurückzusetzen."
L["Sets every pair back to the palette's colors. Gradient direction and Invert gradients are kept."] = "Setzt jedes Paar auf die Farben der Palette zurück. Verlaufsrichtung und Verläufe umkehren bleiben erhalten."
