L["Show with a target only for something you can attack: talking to a quest giver or a vendor leaves it faded."] = "Nur mit einem Ziel anzeigen, das du angreifen kannst: mit Questgeber oder Händler sprechen lässt es ausgeblendet."
L["Show your bag slots: drag a bag out, or drop one in."] = "Deine Taschenplätze anzeigen: ziehe eine Tasche heraus oder lege eine hinein."
