L["Shown"] = "Angezeigt"
L["Shows a grid while frames are unlocked, and snaps them to it."] = "Zeigt ein Raster, während Rahmen entsperrt sind, und rastet sie daran ein."
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "Zeigt einen Griff an jedem Rahmen. Ziehen zum Verschieben; Rechtsklick auf einen Griff setzt diesen Rahmen zurück."
L["Shows a macro's name on its button. When off, macros show their icon only."] = "Zeigt den Namen eines Makros auf seinem Button. Wenn aus, zeigen Makros nur ihr Symbol."
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "Zeigt eine Beispielversion nur dieses Rahmens, während du ihn bearbeitest, und jede Änderung sofort. Bleibt über Seiten an, bis du es ausschaltest; Kampf beendet es."
L["Shows a sample of the line where it sits."] = "Zeigt eine Beispielzeile, wo es sitzt."
L["Shows buffs icons on each member."] = "Zeigt Stärkungszauber-Symbole auf jedem Mitglied."
L["Shows crowd control icons on each member."] = "Zeigt Crowd-Control-Symbole auf jedem Mitglied."
L["Shows debuffs icons on each member."] = "Zeigt Schwächungszauber-Symbole auf jedem Mitglied."
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "Zeigt die Taste jedes Buttons auf dem Button. Wenn aus, funktionieren die Tasten weiterhin, du siehst sie nur nicht."
L["Shows each pet's health as text."] = "Zeigt die Gesundheit jedes Begleiters als Text."
L["Shows each pet's name."] = "Zeigt den Namen jedes Begleiters."
L["Shows only while the buff is up, like Power Word: Shield."] = "Zeigt nur, während der Stärkungszauber aktiv ist, wie Machtwort: Schild."
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "Zeigt oder versteckt die Reihe der Taschen-Buttons. Deine Taschen-Tasten öffnen die Taschen weiterhin, wenn sie versteckt ist."
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "Zeigt oder versteckt die Reihe kleiner Buttons, die Charakter, Zauberbuch, Talente und andere Fenster öffnen. Ihre Tasten funktionieren weiterhin, wenn sie versteckt ist."
L["Shows server time instead of your local time."] = "Zeigt Serverzeit statt deiner lokalen Zeit."
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "Zeigt Ziel, Fokus, Begleiter, Ziel des Ziels und die Gruppe mit Beispieleinheiten und beide Zauberleisten mitten im Zauber, damit du sie stylen und verschieben kannst ohne echtes Ziel. Endet, wenn der Kampf beginnt."
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "Zeigt jetzt den AFK-Bildschirm. Klicken oder eine Taste drücken zum Schließen. Auch /dui afk."
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "Zeigt die Kalender- und Verfolgungs-Buttons am rechten Rand der Karte, während die Maus über der Karte ist."
L["Shows the game's countdown on buttons that are on cooldown."] = "Zeigt den Countdown des Spiels auf Buttons, die auf Abklingzeit sind."
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "Zeigt die kleine Goldmünze des Spiels auf grauen Gegenständen in der Bank, wie bei den Standardtaschen."
L["Shows the game's small gold coin on gray items, like the default bags."] = "Zeigt die kleine Goldmünze des Spiels auf grauen Gegenständen, wie bei den Standardtaschen."
L["Shows the healer's name next to a heal on you."] = "Zeigt den Namen des Heilers neben einer Heilung auf dir."
L["Shows the health text large and white in the frame's inner corner (in Ribbon, at the inner end of the row above the bar)."] = "Zeigt den Gesundheitstext groß und weiß in der inneren Ecke des Rahmens (im Band am inneren Ende der Reihe über der Leiste)."
L["Shows the unit's name on this frame."] = "Zeigt den Namen der Einheit auf diesem Rahmen."
L["Shows these raid frames in a party too, in place of the party frames."] = "Zeigt diese Schlachtzugsrahmen auch in einer Gruppe, anstelle der Gruppenrahmen."
L["Shows this square on each member while its spell is on them."] = "Zeigt dieses Quadrat auf jedem Mitglied, während sein Zauber auf ihnen ist."
L["Shows where the range is before the enemy gets there, faintly."] = "Zeigt schwach, wo die Reichweite ist, bevor der Feind dort ist."
L["Shrink icon when pressed"] = "Symbol beim Drücken verkleinern"
