L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Sound)."] = "Am Lagerfeuer sitzen wärmt den Bildschirm mit Feuerlicht und Funken, ein leises Knistern spielt, und deine Aktionsleisten und Einheitenrahmen blenden aus. Bewegen, zielen oder wirken und alles kommt zurück; ein Kampf bringt es sofort zurück. Die Sounds folgen Weiche UI-Sounds (Allgemein > Sound)."
L["Size"] = "Größe"
L["Size as a percent of the button's normal size."] = "Größe als Prozent der normalen Button-Größe."
L["Size of every plate, friendly and enemy. Plates keep this size at any distance."] = "Größe jeder Plakette, freundlich und feindlich. Plaketten behalten diese Größe in jeder Entfernung."
L["Size of the names and numbers on this meter's bars."] = "Größe der Namen und Zahlen auf den Leisten dieses Meters."
