L["Size of the numbers on the experience bar."] = "Größe der Zahlen auf der Erfahrungsleiste."
L["Size of the quest names in the quest log on the map. Zone names, levels and progress follow it."] = "Größe der Questnamen im Questlog auf der Karte. Zonennamen, Stufen und Fortschritt folgen ihr."
L["Size of the text on the reputation bar. Its font is the experience bar's."] = "Größe des Texts auf der Rufleiste. Ihre Schrift ist die der Erfahrungsleiste."
L["Size target separately"] = "Ziel separat dimensionieren"
