L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for Bank and alts alone: their rows show below."] = "Platzgröße, Abstand, Skalierung, Anordnung der Gegenstände, leere Plätze und Gegenstandssymbol-Markierungen folgen deiner Taschen-Seite. Ausschalten, um sie nur für Bank und Alts zu setzen: ihre Zeilen erscheinen darunter."
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "Platzgröße, Abstand, Skalierung, Anordnung der Gegenstände, leere Plätze und Gegenstandssymbol-Markierungen folgen deiner Taschen-Seite. Ausschalten, um sie nur für die Bank zu setzen: ihre Zeilen erscheinen darunter."
L["Slots"] = "Plätze"
L["Slots per row in the Bank and alts window."] = "Plätze pro Reihe im Bank- und Alts-Fenster."
L["Slots per row in the bank. It holds more than your bags, so it's wider by default."] = "Plätze pro Reihe in der Bank. Sie fasst mehr als deine Taschen, daher standardmäßig breiter."
L["Slots with nothing on them show as empty frames. When off, they disappear and show again while you drag a spell or item."] = "Plätze ohne Inhalt erscheinen als leere Rahmen. Wenn aus, verschwinden sie und erscheinen wieder, während du einen Zauber oder Gegenstand ziehst."
L["Small"] = "Klein"
L["Small Brown Pouch"] = "Kleine braune Tasche"
L["Small colored squares on each member for your heals over time and shields, like Renew or Power Word: Shield. Each square shows while your spell is on them."] = "Kleine farbige Quadrate auf jedem Mitglied für deine Heilungen über Zeit und Schilde, wie Erneuerung oder Machtwort: Schild. Jedes Quadrat erscheint, während dein Zauber auf ihnen ist."
L["Small helpers and the game's windows in DaylightUI style."] = "Kleine Helfer und die Fenster des Spiels im DaylightUI-Stil."
L["Small helpers for looting, quests, trainers and more."] = "Kleine Helfer für Plündern, Quests, Lehrer und mehr."
L["Small helpers that save time every day. Each one says what it does."] = "Kleine Helfer, die jeden Tag Zeit sparen. Jeder sagt, was er tut."
L["Small helpers: faster looting, quest automation, trainers and more."] = "Kleine Helfer: schnelleres Plündern, Quest-Automatisierung, Lehrer und mehr."
L["Small icons in their own row, under the frame by default."] = "Kleine Symbole in eigener Reihe, standardmäßig unter dem Rahmen."
L["Small icons over your frame, nearest it. Off by default: your buff bars show them too."] = "Kleine Symbole über deinem Rahmen, am nächsten dazu. Standardmäßig aus: deine Stärkungszauber-Leisten zeigen sie auch."
L["Small tiles for a raid of up to 10: one column per group, left to right. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "Kleine Kacheln für einen Schlachtzug bis 10: eine Spalte pro Gruppe, von links nach rechts. Anzeigen, Fade, Texturen und Schriften hier gelten für jede Schlachtzugsgröße; deine Gruppe hat eine eigene Seite."
