L["Switch on, then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more): that click on a unit frame casts it. Closing the spellbook switches it off. /dui > Unit Frames > Click-casting lists them."] = "Einschalten, dann einen Zauber mit der gewünschten Maustaste klicken (Umschalt, Strg oder Alt halten für mehr): dieser Klick auf einen Einheitenrahmen wirkt ihn. Zauberbuch schließen schaltet es aus. /dui > Einheitenrahmen > Click-Casting listet sie."
