L["Talking to an NPC opens DaylightUI's window for gossip, quests and rewards. Turn it off to use the game's own windows."] = "Mit einem NSC sprechen öffnet das Fenster von DaylightUI für Geschwätz, Quests und Belohnungen. Ausschalten, um die eigenen Fenster des Spiels zu nutzen."
