L["Thank you for making DaylightUI possible."] = "Danke, dass du DaylightUI möglich machst."
L["Thank you to everyone who supports DaylightUI and keeps it growing."] = "Danke an alle, die DaylightUI unterstützen und wachsen lassen."
L["That border in the unit's class (or reaction) gradient from the Gradients page, running left to right."] = "Dieser Rand im Klassen- (oder Reaktions-) Verlauf der Einheit von der Verläufe-Seite, von links nach rechts."
L["That's as many builds as a set keeps: delete one first."] = "Das sind so viele Builds, wie ein Satz behält: lösche zuerst einen."
L["The '?', the title and the hand-in line."] = "Das '?', der Titel und die Abgabezeile."
L["The AFK screen can't show in combat, a boss fight, a keystone or a PvP match."] = "Der AFK-Bildschirm kann nicht im Kampf, bei einem Boss, einer Schlüsselstein-Dungeon oder einem PvP-Match erscheinen."
L["The Daylight chat box's own look and motion (Chat style: Daylight)."] = "Das eigene Aussehen und die Bewegung des Daylight-Chat-Fensters (Chat-Stil: Daylight)."
L["The DaylightUI border, the item's quality color, your accent color (General > Appearance), or a color you pick."] = "Der DaylightUI-Rand, die Qualitätsfarbe des Gegenstands, deine Akzentfarbe (Allgemein > Aussehen), oder eine Farbe, die du wählst."
L["The Fabled styles are art by JiberishUI and its artists, from the Jiberish Fabled Icons addon, read from its own folder. Without it installed, every style shows Daylight UI's own icons."] = "Die Fabled-Stile sind Kunst von JiberishUI und seinen Künstlern, aus dem Addon Jiberish Fabled Icons, aus seinem eigenen Ordner gelesen. Ohne Installation zeigt jeder Stil die eigenen Symbole von Daylight UI."
L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "Der Erbe-Button zeigt das Fenster von DaylightUI: wie weit die nächste Belohnung ist, die Herausforderungen und die Erbe-Bäume. Ausschalten, um das Fenster des Spiels zu nutzen."
L["The Mindless Ones completed."] = "Die Hirnlosen abgeschlossen."
L["The NPC window is switched off (/dui > Talk)."] = "Das NSC-Fenster ist ausgeschaltet (/dui > Sprechen)."
L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "Die Quests-Überschrift bleibt, wenn nichts verfolgt wird, damit du siehst, wo der Verfolger ist."
L["The accent"] = "Der Akzent"
L["The aggro color when Aggro color is Custom color."] = "Die Aggro-Farbe, wenn Aggro-Farbe auf Eigene Farbe steht."
L["The arrow's color while Arrow color is set to Custom."] = "Die Farbe des Pfeils, während Pfeilfarbe auf Eigen steht."
L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "Die Bank im gleichen Aussehen wie deine Taschen. Gruppen und verschobene Gegenstände werden mit deinen Taschen geteilt."
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "Die Leiste verläuft von dunkel nach hell in den Farben ihres Rangs, auf der Verläufe-Seite bearbeitbar."
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "Die Leiste verläuft von dunkel nach hell statt einer flachen Farbe. Ruf bekommt einen pro Rang, auf der Verläufe-Seite bearbeitbar."
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you."] = "Die Leistenfarbe für tote und offline Spieler und markierte NSCs, und für NSCs danach, wie sie zu dir stehen."
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "Die Farbe der Leiste, während der Zauber nicht interrupted werden kann, unabhängig vom Füllstil."
L["The bar's color while the cast can't be interrupted."] = "Die Farbe der Leiste, während der Zauber nicht interrupted werden kann."
L["The bars over enemies' heads: how big they are, and what they show."] = "Die Leisten über den Köpfen der Feinde: wie groß sie sind und was sie zeigen."
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "Die Leisten verlaufen von dunkel nach hell statt einer flachen Farbe. Die Farbpaare sind unter Allgemein > Verläufe."
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "Die Leisten, die am Ende der Gesundheit für ankommende Heilungen und Absorptionsschilde hängen. Ein Überschirm (ein Schild größer als die fehlende Gesundheit) folgt dem Schild."
L["The bars' and names' colors on every unit frame."] = "Die Farben der Leisten und Namen auf jedem Einheitenrahmen."
L["The bars' color when Bar color is One color."] = "Die Farbe der Leisten, wenn Leistenfarbe auf Eine Farbe steht."
L["The border color of every loot feed line while Loot feed border color is set to Custom."] = "Die Randfarbe jeder Beute-Feed-Zeile, während Beute-Feed-Randfarbe auf Eigen steht."
L["The border color when Border color is set to Your own color."] = "Die Randfarbe, wenn Randfarbe auf Eigene Farbe steht."
L["The border in the same color as the name."] = "Der Rand in derselben Farbe wie der Name."
L["The border of a debuff you can dispel, and the raid tile's dispel icon. Debuffs already on screen change after /reload."] = "Der Rand eines Schwächungszaubers, den du dispellen kannst, und das Dispel-Symbol der Schlachtzugskachel. Bereits sichtbare Schwächungszauber ändern sich nach /reload."
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "Die Boxen hinter Erfahrungsleiste, Minikarte und Schadensmeter sowie die eigenen Fenster der Meter und des Bedrohungsmessers. Bei 0 Deckkraft verschwinden die Boxen; Minikarte und Leisten bleiben sichtbar."
L["The buffs wrap onto up to this many rows."] = "Die Stärkungszauber umbrechen auf bis zu so viele Reihen."
L["The button's border lights up while the mouse is over it."] = "Der Rand des Buttons leuchtet, während die Maus darüber ist."
L["The button's border lights up while you press it."] = "Der Rand des Buttons leuchtet, während du ihn drückst."
L["The cast bar's color when Fill style is One color."] = "Die Farbe der Zauberleiste, wenn Füllstil auf Eine Farbe steht."
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "Das Charakterfenster und seine Tabs (Ruf, Fertigkeiten, PvP, Währung, Statistiken), andere inspizieren."
L["The chat menu, channel, voice and social buttons next to chat. When off, they're gone; their slash commands still work."] = "Das Chat-Menü, Kanal-, Sprach- und Sozial-Buttons neben dem Chat. Wenn aus, sind sie weg; ihre Slash-Befehle funktionieren weiterhin."
L["The chat only"] = "Nur der Chat"
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "Der Text des Chat-Fensters und die Chat-Blasen. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["The clock reads 18:30 instead of 6:30 PM."] = "Die Uhr zeigt 18:30 statt 6:30 PM."
L["The color of a Curse debuff's border and dispel icon."] = "Die Farbe des Rands und Dispel-Symbols eines Fluch-Schwächungszaubers."
L["The color of a Disease debuff's border and dispel icon."] = "Die Farbe des Rands und Dispel-Symbols eines Krankheits-Schwächungszaubers."
L["The color of a Magic debuff's border and dispel icon."] = "Die Farbe des Rands und Dispel-Symbols eines Magie-Schwächungszaubers."
L["The color of a Poison debuff's border and dispel icon."] = "Die Farbe des Rands und Dispel-Symbols eines Gift-Schwächungszaubers."
L["The color of the glow around your target's bar."] = "Die Farbe des Glows um die Leiste deines Ziels."
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "Die Farbe des letzten Punkts, oder der ganzen Reihe bei Maximalpunkten, und das Ende von Farbe zu voller Farbe."
L["The color of the names on the threat meter."] = "Die Farbe der Namen auf dem Bedrohungsmeter."
L["The color of the names on this meter's bars."] = "Die Farbe der Namen auf den Leisten dieses Meters."
L["The color of the outline around your target's bar."] = "Die Farbe des Umrisses um die Leiste deines Ziels."
L["The color of the pull line across the threat bars."] = "Die Farbe der Pull-Linie über den Bedrohungsleisten."
L["The color of the shaded spell cost on your power bar."] = "Die Farbe der schattierten Zauberkosten auf deiner Ressourcenleiste."
L["The color of the stretch for damage shields."] = "Die Farbe der Streckung für Schadensschilde."
L["The color of the stretch past the health for heals on their way."] = "Die Farbe der Streckung über die Gesundheit hinaus für ankommende Heilungen."
L["The color the border lights up in while the mouse is over a button."] = "Die Farbe, in der der Rand aufleuchtet, während die Maus über einem Button ist."
L["The color the border lights up in while you press a button."] = "Die Farbe, in der der Rand aufleuchtet, während du einen Button drückst."
L["The color the execute range lights up in."] = "Die Farbe, in der der Hinrichtungsbereich aufleuchtet."
L["The color used while the menu above is set to Custom."] = "Die Farbe, die genutzt wird, während das Menü oben auf Eigen steht."
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "Der farbige Sweep über dem Symbol, während sein Stärkungszauber aktiv ist. Wenn aus, zeigt nur der Timer."
L["The colors below"] = "Die Farben darunter"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "Die überall genutzten Farben, Schriften und Texturen. Der Bildschirm ändert sich beim Wählen."
L["The cooldown edge's color when Cooldown edge is set to Your own color."] = "Die Farbe der Abklingzeit-Kante, wenn Abklingzeit-Kante auf Eigene Farbe steht."
L["The cooldown layout can't be edited during combat."] = "Das Cooldown-Layout kann während des Kampfes nicht bearbeitet werden."
L["The cooldown manager's layout."] = "Das Layout des Cooldown-Managers."
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "Die Countdown-Symbole für deine Totems, über dem Spieler-Rahmen. Im Entsperrmodus verschieben."
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "Die Währungen, die du verfolgst (wie die eigene Rucksackliste des Spiels sie zeigt), mit Symbol und Anzahl, neben deinem Geld."
L["The dark part shrinks away instead of filling in."] = "Der dunkle Teil schrumpft weg statt sich zu füllen."
L["The dark ribbon behind each line. When off, only the icon and text show."] = "Das dunkle Band hinter jeder Zeile. Wenn aus, erscheinen nur Symbol und Text."
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "Die Datentexte sowie Uhr und Bildrate auf der Minikarte. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["The debuffs wrap onto up to this many rows."] = "Die Schwächungszauber umbrechen auf bis zu so viele Reihen."
L["The dim line under each item's name. Repair warnings still show when it's off."] = "Die dunkle Linie unter dem Namen jedes Gegenstands. Reparaturwarnungen erscheinen weiterhin, wenn sie aus ist."
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "Das Dungeon-Journal, seine Favoriten- und Einstellungsfenster; das Bild jedes Dungeons bleibt."
L["The edge round each button. A proc still lights it up."] = "Der Rand um jeden Button. Ein Proc leuchtet ihn weiterhin auf."
L["The elite dragon wraps your own portrait too."] = "Der Elite-Drache umschließt auch dein eigenes Porträt."
L["The empty bar pulses while the buff is down."] = "Die leere Leiste pulsiert, während der Stärkungszauber abgelaufen ist."
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "Der leere Teil hinter der Füllung jeder Leiste, in der Farbe der Leiste getönt, außer wo die eigene Seite eines Rahmens eine andere wählt."
L["The empty part behind the bars in DaylightUI's windows. General uses the bar background above."] = "Der leere Teil hinter den Leisten in DaylightUI-Fenstern. Allgemein nutzt den Leistenhintergrund oben."
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "Der leere Teil jeder Leiste in der Gruppe. Der eigene Hintergrund eines Zaubers, oben, gewinnt."
L["The empty part of every health bar: a dimmed copy of the bar's own color, or one you pick."] = "Der leere Teil jeder Gesundheitsleiste: eine abgedunkelte Kopie der eigenen Farbe der Leiste, oder eine, die du wählst."
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Leisten des Cooldown-Managers, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Zauberleiste auf jeder Namensplakette, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Combopunkte auf der Namensplakette deines Ziels, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Combopunkte, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Leisten der Schadens-, Heilungs- und Bedrohungsmesser, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Erfahrungs- und Rufleiste, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Gesundheitsleiste auf jeder Namensplakette, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Gesundheitsleiste unter dem Tooltip einer Einheit, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Gesundheitsleisten der Begleiter, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Ressourcenleisten der Begleiter, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Fortschrittsleisten im Verfolger und im Popup, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Gesundheitsleisten der Schlachtzugskacheln, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Ressourcenleisten der Schlachtzugskacheln, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil des Schwung-Timers, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Gesundheitsleiste dieses Rahmens, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Ressourcenleiste dieses Rahmens, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil deiner Zauberleiste, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Zauberleiste deines Fokus, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "Der leere Teil der Zauberleiste deines Ziels, hinter der Füllung. Allgemein nutzt den Leistenhintergrund unter Allgemein > Aussehen."
L["The empty part's color when Missing health color is Custom color."] = "Die Farbe des leeren Teils, wenn Farbe fehlender Gesundheit auf Eigene Farbe steht."
L["The experience bar on top of the panel, or reputation at the level cap."] = "Die Erfahrungsleiste oben auf dem Panel, oder Ruf am Stufenlimit."
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "Der Text der Erfahrungsleiste und ihr +EP. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "Erfahrungsleiste, Schadensmeter und Minikarte blenden zusammen aus (und das separate Meter-Fenster, falls genutzt)."
L["The faction's name on the bar."] = "Der Name der Fraktion auf der Leiste."
L["The fifth chat channel you joined, often a custom one."] = "Der fünfte Chat-Kanal, dem du beigetreten bist, oft ein eigener."
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "Der fünfte Punkt füllt sich in Voller Farbe (zunächst rot), damit eine volle Reihe auf einen Blick auffällt."
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "Die Füllung jeder Leiste: Gesundheit, Ressource, Zauberleisten, Schwung-Timer, Erfahrung, Schadensmeter, Namensplaketten und mehr, außer wo die eigene Seite eines Rahmens eine andere wählt. Texturen, die andere Addons teilen (SharedMedia), sind nach unseren gelistet."
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "Die Füllung der Leisten des Cooldown-Managers. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the bars in DaylightUI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "Die Füllung der Leisten in DaylightUI-Fenstern: Ruf, Fertigkeiten, Berufe, Begleiter-Erfahrung, Questziele. Sie behalten ihre runde Form. Allgemein nutzt die Leistentextur oben."
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "Die Füllung der Zauberleiste auf jeder Namensplakette. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "Die Füllung der Combopunkte auf der Namensplakette deines Ziels. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "Die Füllung der Combopunkte. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "Die Füllung der Leisten der Schadens-, Heilungs- und Bedrohungsmesser. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "Die Füllung der Erfahrungs- und Rufleiste. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "Die Füllung der Gesundheitsleiste auf jeder Namensplakette. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "Die Füllung der Gesundheitsleiste unter dem Tooltip einer Einheit. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "Die Füllung der Gesundheitsleisten der Begleiter. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "Die Füllung der Ressourcenleisten der Begleiter. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "Die Füllung der Fortschrittsleisten im Verfolger und im Popup. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "Die Füllung der Gesundheitsleisten der Schlachtzugskacheln. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "Die Füllung der Ressourcenleisten der Schlachtzugskacheln. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "Die Füllung des Schwung-Timers. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "Die Füllung der Gesundheitsleiste dieses Rahmens. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "Die Füllung der Ressourcenleiste dieses Rahmens. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "Die Füllung deiner Zauberleiste. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "Die Füllung der Zauberleiste deines Fokus. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "Die Füllung der Zauberleiste deines Ziels. Allgemein nutzt die Leistentextur unter Allgemein > Aussehen."
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "Die Schrift oben erscheint überall auf einmal, außer wo die eigene Seite eines Rahmens oder die Fensterschrift darunter eine andere wählt. Das setzt jede davon auf die Schrift oben zurück."
L["The friendly health bar's color when Bar color is One color."] = "Die Farbe der freundlichen Gesundheitsleiste, wenn Leistenfarbe auf Eine Farbe steht."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the professions book, the world map's frame, the breath bar. Also the game's own character and inspect windows while Daylight UI's are off."] = "Das Spielmenü, Addon-Liste, Makros, Uhr, Beute, Sockeln, Aufwerten, Schrottplatz, Auktionshaus, Berufsbuch, Rahmen der Weltkarte, Atemleiste. Auch die eigenen Charakter- und Inspizieren-Fenster des Spiels, während die von Daylight UI aus sind."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "Das Spielmenü, Addon-Liste, Makros, Uhr, Beute, Sockeln, Aufwerten, Schrottplatz, Auktionshaus, Rahmen der Weltkarte, Atemleiste."
L["The game only reports range for your group; anyone else stays at full opacity."] = "Das Spiel meldet Reichweite nur für deine Gruppe; alle anderen bleiben bei voller Deckkraft."
L["The game shows it as a bar."] = "Das Spiel zeigt es als Leiste."
L["The game shows it as an icon."] = "Das Spiel zeigt es als Symbol."
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "Der Chat des Spiels im DaylightUI-Aussehen, in der unteren linken Ecke. Der Chat selbst funktioniert normal."
L["The game's new-player tips (the game setting 'Tutorials'). When off, they're turned off."] = "Die Neuling-Tipps des Spiels (Spieleinstellung „Tutorials“). Wenn aus, sind sie ausgeschaltet."
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "Die Zahlen des Spiels, die von dem abspringen, was du triffst, und der scrollende Kampftext über dir."
L["The game's own"] = "Die des Spiels"
L["The game's own buff frames show beside DaylightUI's bars. When off, our bars replace them (they still show while Edit Mode is open)."] = "Die eigenen Stärkungszauber-Rahmen des Spiels erscheinen neben den Leisten von DaylightUI. Wenn aus, ersetzen unsere Leisten sie (sie erscheinen weiterhin, während der Edit Mode offen ist)."
L["The game's own messages: logins, /played, errors and the like."] = "Die eigenen Nachrichten des Spiels: Logins, /gespielt, Fehler und Ähnliches."
L["The game's own setting: a quest you accept goes straight into the tracker."] = "Die eigene Einstellung des Spiels: eine Quest, die du annimmst, geht direkt in den Verfolger."
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "Die eigene Einstellung des Spiels: die Karte dreht sich mit dir, sodass die Blickrichtung immer oben ist. Wenn aus, ist Norden immer oben."
L["The game's own settings for how the numbers leave the target."] = "Die eigenen Einstellungen des Spiels, wie die Zahlen das Ziel verlassen."
L["The game's own switches."] = "Die eigenen Schalter des Spiels."
L["The game's own windows in DaylightUI style: the info panel's background, DaylightUI borders, font, controls and scroll bars."] = "Die eigenen Fenster des Spiels im DaylightUI-Stil: Hintergrund des Info-Panels, DaylightUI-Ränder, Schrift, Steuerelemente und Scrollleisten."
L["The game's own windows in the DaylightUI look."] = "Die eigenen Fenster des Spiels im DaylightUI-Aussehen."
L["The game's quest tracker, placed under the panel."] = "Der Questverfolger des Spiels, unter dem Panel platziert."
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "Der scrollende Text des Spiels über deinem eigenen Charakter: Treffer, die du erleidest, Heilungen, Procs und mehr."
L["The game's tooltips in the DaylightUI look."] = "Die Tooltips des Spiels im DaylightUI-Aussehen."
L["The game's tooltips."] = "Die Tooltips des Spiels."
L["The game's windows Daylight UI didn't rebuild. Rebuilt windows have their own switches under Extras."] = "Die Fenster des Spiels, die Daylight UI nicht neu gebaut hat. Neu gebaute Fenster haben eigene Schalter unter Extras."
L["The gap between buff icons."] = "Der Abstand zwischen Stärkungszauber-Symbolen."
L["The gap between combo point pips."] = "Der Abstand zwischen Combopunkt-Punkten."
L["The gap between combo points."] = "Der Abstand zwischen Combopunkten."
L["The gap between debuff icons."] = "Der Abstand zwischen Schwächungszauber-Symbolen."
L["The gap between icons."] = "Der Abstand zwischen Symbolen."
L["The gap between lines, when there's more than one."] = "Der Abstand zwischen Zeilen, wenn es mehr als eine gibt."
L["The gap between one party frame and the next."] = "Der Abstand zwischen einem Gruppenrahmen und dem nächsten."
L["The gap between this bar's buttons."] = "Der Abstand zwischen den Buttons dieser Leiste."
L["The gap between this bar's icons."] = "Der Abstand zwischen den Symbolen dieser Leiste."
L["The glow behind your character in this color."] = "Der Glow hinter deinem Charakter in dieser Farbe."
L["The glowing border on a button when its spell procs."] = "Der leuchtende Rand auf einem Button, wenn sein Zauber proct."
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "Das Gold unten in der Tasche zählt hoch oder runter zum neuen Betrag. Braucht Bewegungseffekte (Allgemein > Aussehen)."
L["The green numbers over who you heal."] = "Die grünen Zahlen über dem, den du heilst."
L["The guide that set this character up: a quick setup, a tour of everything DaylightUI does, or another profile."] = "Die Anleitung, die diesen Charakter eingerichtet hat: eine Schnelleinrichtung, eine Tour durch alles, was DaylightUI tut, oder ein anderes Profil."
L["The guide window (old and new), its steps and its item and target boxes."] = "Das Anleitungsfenster (alt und neu), seine Schritte und seine Gegenstands- und Zielboxen."
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "Hand und Zeit auf jeder Leiste. Unter der Zauberleiste angehängt, bleibt es klein genug für die Leiste."
L["The health and level numbers on the nameplates. General uses the font on General > Appearance."] = "Die Gesundheits- und Stufenzahlen auf den Namensplaketten. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["The health bar fills bottom to top instead of across."] = "Die Gesundheitsleiste füllt sich von unten nach oben statt quer."
L["The health bar fills from the opposite side."] = "Die Gesundheitsleiste füllt sich von der gegenüberliegenden Seite."
L["The health bar's color for a dead unit."] = "Die Farbe der Gesundheitsleiste für eine tote Einheit."
L["The health bar's color for a friendly NPC."] = "Die Farbe der Gesundheitsleiste für einen freundlichen NSC."
L["The health bar's color for a player who went offline."] = "Die Farbe der Gesundheitsleiste für einen Spieler, der offline gegangen ist."
L["The health bar's color for an NPC someone else tagged first."] = "Die Farbe der Gesundheitsleiste für einen NSC, den jemand anderes zuerst markiert hat."
L["The health bar's color for an NPC that attacks you."] = "Die Farbe der Gesundheitsleiste für einen NSC, der dich angreift."
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "Die Farbe der Gesundheitsleiste für einen NSC, der dich in Ruhe lässt, bis du ihn angreifst."
L["The health bar's color when Health bar color is One color."] = "Die Farbe der Gesundheitsleiste, wenn Gesundheitsleisten-Farbe auf Eine Farbe steht."
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "Der Gesundheitstext erscheint auch bei voller Gesundheit. Wenn aus, verschwindet er, während die Einheit voll ist."
L["The health text's color when Health text color is Custom."] = "Die Farbe des Gesundheitstexts, wenn Gesundheitstext-Farbe auf Eigen steht."
L["The highest rank"] = "Der höchste Rang"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "Die Hervorhebungsfarbe: Daylights eigener ruhiger Ton, der Daylight-Verlauf, die Farbe deiner Klasse oder ihr Verlauf (von der Verläufe-Seite), oder eine eigene."
L["The highlight's color when Active spell is set to Your own color."] = "Die Farbe der Hervorhebung, wenn Aktiver Zauber auf Eigene Farbe steht."
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "Das Symbol der Quest, auf die der Minikarten-Pfeil zeigt (klicke das Symbol einer Quest zum Auswählen), und das Licht hinter einem Symbol unter der Maus."
L["The info panel, meter, map and tracker."] = "Das Info-Panel, Meter, Karte und Verfolger."
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain gray."] = "Die Gegenstandsstufe unten in der Qualitätsfarbe deiner Ausrüstung, Haltbarkeit grün zu gelb zu rot. Wenn aus, sind beide schlicht grau."
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "Die Gegenstandsstufe von Waffen und Rüstung in der Bank, in der unteren linken Ecke."
L["The item level of weapons and armor in the bottom left corner."] = "Die Gegenstandsstufe von Waffen und Rüstung in der unteren linken Ecke."
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "Die Kobolde in der Mine tragen Kerzen auf dem Kopf, um im Dunkeln zu sehen. Bring mir acht davon und ich werde es dir lohnen."
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "Die Anführer-Werkzeuge sind aus: Einheitenrahmen > Schlachtzug > Anführer-Werkzeuge."
L["The leader tools open after the fight."] = "Die Anführer-Werkzeuge öffnen sich nach dem Kampf."
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "Die Anführer-Werkzeuge sitzen neben den Gruppen- oder Schlachtzugsrahmen von Daylight UI, die aus sind."
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "Die Krone des Anführers bleibt im Kampf. Wenn aus, versteckt sie sich, während du kämpfst."
L["The level in front of each quest name."] = "Die Stufe vor jedem Questnamen."
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "Die Linie unter dem offenen Tab oben (Charakter, Ruf, Fertigkeiten...)."
L["The line under the open tab in this color."] = "Die Linie unter dem offenen Tab in dieser Farbe."
L["The line where the range starts. 0 hides it."] = "Die Linie, wo die Reichweite beginnt. 0 versteckt sie."
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "Die Zeilen in der Bildschirmmitte (interrupted, Taschen voll, neues Gebiet gefunden) in deiner Schrift, Fehler in weichem Rot, ein- und ausblendend. Mit /dui unlock verschieben. Ausschalten, um den eigenen roten und gelben Text des Spiels zu sehen."
L["The lines under the headers in this color."] = "Die Linien unter den Überschriften in dieser Farbe."
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "Die Liste wächst von ihrem Griff nach oben statt nach unten. Für einen Verfolger, der niedrig auf dem Bildschirm platziert ist."
L["The look everything shares: the font, the accent color and the window background."] = "Das gemeinsame Erscheinungsbild: die Schriftart, die Akzentfarbe und der Fensterhintergrund."
L["The look shared by everything DaylightUI draws."] = "Das gemeinsame Erscheinungsbild für alles, was DaylightUI zeichnet."
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "Das Fenster des Beute-Browsers, seine Listen, Schaltflächen und Dialoge; seine Symbole und Karten bleiben erhalten."
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "Die Position des Beutefensters wird vom Bearbeitungsmodus des Spiels verwaltet. Du nutzt ein eigenes Layout: verschiebe es dort (Esc > Bearbeitungsmodus)."
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "Die niedrigeren Ränge jedes Zaubers stehen unter dem höchsten, damit du einen älteren Rang für weniger Mana wirken kannst. Ausgeschaltet listet das Zauberbuch nur den höchsten Rang. Die Zauberbuchseite hat denselben Schalter (Ränge ausblenden)."
L["The main hand bar's color."] = "Die Farbe der Haupthand-Leiste."
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the !."] = "Die Markierung zeigt, was die Quest verlangt – wie auf der Karte: ein Schwert zum Töten, ein Beutel zum Plündern, ein Zahnrad zum Benutzen, ein Auge zum Erkunden, in der Questfarbe. Benötigt das Quest-Modul; ohne es nur das !."
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "Der Marker und der Pfeil blenden sich im Kampf aus, damit sie nicht im Weg sind."
L["The marker in the world that leads you to your quest."] = "Der Marker in der Welt, der dich zu deiner Quest führt."
L["The marker over the spot of the quest you picked (click its icon in the tracker) in DaylightUI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "Der Marker über dem Ort der gewählten Quest (klicke auf ihr Symbol im Tracker) im DaylightUI-Stil mit Entfernungsanzeige. Er verschwindet, sobald du dich im Questgebiet auf der Karte befindest. Ausschalten zeigt den spielinternen Marker."
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "Die Farbe der Nahkampf-Leisten, während Heldenhafter Stoß, Spalten oder Zermalmen auf deinen nächsten Schlag wartet."
L["The meter hides while you play solo."] = "Der Zähler wird ausgeblendet, wenn du solo spielst."
L["The most buff icons at once."] = "Die maximale Anzahl an Stärkungszauber-Symbolen gleichzeitig."
L["The most buffs you can purge or steal one plate shows."] = "Die maximale Anzahl an reinigbaren oder stehlbaren Stärkungszaubern, die eine Leiste anzeigt."
L["The most debuff icons at once."] = "Die maximale Anzahl an Schwächungszauber-Symbolen gleichzeitig."
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "Die maximale Anzahl an Schwächungszaubern anderer Spieler, die nach deinen eigenen angezeigt werden. Nur bei „Meine zuerst, dann andere“."
L["The most group members the threat meter lists at once, under the damage meter."] = "Die maximale Anzahl an Gruppenmitgliedern, die der Bedrohungszähler unter dem Schadenszähler gleichzeitig anzeigt."
L["The most group members the threat meter lists at once."] = "Die maximale Anzahl an Gruppenmitgliedern, die der Bedrohungszähler gleichzeitig auflistet."
L["The most icons this group shows at once."] = "Die maximale Anzahl an Symbolen, die diese Gruppe gleichzeitig anzeigt."
L["The most of your buffs one friendly plate shows."] = "Die maximale Anzahl deiner Stärkungszauber, die eine freundliche Leiste anzeigt."
L["The most of your debuffs one plate shows."] = "Die maximale Anzahl deiner Schwächungszauber, die eine Leiste anzeigt."
L["The most of your own debuffs shown at once."] = "Die maximale Anzahl deiner eigenen Schwächungszauber, die gleichzeitig angezeigt werden."
L["The mouseover border's color when Mouseover border color is set to Your own color."] = "Die Farbe des Mauszeiger-Rahmens, wenn „Mauszeiger-Rahmenfarbe“ auf „Eigene Farbe“ steht."
L["The name floats above the bar, at its outer end. Long names are cut short."] = "Der Name schwebt über der Leiste an ihrem äußeren Ende. Lange Namen werden gekürzt."
L["The name of a buff or debuff as it lands on you."] = "Der Name eines Stärkungs- oder Schwächungszaubers, wenn er dich trifft."
L["The name sits in a small tab above the frame. Long names are cut short."] = "Der Name sitzt in einem kleinen Reiter über dem Rahmen. Lange Namen werden gekürzt."
L["The name's color when Name color is Custom."] = "Die Farbe des Namens, wenn „Namensfarbe“ auf „Benutzerdefiniert“ steht."
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "Die Namen auf jedem Einheitenrahmen, sofern ein Rahmen nicht eigene wählt. Klasse und Reaktion: Spieler nach Klassenfarbe, andere nach freundlich, neutral oder feindlich."
L["The names' color when Name color is Custom."] = "Die Farbe der Namen, wenn „Namensfarbe“ auf „Benutzerdefiniert“ steht."
L["The newest first. Click one to move it again."] = "Die neuesten zuerst. Klicke auf einen, um ihn erneut zu verschieben."
L["The note box shows after the fight."] = "Das Notizfeld wird nach dem Kampf angezeigt."
L["The number on an icon showing how many stacks it has."] = "Die Zahl auf einem Symbol, die die Anzahl der Stapel anzeigt."
L["The numbers change color for the last seconds of the cooldown."] = "Die Zahlen ändern ihre Farbe in den letzten Sekunden der Abklingzeit."
L["The numbers in objectives, like 3/8."] = "Die Zahlen in den Zielen, z. B. 3/8."
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "Die Zahlen auf der Leiste, z. B. 1.200 / 5.000 (+800), wobei +800 deine ausgeruhte Erfahrung ist."
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "Die Zahlen auf der Leiste, z. B. 1.800 / 3.000."
L["The numbers over what you hit."] = "Die Zahlen über dem, was du triffst."
L["The off hand bar's color."] = "Die Farbe der Nebenhand-Leiste."
L["The order of the quests inside each zone in the quest log on the map."] = "Die Reihenfolge der Quests innerhalb jeder Zone im Questlog auf der Karte."
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "Der Umriss, auf den jeder Button zugeschnitten ist. Symbol, Rand und Abklingzeit-Schattierung folgen ihm alle."
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "Der Umriss oder Glow in deiner Akzentfarbe (Aussehen), folgt ihr bei Änderungen. Wenn aus, nutzt die Farben darunter."
L["The outline's color when Target outline color is Custom color."] = "Die Farbe des Umrisses, wenn Ziel-Umrissfarbe auf Eigene Farbe steht."
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "Das Panel hinter dem Chat, mit seinem Rand. Wenn aus, erscheint nur der Chat-Text."
L["The panel's framed box behind the list, as tall as what's shown."] = "Die gerahmte Box des Panels hinter der Liste, so hoch wie das Angezeigte."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "Die Gesundheitsleiste des Begleiters nimmt stattdessen die Stimmungsfarbe an: rot unglücklich, gelb zufrieden, grün glücklich. Das Quadrat ausschalten, um nur das zu haben."
L["The pets' health text. General uses the font on General > Appearance."] = "Der Gesundheitstext der Begleiter. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["The pets' names. General uses the font on General > Appearance."] = "Die Namen der Begleiter. Allgemein nutzt die Schrift unter Allgemein > Aussehen."
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "Das Stück der Leiste, das du gerade verdient hast, blitzt auf und „+EP“ steigt; ein Sweep beim Stufenaufstieg. Braucht Bewegungseffekte (Allgemein > Aussehen)."
L["The pips widen to span the whole frame, so the row reads like a bar."] = "Die Punkte verbreitern sich über den ganzen Rahmen, sodass die Reihe wie eine Leiste wirkt."
L["The pips' color with One color, or the color they start from with Color to full color."] = "Die Farbe der Punkte bei Eine Farbe, oder die Farbe, von der sie starten, bei Farbe zu voller Farbe."
L["The players who keep DaylightUI going. Thank you."] = "Die Spieler, die DaylightUI am Laufen halten. Danke."
L["The power bar's color when Power bar color is One color."] = "Die Farbe der Ressourcenleiste, wenn Ressourcenleisten-Farbe auf Eine Farbe steht."
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "Der Ressourcentext erscheint auch bei vollem Mana, voller Wut oder voller Energie. Wenn aus, verschwindet er bei voll."
L["The pressed border's color when Pressed border color is set to Your own color."] = "Die Farbe des gedrückten Rands, wenn Gedrückte Randfarbe auf Eigene Farbe steht."
L["The priority quest's color while Priority quest color is set to Custom."] = "Die Farbe der Prioritätsquest, während Prioritätsquest-Farbe auf Eigen steht."
L["The proc border's color when Proc border is set to Your own color."] = "Die Farbe des Proc-Rands, wenn Proc-Rand auf Eigene Farbe steht."
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "Das Profil %s ist bereit. Wähle es für diesen Charakter (oder einen Talentbaum), um es zu nutzen."
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "Das Profil %s: seine Einstellungen, Rahmenpositionen und Edit-Mode-Layout. Strg+C zum Kopieren, dann teilen."
L["The profile for your first talent set. Changing it asks to reload."] = "Das Profil für deinen ersten Talentbaum. Ändern fordert zum Neuladen auf."
L["The profile for your second talent set; swapping talents asks to switch."] = "Das Profil deines zweiten Talentbaums; Talentwechsel fragt nach dem Umschalten."
L["The profile in use as text to copy and share."] = "Das verwendete Profil als Text zum Kopieren und Teilen."
L["The profile is ready. Reload to use it."] = "Das Profil ist bereit. Neu laden, um es zu nutzen."
L["The profile is used as it is; nothing in it changes."] = "Das Profil wird so verwendet, wie es ist; nichts darin ändert sich."
L["The profile this character uses. Changing it asks to reload."] = "Das Profil, das dieser Charakter verwendet. Es zu ändern fordert ein Neuladen an."
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "Das Bearbeitungsmodus-Layout des Profils wird nach dem Neuladen gesetzt (%s)."
L["The progress bars' color while Progress bar color is set to Custom."] = "Die Farbe der Fortschrittsleisten, wenn „Farbe der Fortschrittsleisten“ auf „Benutzerdefiniert“ steht."
L["The quest log on the world map."] = "Das Questlog auf der Weltkarte."
L["The quest under the mouse stays bright, the others ease dimmer."] = "Die Quest unter der Maus bleibt hell, die anderen werden sanft dunkler."
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Die Schlachtzugsrahmen für 11 bis 20 Spieler. Anzeige, Fade, Texturen und Schriften sind auf der Raid-10-Seite."
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "Die Schlachtzugsrahmen für 21 bis 40 Spieler. Anzeige, Fade, Texturen und Schriften sind auf der Raid-10-Seite."
L["The raid tiles' health text. General uses the font on General > Appearance."] = "Der Gesundheitstext der Schlachtzugskacheln. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The raid tiles' names. General uses the font on General > Appearance."] = "Die Namen der Schlachtzugskacheln. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The raid tiles' own name color. Same as the Colors page follows the name color every frame shares."] = "Die eigene Namensfarbe der Schlachtzugskacheln. „Wie die Farben-Seite“ folgt der Namensfarbe, die alle Rahmen teilen."
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "Die Fernkampfleiste zeigt, wie weit dein Ziel ist, statt seines Namens: Nahkampf, Tote Zone, 10 bis 35 m, Max. Reichweite oder Außer Reichweite."
L["The ranged bar's color."] = "Die Farbe der Fernkampfleiste."
L["The red of a ring, name tab or raid tile while something is attacking the unit, or a color you pick."] = "Das Rot eines Rings, Namens-Tabs oder einer Schlachtzugskachel, während etwas die Einheit angreift, oder eine Farbe deiner Wahl."
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "Der Ruf, den du beobachtest, immer, auf seiner eigenen Leiste. Wähle die Fraktion auf der Ruf-Seite des Charakterfensters. Verschiebe sie im Entsperrmodus; ziehe an ihrer Ecke zum Ändern der Größe."
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "Der Ring (oder Namens-Tab oder Schlachtzugskachel), der rot wird, während etwas die Einheit angreift; der Drache eines Elites behält seine Farbe, seine Augen fangen Feuer."
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "Das Rollensymbol bleibt im Kampf. Wenn aus, versteckt es sich, während du kämpfst."
L["The row above the bar that holds the name and the health number."] = "Die Reihe über der Leiste, die den Namen und die Gesundheitszahl hält."
L["The same click again removes it."] = "Derselbe Klick nochmal entfernt es."
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "Dieselben Farben wie in den Chat-Einstellungen des Spiels: Eine Änderung zeigt sich in jedem Chat-Tab."
L["The same size as the top-right panel with its damage meter out."] = "Dieselbe Größe wie das Panel oben rechts mit ausgefahrenem Schadensmeter."
L["The search failed. Try Refresh."] = "Die Suche ist fehlgeschlagen. Versuche Aktualisieren."
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "Die Schattierung über der Gesundheit, die deine Schaden-über-Zeit-Zauber noch nehmen werden, auf dem Ziel und auf feindlichen Namensplaketten."
L["The shade that sweeps over a button while it's on cooldown."] = "Die Schattierung, die über einen Button wischt, während er auf Abklingzeit ist."
L["The short tag before these messages. Left empty it stays [%s]."] = "Das kurze Etikett vor diesen Nachrichten. Leer gelassen bleibt es [%s]."
L["The side the whisper tiles and conversations slide out from. Left suits a chat on the right of your screen."] = "Die Seite, von der die Flüsterkacheln und Gespräche herausgleiten. Links passt zu einem Chat rechts auf dem Bildschirm."
L["The size of each whisper tile."] = "Die Größe jeder Flüsterkachel."
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "Die Größe der Eingangs-, Flugmeister-, Schiff- und Zeppelin-Symbole auf der Weltkarte. Sie behalten diese Größe beim Zoomen."
L["The skull, star and other raid markers just left of the bar."] = "Der Totenkopf, Stern und andere Schlachtzugsmarker direkt links von der Leiste."
L["The slim health bar. The name, the health number and the power line sit outside it."] = "Die schlanke Gesundheitsleiste. Der Name, die Gesundheitszahl und die Ressourcenzeile sitzen außerhalb."
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "Der kleine Tab am linken Rand des Meters (sichtbar, wenn die Maus nahe ist) schiebt ihn manuell heraus oder hinein."
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "Der kleine Tab, der den Namen über dem Rahmen hält: sein eigener Rand, Ecken, Schatten, Platz und Breite."
L["The small zone names over each group of quests."] = "Die kleinen Zonennamen über jeder Questgruppe."
L["The soft light behind the model on the Character page."] = "Das weiche Licht hinter dem Modell auf der Charakterseite."
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "Das weiche Licht hinter dem Modell auf der Charakterseite. Wenn aus, zeigt sich nur der Hintergrund des Fensters."
L["The sound when someone whispers you. The first five are gentle chimes made for DaylightUI; picking one plays it once."] = "Der Sound, wenn jemand dich anflüstert. Die ersten fünf sind sanfte Glockentöne, die für DaylightUI gemacht wurden; einen auswählen spielt ihn einmal."
L["The space between the health bar and the power line under it."] = "Der Abstand zwischen der Gesundheitsleiste und der Ressourcenzeile darunter."
L["The spell an enemy is casting, under its health bar."] = "Der Zauber, den ein Feind wirkt, unter seiner Gesundheitsleiste."
L["The spell being cast, as a small icon left of the cast bar."] = "Der gerade gewirkte Zauber als kleines Symbol links von der Zauberleiste."
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "Der Zaubername und die Zeit auf den Zauberleisten. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The spell name and time on your cast bar."] = "Der Zaubername und die Zeit auf deiner Zauberleiste."
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "Der Zaubername und die Zeit auf deiner Zauberleiste. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "Der Zaubername und die Zeit auf der Zauberleiste deines Fokus. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "Der Zaubername und die Zeit auf der Zauberleiste deines Fokus. Im Rahmen bleibt er klein genug für die Ressourcenleiste."
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "Der Zaubername und die Zeit auf der Zauberleiste deines Ziels. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "Der Zaubername und die Zeit auf der Zauberleiste deines Ziels. Im Rahmen bleibt er klein genug für die Ressourcenleiste, es sei denn, „Textgröße im Rahmen“ ist eingestellt."
L["The spell name and timer on the target's cast bar."] = "Der Zaubername und der Timer auf der Zauberleiste des Ziels."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "Der Zaubername und der Timer, während die Leiste im Zielrahmen sitzt, auch über die Höhe der Ressourcenleiste hinaus. 0 verwendet „Textgröße der Ziel-Zauberleiste“, klein genug für die Ressourcenleiste gehalten."
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "Das Symbol des Zaubers am Ende der Zauberleiste deines Fokus. Nicht, während sie im Rahmen sitzt."
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "Das Symbol des Zaubers am Ende der Zauberleiste deines Ziels. Nicht, während sie im Rahmen sitzt."
L["The spell's name on every cast bar."] = "Der Name des Zaubers auf jeder Zauberleiste."
L["The spell's own"] = "Die des Zaubers"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "Die eigene Farbe des Zaubers (Erneuerung grün, ein Schild blau), oder eine deiner Wahl."
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "Die Zauberbuch- und Talenttasten öffnen das Fenster von DaylightUI. Im Kampf öffnet sich das eigene Buch des Spiels, damit du weiterhin Zauber auf deine Leisten ziehen kannst. Schalte es aus, um immer das Fenster des Spiels zu nutzen."
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "Das Zauberbuch und die Talente, die Beruf-Fenster, das Berufs-Buch, der Stall."
L["The square minimap in the panel."] = "Die quadratische Minikarte im Panel."
L["The square's color when Heal indicator color is Custom color."] = "Die Farbe des Quadrats, wenn „Farbe des Heilungsindikators“ auf „Benutzerdefinierte Farbe“ steht."
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "Die Statistikgruppen-Überschriften und die Überschriften der anderen Seiten. „Jeder seine eigene“: eine Farbe pro Statistikgruppe, der Reihe nach auf den anderen Seiten verwendet."
L["The sweep can't start in combat."] = "Der Sweep kann im Kampf nicht starten."
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "Der Zeiger und die Zeit des Schwung-Timers. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["The tag after a PvP quest's title."] = "Das Etikett nach dem Titel einer PvP-Quest."
L["The tag after a dungeon quest's title."] = "Das Etikett nach dem Titel einer Dungeon-Quest."
L["The tag after a raid quest's title."] = "Das Etikett nach dem Titel einer Schlachtzugs-Quest."
L["The tag after an elite quest's title."] = "Das Etikett nach dem Titel einer Elite-Quest."
L["The talents you're using now."] = "Die Talente, die du gerade verwendest."
L["The target and focus cast bars' color for a moment after their cast is interrupted."] = "Die Farbe der Ziel- und Fokus-Zauberleisten für einen Moment, nachdem ihr Zauber unterbrochen wurde."
L["The target and focus cast bars' color while they cast."] = "Die Farbe der Ziel- und Fokus-Zauberleisten, während sie zaubern."
L["The target and focus cast bars' color while they channel."] = "Die Farbe der Ziel- und Fokus-Zauberleisten, während sie kanalisieren."
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "Die Klassen- und Ressourcenverläufe des Ziels und des Ziels des Ziels laufen andersherum, sodass sie deine spiegeln. Nur für einen horizontalen Verlauf."
L["The text in DaylightUI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "Der Text in den Fenstern von DaylightUI (Charakter, Zauberbuch, Berufe, Taschen, Questtagebuch) und den Fenstern des Spiels, die es umgestaltet. „Allgemein“ verwendet die Schrift darüber."
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "Die Texturen darüber gelten für alle Leisten gleichzeitig, außer wo die eigene Seite eines Rahmens oder die Fensterleisten darunter eine andere wählen. Dies setzt alle davon zurück auf die Texturen darüber."
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "Die dünne Linie unter jeder Überschrift. „Wie die Tab-Unterstreichung“: was „Tab-Unterstreichung“ darunter eingestellt ist. „Klassenverlauf“ verwendet die Farben deiner Klasse von der Verläufe-Seite."
L["The thin power bar under the health bar."] = "Die dünne Ressourcenleiste unter der Gesundheitsleiste."
L["The thin strip under the minimap with gold, gear, bag space and more."] = "Der dünne Streifen unter der Minikarte mit Gold, Ausrüstung, Taschenplatz und mehr."
L["The threat bars' color when Bar color is One color."] = "Die Farbe der Bedrohungsleisten, wenn „Leistenfarbe“ auf „Eine Farbe“ steht."
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "Die Bedrohungsfarben werden langsam heller und dunkler, schneller, wenn ein Gegner kurz vor dem Wechsel steht. Benötigt die Gesundheitsleiste, den Rand oder den Glow darüber."
L["The tick next to a finished objective."] = "Das Häkchen neben einem abgeschlossenen Ziel."
L["The time at the bottom of the minimap."] = "Die Uhrzeit unten an der Minikarte."
L["The time before each message (the game's own setting)."] = "Die Zeit vor jeder Nachricht (die eigene Einstellung des Spiels)."
L["The time left as a number on each icon."] = "Die verbleibende Zeit als Zahl auf jedem Symbol."
L["The time left on a timed quest once it's under a minute."] = "Die verbleibende Zeit einer zeitlich begrenzten Quest, sobald sie unter einer Minute ist."
L["The time left on a timed quest."] = "Die verbleibende Zeit einer zeitlich begrenzten Quest."
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "Die Zeit auf jeder Zauberleiste: was übrig ist, was übrig ist von der gesamten Zauberzeit, oder nichts."
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "Die Tönung eines Buttons, während dein Ziel außer Reichweite ist, wenn „Außer Reichweite“ auf „Symbol tönen“ steht."
L["The tooltip text; titles are a little larger."] = "Der Tooltip-Text; Titel sind etwas größer."
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode."] = "Das Panel oben rechts: Erfahrungsleiste oben, Schadensmeter und Minikarte darunter. Verschiebe es im Entsperrmodus."
L["The two ends of the bar's gradient. With Gradient off, the bar takes the bright end."] = "Die beiden Enden des Verlaufs der Leiste. Mit „Verlauf“ aus nimmt die Leiste das helle Ende."
L["The two-color fills bars use when set to a gradient (Class gradient on unit frames and nameplates, power bars)."] = "Die zweistufigen Füllungen, die Leisten verwenden, wenn sie auf einen Verlauf eingestellt sind (Klassenverlauf auf Einheitenrahmen und Namensplaketten, Ressourcenleisten)."
L["The unit you set as focus."] = "Die Einheit, die du als Fokus gesetzt hast."
L["The unit's health as text at the right end of the bar. Pick the format under Health text."] = "Die Gesundheit der Einheit als Text am rechten Ende der Leiste. Wähle das Format unter Gesundheitstext."
L["The unit's health written on this frame."] = "Die Gesundheit der Einheit, geschrieben auf diesem Rahmen."
L["The unit's level at the left end of the bar, in the game's difficulty color; ?? for one far above you, + for an elite."] = "Die Stufe der Einheit am linken Ende der Leiste, in der Schwierigkeitsfarbe des Spiels; ?? für eine weit über dir, + für einen Elite."
L["The whole Bank and alts window, slots, text and buttons together."] = "Das gesamte Bank- und Alts-Fenster, Plätze, Text und Buttons zusammen."
L["The whole bag window, slots, text and buttons together."] = "Das gesamte Taschenfenster, Plätze, Text und Buttons zusammen."
L["The whole bank window, slots, text and buttons together."] = "Das gesamte Bankfenster, Plätze, Text und Buttons zusammen."
L["The whole bar, icons, text and background together."] = "Die gesamte Leiste, Symbole, Text und Hintergrund zusammen."
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "Der gesamte Feed. Auch das Mausrad über seinem Anfasser in /dui unlock."
L["The whole group shows only during a fight."] = "Die ganze Gruppe zeigt sich nur während eines Kampfes."
L["The whole group shows only in a party or raid."] = "Die ganze Gruppe zeigt sich nur in einer Gruppe oder einem Schlachtzug."
L["The whole pop-up, text and bar together."] = "Das gesamte Pop-up, Text und Leiste zusammen."
L["The width of a whisper conversation. It slides out beside the tiles, as tall as the chat."] = "Die Breite eines Flüstergesprächs. Es gleitet neben den Kacheln heraus, so hoch wie der Chat."
L["The window's title shows the player's last name after their first name."] = "Der Titel des Fensters zeigt den Nachnamen des Spielers nach seinem Vornamen."
L["The world map's quest list and quest pages in DaylightUI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "Die Questliste und Questseiten der Weltkarte im DaylightUI-Stil, mit Verfolgen, Teilen und Aufgeben bei jeder Quest. Schalte es aus, um die des Spiels zu nutzen."
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "Die Zone oder der Ort, in dem du bist, oben auf der Karte (über den Koordinaten)."
L["The zone or area you're in, at the top of the minimap."] = "Die Zone oder der Ort, in dem du bist, oben an der Minikarte."
L["Their class icon"] = "Ihr Klassensymbol"
L["Their health as text at the right end of the bar."] = "Ihre Gesundheit als Text am rechten Ende der Leiste."
L["Their initial"] = "Ihr Initial"
L["Their initial in their class's colors, or their class icon from the set picked in Unit Frames (Daylight UI's own or a Jiberish style)."] = "Ihr Initial in den Farben ihrer Klasse, oder ihr Klassensymbol aus dem in Einheitenrahmen gewählten Satz (das von Daylight UI oder ein Jiberish-Stil)."
L["Their keybinds work even when hidden. Move them in unlock mode."] = "Ihre Tastenbelegungen funktionieren auch, wenn sie versteckt sind. Verschiebe sie im Entsperrmodus."
L["Their level at the left end of the bar."] = "Ihre Stufe am linken Ende der Leiste."
L["Their own window"] = "Ihr eigenes Fenster"
L["Their own window and the chat"] = "Ihr eigenes Fenster und der Chat"
L["Their own window: a tile beside the chat for each person you talk to; click one to open the conversation. The chat only: whispers stay in the chat like any other message."] = "Ihr eigenes Fenster: eine Kachel neben dem Chat für jede Person, mit der du sprichst; klicke eine, um das Gespräch zu öffnen. Nur der Chat: Flüstern bleiben im Chat wie jede andere Nachricht."
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "Ihre Timer-Leisten in deiner Schrift, Leistentextur und Rand, im Standard-Leistenstil von BigWigs. Größen, Farben und Plätze bleiben bei BigWigs."
L["These are for talent set %s; each talent set keeps its own."] = "Diese sind für Talentbaum %s; jeder Talentbaum behält seine eigenen."
L["These talents use the profile %s. Switch to it?"] = "Diese Talente verwenden das Profil %s. Dazu wechseln?"
L["Thick"] = "Dick"
L["Thick outline"] = "Dicker Umriss"
L["Thin"] = "Dünn"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "Dünne Linien teilen die Leiste in 20 Teile, wie die klassische Leiste: Jeder ist 5% einer Stufe."
L["This Legacy tree isn't available yet."] = "Dieser Erbe-Baum ist noch nicht verfügbar."
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "Die eigene Namensgröße dieser Leiste. „Textgröße“ unter „Ganze Gruppe“ setzt die aller Leisten."
L["This character"] = "Dieser Charakter"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "Dieser Charakter hat den Einrichtungsassistenten nicht abgeschlossen, daher kehren verschobene Rahmen beim Ausloggen zurück. Tippe /dui install, um ihn abzuschließen."
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "Dieser Charakter hat den Einrichtungsassistenten nicht abgeschlossen, daher geht verloren, was du änderst oder verschiebst, wenn du dich ausloggst. Schließe zuerst den Assistenten ab, dann mache deine Änderungen."
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "Die dieses Charakters, für den aktiven Talentbaum. Betrifft deine Spieler-, Ziel-, Ziel-des-Ziels-, Begleiter-, Fokus-, Gruppen- und Schlachtzugsrahmen."
L["This client has no aura container; target auras are off."] = "Dieser Client hat keinen Aura-Container; Ziel-Auren sind aus."
L["This fight"] = "Dieser Kampf"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "Der Gesundheitstext und die große Zahl dieses Rahmens. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "Die Namen dieses Rahmens und sein Stufenabzeichen. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["This frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares."] = "Die eigene Gesundheitsfarbe dieses Rahmens, damit er anders aussehen kann als die anderen. „Wie die Farben-Seite“ folgt der Farbe, die alle Rahmen teilen."
L["This frame's own name color. Same as the Colors page follows the name color every frame shares."] = "Die eigene Namensfarbe dieses Rahmens. „Wie die Farben-Seite“ folgt der Namensfarbe, die alle Rahmen teilen."
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "Der eigene Umriss, die Ecken und der Schatten dieses Rahmens, damit er sich vom Rest deiner UI abhebt."
L["This frame's own power color. Same as the Colors page follows the color every frame shares."] = "Die eigene Ressourcenfarbe dieses Rahmens. „Wie die Farben-Seite“ folgt der Farbe, die alle Rahmen teilen."
L["This frame's power text. General uses the font on General > Appearance."] = "Der Ressourcentext dieses Rahmens. „Allgemein“ verwendet die Schrift unter Allgemein > Erscheinungsbild."
L["This group's header. The other pages use the six colors in turn."] = "Die Überschrift dieser Gruppe. Die anderen Seiten verwenden die sechs Farben der Reihe nach."
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "Die eigene Größe dieses Symbols. „Ganze Gruppe“ darunter setzt alle Symbole der Gruppe."
L["This level"] = "Diese Stufe"
L["This session"] = "Diese Sitzung"
L["This set hasn't been used yet. Activate it to spend its points."] = "Dieser Satz wurde noch nicht verwendet. Aktiviere ihn, um seine Punkte auszugeben."
L["This setting"] = "Diese Einstellung"
L["This zone"] = "Diese Zone"
L["This zone only"] = "Nur diese Zone"
L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Sound)."] = "Diese stillen Fehler spielen einen weichen, tiefen Tick anstelle der Sprachzeile, nie in einem Stoß. Folgt den weichen UI-Sounds (Allgemein > Sound)."
