L["Two-color gradient"] = "Zweistufiger Verlauf"
L["Type"] = "Typ"
L["Type DELETE for me"] = "Tippe LÖSCHEN für mich"
L["Type a buff's name and pick where it belongs."] = "Tippe den Namen eines Stärkungszaubers und wähle, wohin er gehört."
L["Uncommon (green) and up"] = "Ungewöhnlich (grün) und höher"
L["Under a day"] = "Unter einem Tag"
L["Under its owner"] = "Unter seinem Besitzer"
L["Under the action bars"] = "Unter den Aktionsleisten"
L["Under the bar (the cast bar moves down) or over it (the name moves up)."] = "Unter der Leiste (die Zauberleiste bewegt sich nach unten) oder darüber (der Name bewegt sich nach oben)."
L["Under the cast bar"] = "Unter der Zauberleiste"
L["Under the frame (slides out)"] = "Unter dem Rahmen (gleitet heraus)"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "Unter dem Rahmen setzt sie den Winkel des Rahmens fort und gleitet heraus, während du zauberst. Über dem Rahmen oder eigenständig hat sie ihre eigene Größe."
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "Unter dem Rahmen setzt sie den Winkel des Rahmens fort. Wenn aus, ist ihr Ende gerade."
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "Unter dem Rahmen oder darüber, frei vom Namen. Die Stärkungs- oder Schwächungszauber des Ziels auf dieser Seite räumen den Weg."
L["Under the meter"] = "Unter dem Meter"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "Unter dem Meter steigt er aus dem unteren Rand des Schadensmeters im Panel auf, so breit wie der Meter, und die Zeilen des Meters machen Platz. Angedockt (links oder darunter) zeigt er sich nur, während der Schadensmeter offen ist. Sein eigenes Fenster geht überall hin: Verschiebe es im Entsperrmodus (/dui unlock) und ziehe an seiner Ecke, um es zu skalieren."
L["Under the meter it's part of the panel, with no window of its own."] = "Unter dem Meter ist er Teil des Panels, ohne eigenes Fenster."
L["Under the panel"] = "Unter dem Panel"
L["Underline color"] = "Unterstreichungsfarbe"
L["Undo"] = "Rückgängig"
L["Unexplored area brightness"] = "Helligkeit unerforschter Gebiete"
L["Unfold"] = "Ausklappen"
L["Unfriendly"] = "Unfreundlich"
L["Unhook it"] = "Abhängen"
L["Unit Frames"] = "Einheitenrahmen"
L["Unknown"] = "Unbekannt"
L["Unknown command '%s'."] = "Unbekannter Befehl „%s“."
L["Unknown spell"] = "Unbekannter Zauber"
L["Unlearn"] = "Verlernen"
L["Unlist"] = "Von der Liste nehmen"
L["Unlock"] = "Entsperren"
L["Unlock frames"] = "Rahmen entsperren"
L["Unlock the chat's size"] = "Die Größe des Chats entsperren"
L["Unlocked. Drag to move, scroll to resize, right-click to put back, /dui lock when done."] = "Entsperrt. Ziehen zum Verschieben, Scrollen zum Ändern der Größe, Rechtsklick zum Zurücksetzen, /dui lock wenn fertig."
L["Unpin"] = "Lösen"
L["Untrack"] = "Nicht mehr verfolgen"
L["Untrack all"] = "Alle nicht mehr verfolgen"
L["Up"] = "Oben"
L["Up and Down scroll the text in a straight line. Arc bursts it out to the side and curves it up."] = "„Oben“ und „Unten“ scrollen den Text in einer geraden Linie. „Bogen“ schießt ihn zur Seite und krümmt ihn nach oben."
L["Up early. Even the murlocs are still asleep."] = "Früh auf. Sogar die Murlocs schlafen noch."
L["Up to three, at the debuffs' size, with a countdown. They only appear when a boss uses them. With the game's buff frames shown, the game shows them there instead."] = "Bis zu drei, in der Größe der Schwächungszauber, mit Countdown. Sie erscheinen nur, wenn ein Boss sie verwendet. Wenn die Stärkungszauber-Rahmen des Spiels angezeigt werden, zeigt das Spiel sie dort stattdessen."
L["Up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "Bis zu zwei große Symbole in der Mitte, mit einem Wisch für die verbleibende Zeit. Sie erscheinen nur, wenn ein Boss sie verwendet."
L["Up: newest at the bottom"] = "Nach oben: neueste unten"
L["Update"] = "Aktualisieren"
L["Usable glow color"] = "Farbe des nutzbaren Glows"
L["Usable"] = "Nutzbar"
L["Usage: /dui buffs toggle <category name>"] = "Verwendung: /dui buffs toggle <Kategoriename>"
L["Use"] = "Verwenden"
L["Use DaylightUI's"] = "DaylightUIs verwenden"
L["Use DaylightUI's Cooldown Manager"] = "Den Cooldown-Manager von DaylightUI verwenden"
L["Use DaylightUI's quest tracker"] = "Den Questverfolger von DaylightUI verwenden"
L["Use a setup I have"] = "Ein vorhandenes Setup verwenden"
L["Use accent color"] = "Akzentfarbe verwenden"
L["Use guild money first"] = "Zuerst Gildengeld verwenden"
L["Use my language's font"] = "Die Schrift meiner Sprache verwenden"
L["Use my layout on this character"] = "Mein Layout auf diesem Charakter verwenden"
L["Use raid frames in a party"] = "Schlachtzugsrahmen in einer Gruppe verwenden"
L["Use this"] = "Dies verwenden"
L["Use this font for the game's text"] = "Diese Schrift für den Text des Spiels verwenden"
L["Use this heal indicator"] = "Diesen Heilungsindikator verwenden"
L["Used by all DaylightUI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed after ours."] = "Von allem DaylightUI-Text verwendet, außer wo die eigene Seite eines Rahmens eine andere Schrift wählt. „Schrift des Spiels“ ist die des Clients, einschließlich einer Schrift, die du ersetzt hast. Schriften, die andere Addons teilen (SharedMedia), sind nach den unseren aufgelistet."
L["Used when Unit Frames > Extras > Combo points > Colors is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "Verwendet, wenn Einheitenrahmen > Extras > Combopunkte > Farben ein Verlauf ist: „Alle Punkte“ füllt jeden Punkt mit einem Paar, „Punkt 1 bis 5“ gibt jedem Punkt sein eigenes."
L["Uses the Raid 10 frames, and the rows below are grayed out. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "Verwendet die Raid-10-Rahmen, und die Zeilen darunter sind ausgegraut. Schalte es aus, um dieser Schlachtzugsgröße eigene zu geben, ausgehend von einer Kopie von Raid 10."
L["Uses the game's own font in place of DaylightUI's fonts, which only have Latin letters. The options window changes after /reload."] = "Verwendet die eigene Schrift des Spiels anstelle der Schriften von DaylightUI, die nur lateinische Buchstaben haben. Das Optionsfenster ändert sich nach /reload."
L["Usually General."] = "Normalerweise Allgemein."
L["Usually Local Defense."] = "Normalerweise Lokale Verteidigung."
L["Usually Looking for Group."] = "Normalerweise Suche nach Gruppe."
L["Usually Trade."] = "Normalerweise Handel."
L["Usually a skill point"] = "Normalerweise ein Fertigkeitspunkt"
L["Varela Round"] = "Varela Round"
L["Vendor window"] = "Händlerfenster"
L["Vendors"] = "Händler"
L["Vendors open in the NPC window too, with their goods on a shelf. Turn it off to use the game's vendor window."] = "Händler öffnen sich auch im NSC-Fenster, mit ihren Waren auf einem Regal. Schalte es aus, um das Händlerfenster des Spiels zu nutzen."
L["Version %s."] = "Version %s."
L["Vertical (light on top)"] = "Vertikal (hell oben)"
L["Vertical bar"] = "Vertikale Leiste"
L["View distance (yards)"] = "Sichtweite (Meter)"
L["Visibility"] = "Sichtbarkeit"
L["Visible"] = "Sichtbar"
L["Waist"] = "Taille"
L["Wait for the talents being applied."] = "Warte, bis die Talente angewendet werden."
L["Walking Boots"] = "Wanderstiefel"
L["Warlock"] = "Hexenmeister"
L["Warm bell"] = "Warme Glocke"
L["Warmed by the fire"] = "Am Feuer gewärmt"
L["Warns you when a mob is about to change target, or has."] = "Warnt dich, wenn ein Gegner kurz davor ist, das Ziel zu wechseln, oder es getan hat."
L["Warrior"] = "Krieger"
L["Weapon"] = "Waffe"
L["Weapon Enchant"] = "Waffenverzauberung"
L["Weapon icon"] = "Waffensymbol"
L["Weapon master"] = "Waffenmeister"
L["Weapons"] = "Waffen"
L["Wearing it"] = "Trägt es"
L["Web addresses in messages become links; click one to copy it."] = "Webadressen in Nachrichten werden zu Links; klicke einen, um ihn zu kopieren."
L["Website: %s"] = "Website: %s"
L["Welcome"] = "Willkommen"
L["Welcome back, %s"] = "Willkommen zurück, %s"
L["Went out"] = "Ausgegangen"
L["What Alt-click on a quest in the tracker does."] = "Was ein Alt-Klick auf eine Quest im Verfolger macht."
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "Was ein Button macht, während dein Ziel außer Reichweite ist. Nicht genug Mana, Wut oder Energie macht dasselbe (blau, wenn getönt)."
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "Was ein Klick auf eine Quest im Verfolger macht. Ein Klick auf ihr Symbol macht sie immer zu deiner Priorität, und Rechtsklick öffnet ihr Menü."
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "Was ein freundlicher NSC tut (Gastwirt, Flugmeister...) unter seinem Namen, kleiner."
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "Was ein NSC tut (Kürschner, Flugmeister...) unter seinem Namen, kleiner. Nicht in Instanzen."
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "Was eine unterbrochene Zauberleiste macht: „Klinge“ schneidet sie in zwei, „Zersplittern“ zerbricht sie in Scherben, „Schnappen“ reißt sie in der Mitte, „Ausbrennen“ verbrennt die Füllung, „Zurückspulen“ peitscht sie zurück zu leer, „Schockwelle“ lässt Licht daraus hervorbrechen, „Zischen“ lässt ihr Licht auslaufen. Deine eigenen Unterbrechungen leuchten in deiner Akzentfarbe. Zeige auf eine Auswahl, um sie in der Vorschau zu sehen."
L["What changed in each version."] = "Was sich in jeder Version geändert hat."
L["What changed in each version. Click a version to open or close it."] = "Was sich in jeder Version geändert hat. Klicke eine Version, um sie zu öffnen oder zu schließen."
L["What each enemy plate shows on and around its bar, and its colors."] = "Was jede feindliche Plakette auf und um ihre Leiste zeigt, und ihre Farben."
L["What each item's icon shows in the Bank and alts window."] = "Was das Symbol jedes Gegenstands im Bank- und Alts-Fenster zeigt."
L["What each item's icon shows in the bank."] = "Was das Symbol jedes Gegenstands in der Bank zeigt."
L["What each item's icon shows."] = "Was das Symbol jedes Gegenstands zeigt."
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "Was jeder Platz zeigt, von links nach rechts. Uhr, Bildrate und Koordinaten sind auch auf der Minikarte."
L["What fades, and when"] = "Was ausblendet, und wann"
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "Was mit den Kämpfen passiert, die du bisher hast, wenn du einen Dungeon, Schlachtzug oder ein Schlachtfeld betrittst: behalten, fragen ob zurücksetzen, oder sofort zurücksetzen. Zurücklaufen nach dem Tod zählt nicht."
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "Was mit den Kämpfen passiert, die du bisher hast, wenn du einer Gruppe beitrittst: behalten, fragen ob zurücksetzen, oder sofort zurücksetzen."
L["What it shows"] = "Was es zeigt"
L["What sits between the text's parts."] = "Was zwischen den Teilen des Texts sitzt."
L["What the away message says."] = "Was die Abwesenheitsnachricht sagt."
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "Was der Meter auflistet: Schaden, Heilung, erlittener Schaden, Unterbrechungen, Dispels, Tode und mehr. Der Button am Meter ändert es auch."
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "Was der zweite Meter auflistet: Schaden, Heilung, erlittener Schaden, Unterbrechungen, Dispels, Tode und mehr."
L["What the target's or focus's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "Was die Zauberleiste des Ziels oder Fokus macht, wenn ihr Zauber unterbrochen wird. Deine eigenen Unterbrechungen leuchten in deiner Akzentfarbe."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "Was der Verfolger macht, wenn du einen Dungeon, Schlachtzug oder ein Schlachtfeld betrittst. Er kommt zurück, wenn du gehst."
L["What this extra text shows first, like the name, the level or the guild."] = "Was dieser zusätzliche Text zuerst zeigt, wie den Namen, die Stufe oder die Gilde."
L["What this group takes. Click to change."] = "Was diese Gruppe aufnimmt. Klicke zum Ändern."
L["What this slot on the data text strip shows. Slots count from the left."] = "Was dieser Platz auf dem Datentext-Streifen zeigt. Plätze zählen von links."
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "Was du plünderst und deine Fertigkeitssteigerungen, die als Bänder unten rechts hereingleiten."
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "Was du plünderst, gleitet unten rechts auf dem Bildschirm in seiner Qualitätsfarbe herein; mehr vom selben addiert sich zu seiner Anzahl und verblasst ein paar Sekunden später. Zeige auf eine Zeile für den Tooltip des Gegenstands. Verschiebe es mit /dui unlock."
L["What's Training is still reading your spells."] = "What's Training liest noch deine Zauber."
L["What's included"] = "Was enthalten ist"
L["What's new"] = "Was neu ist"
L["When Threat colors are on, they replace this color while showing."] = "Wenn Bedrohungsfarben an sind, ersetzen sie diese Farbe, während sie angezeigt werden."
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "Wenn ein Stärkungszauber ausläuft, gleiten die Zauber danach herüber, um seinen Platz zu füllen. Wenn aus, behält jeder Zauber seinen Platz. Ein Zauber, der auf „Seinen Platz behalten“ (Verhalten-Tab) steht, behält ihn in beiden Fällen."
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "Wenn ein Zauber unterbrochen wird, bleibt die Leiste einen Moment voll und sagt „Unterbrochen“."
L["When a reputation goes up a standing, like Friendly to Honored, the new standing rises in at the top of the screen in its color, with the faction's name and a bar showing how far into it you are. Follows Motion effects (General > Appearance)."] = "Wenn ein Ruf einen Rang aufsteigt, z. B. von Freundlich zu Wohlwollend, steigt der neue Rang oben auf dem Bildschirm in seiner Farbe auf, mit dem Namen der Fraktion und einer Leiste, die zeigt, wie weit du darin bist. Folgt den Bewegungseffekten (Allgemein > Erscheinungsbild)."
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "Wenn ein NSC nur eine Sache anzubieten hat (einen Händler, Flugmeister, Bankier oder Lehrer) und keine Quests, öffnet sich sein Fenster sofort. Halte Umschalt, um den Dialog zu sehen."
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "Wenn Auto-Loot an ist, wird alles auf einmal aufgenommen statt Gegenstand für Gegenstand."
L["When hovering a button shows its spell or item tooltip."] = "Wenn das Überfahren eines Buttons seinen Zauber- oder Gegenstand-Tooltip zeigt."
L["When it shows"] = "Wann es sich zeigt"
L["When not usable"] = "Wenn nicht nutzbar"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "Wenn aus, zeigt sich jeder Schwächungszauber mit einem Typ (Magie, Fluch, Krankheit, Gift), auch einer, den du nicht entfernen kannst."
L["When off, the game's own bag windows are used."] = "Wenn aus, werden die eigenen Taschenfenster des Spiels verwendet."
L["When off, the game's tracker stays where Edit Mode puts it."] = "Wenn aus, bleibt der Verfolger des Spiels dort, wo der Bearbeitungsmodus ihn hinsetzt."
L["When ready"] = "Wenn bereit"
L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "Wenn jemand deinen Namen schreibt, wo Leute sprechen, leuchtet er in deiner Akzentfarbe auf und der Tab, in dem er landet, glüht."
L["When the accent color is a gradient (Daylight's or your class's), window borders run along it."] = "Wenn die Akzentfarbe ein Verlauf ist (der von Daylight oder deiner Klasse), folgen die Fensterränder ihm."
L["When the away message answers."] = "Wann die Abwesenheitsnachricht antwortet."
L["When the shown bag bar fades and how far."] = "Wann die angezeigte Taschenleiste ausblendet und wie weit."
L["When the shown micro menu fades and how far."] = "Wann das angezeigte Mikro-Menü ausblendet und wie weit."
L["When to show"] = "Wann anzeigen"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "Wenn du einen guten Gegenstand zerstörst, ist das Bestätigungsfenster ausgefüllt. Du musst den Button trotzdem drücken."
L["When you dodge, parry or an attack misses you."] = "Wenn du ausweichst, parierst oder ein Angriff dich verfehlt."
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "Wenn du dich entfernst, verdunkelt sich die Welt, die UI blendet aus und dein Charakter steht neben einer Karte mit deinem Namen, Zone, ausgeruhtem EP und einer lustigen Tatsache. Bewege dich, klicke oder drücke eine Taste, um zurückzukommen. Nie im Kampf, Bosskämpfen, Schlüsselsteinen oder PvP-Matches."
L["When you have forms"] = "Wenn du Formen hast"
L["When you have totems"] = "Wenn du Totems hast"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "Wann dein nächster Auto-Angriff trifft: eine Leiste für jede Hand, mit der du schlägst."
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "Wo „Unterbrochen von“ und der Name erscheinen: neben der Zauberleiste oder darunter."
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "Wo entlang des Rahmens die Reihe beginnt: das abgeschrägte Ende zur Bildschirmmitte, die Mitte oder das ferne Ende."
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "Wo entlang der Oberseite des Rahmens der Tab sitzt. Ein Tab voller Breite beginnt immer am äußeren Ende. Oder ziehe den Tab im Design-Modus."
L["Where along the power bar the power text sits."] = "Wo entlang der Ressourcenleiste der Ressourcentext sitzt."
L["Where new lines come in."] = "Wo neue Zeilen ankommen."
L["Where on the button its key shows."] = "Wo auf dem Button seine Taste erscheint."
L["Where on the frame this square sits."] = "Wo auf dem Rahmen dieses Quadrat sitzt."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "Wo das Feld erscheint, in das du tippst. „Unter dem Panel“ hält einen Streifen unter dem Chat dafür frei, damit es nie Text verdeckt."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "Wo das Feld erscheint, in das du tippst. „Unter dem Panel“ hält einen Streifen unter dem Chat dafür frei, damit es nie Text verdeckt. „Unten“ hebt die Daylight-Chatbox ihre Nachrichten über das Feld, während du tippst."
L["Where the dispel icon sits on each frame, or just outside it."] = "Wo das Dispel-Symbol auf jedem Rahmen sitzt, oder direkt außerhalb."
L["Where the interrupter's name shows: right of the cast bar or under it."] = "Wo der Name des Unterbrechers erscheint: rechts von der Zauberleiste oder darunter."
L["Where the leader crown sits on each frame, or just outside it."] = "Wo die Anführerkrone auf jedem Rahmen sitzt, oder direkt außerhalb."
L["Where the name sits across the bar, while it's on the bar: left, center or right."] = "Wo der Name quer über die Leiste sitzt, während er auf der Leiste ist: links, mitte oder rechts."
L["Where the name sits across the bar: left, center or right."] = "Wo der Name quer über die Leiste sitzt: links, mitte oder rechts."
L["Where the name sits inside its tab: left, center or right."] = "Wo der Name in seinem Tab sitzt: links, mitte oder rechts."
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "Wo die Zahlen sich öffnen, wenn du die Leiste überfährst. „Automatisch“ öffnet sie zur Bildschirmmitte hin."
L["Where the raid marker sits on each frame, or just outside it."] = "Wo der Schlachtzugsmarker auf jedem Rahmen sitzt, oder direkt außerhalb."
L["Where the ready check answer sits on each frame, or just outside it."] = "Wo die Antwort auf den Bereitschaftscheck auf jedem Rahmen sitzt, oder direkt außerhalb."
L["Where the role icon sits on each frame, or just outside it."] = "Wo das Rollensymbol auf jedem Rahmen sitzt, oder direkt außerhalb."
L["Where the role, marker, crown and dispel icons sit on a tile."] = "Wo die Rollen-, Marker-, Kronen- und Dispel-Symbole auf einer Kachel sitzen."
L["Where things sit on your screen."] = "Wo Dinge auf deinem Bildschirm sitzen."
L["Where this category sits on the bar."] = "Wo diese Kategorie auf der Leiste sitzt."
L["Where this extra text sits on the frame, or just outside it."] = "Wo dieser zusätzliche Text auf dem Rahmen sitzt, oder direkt außerhalb."
L["Where this group sits in the bag."] = "Wo diese Gruppe in der Tasche sitzt."
L["Where to start"] = "Wo anfangen"
L["Where you put it"] = "Wo du es hinlegst"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "Wo deine Rahmen sitzen. Heiler bekommen die Gruppe als große Kacheln in der Bildschirmmitte."
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "Ob jede Schlachtzugsgruppe eine Spalte ist, nebeneinander, oder eine Reihe, nach unten gestapelt."
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "Ob der Meter den Kampf zählt, in dem du bist, oder jeden Kampf seit dem letzten Zurücksetzen."
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "Ob das Ende des Namens-Tabs schräg geschnitten ist. „Wie der Rahmen“ folgt dem eigenen Ende des Rahmens."
L["Whether the party frames stack down or line up across."] = "Ob die Gruppenrahmen nach unten stapeln oder quer ausrichten."
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "Ob der zweite Meter den Kampf zählt, in dem du bist, oder jeden Kampf seit dem letzten Zurücksetzen."
L["Whether this extra group shows debuffs or buffs."] = "Ob diese zusätzliche Gruppe Schwächungs- oder Stärkungszauber zeigt."
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "Ob deine Leisten und dein Rahmen zur Seite treten, wenn du nicht kämpfst. Jeder Teil hat später seine eigene Sichtbarkeits-Einstellung."
L["Which bar the rows below set."] = "Welche Leiste die Zeilen darunter einstellen."
L["Which buffs show."] = "Welche Stärkungszauber angezeigt werden."
L["Which buffs this group shows."] = "Welche Stärkungszauber diese Gruppe zeigt."
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "Welche Buttons die Aussehen-Zeilen auf dieser Seite ändern. Eine Leiste behält, was du für sie änderst; der Rest folgt „Alle Leisten“."
L["Which corner of the button its count shows in."] = "In welcher Ecke des Buttons seine Anzahl erscheint."
L["Which debuffs show."] = "Welche Schwächungszauber angezeigt werden."
L["Which debuffs this group shows."] = "Welche Schwächungszauber diese Gruppe zeigt."
L["Which end of the group stays put when a spell in it hides."] = "Welches Ende der Gruppe fest bleibt, wenn ein Zauber darin versteckt wird."
L["Which frame the pips sit on."] = "Auf welchem Rahmen die Punkte sitzen."
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "Welche Taste annimmt, fortsetzt und abschließt. Enter ist auch die Taste, die den Chat öffnet."
L["Which numbers"] = "Welche Zahlen"
L["Which of the six squares the rows below set."] = "Welches der sechs Quadrate die Zeilen darunter einstellen."
L["Which part's fade the rows below set."] = "Wessen Fade die Zeilen darunter einstellen."
L["Which quest tracker?"] = "Welcher Questverfolger?"
L["Which side of its owner's frame each pet bar sits on."] = "Auf welcher Seite des Rahmens seines Besitzers jede Begleiterleiste sitzt."
L["Which side of the list the quest item buttons sit on."] = "Auf welcher Seite der Liste die Questgegenstand-Buttons sitzen."
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "Welche Statistikgruppen geöffnet starten. „Nach Klasse und Spezialisierung“: Attribute und die, die für dich zählt. Gruppen, die du selbst öffnest oder einklappst, werden pro Charakter gemerkt."
L["Which way the color runs along a bar."] = "In welche Richtung die Farbe entlang einer Leiste läuft."
L["Which way the row adds its icons, starting from its position."] = "In welche Richtung die Reihe ihre Symbole hinzufügt, ausgehend von ihrer Position."
L["Which way the row of icons fills from its first icon."] = "In welche Richtung die Symbolreihe sich von ihrem ersten Symbol aus füllt."
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "Während Heldenhafter Stoß, Spalten oder Zermalmen auf deinen nächsten Schwung wartet, ändern die Nahkampfleisten die Farbe und zeigen seinen Namen."
L["While it's off cooldown but you can't cast it: Overpower before a dodge, Riposte before a parry, Execute on a healthy target. Show leaves it dimmed. Hide keeps its gap: the other spells don't move."] = "Während er außer Abklingzeit ist, du ihn aber nicht wirken kannst: Überwältigen vor einem Ausweichen, Riposte vor einem Parieren, Hinrichten auf einem gesunden Ziel. Anzeigen lässt ihn abgedunkelt. Verstecken behält seine Lücke: Die anderen Zauber bewegen sich nicht."
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "Während du Rahmen verschiebst, richten sich Kanten und Mitten an anderen Rahmen aus. Halte Umschalt, um sie überall abzulegen."
L["While possessing"] = "Während der Kontrolle"
L["While swinging"] = "Während des Schlagens"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "Während des Schlagens: jede Leiste nur, während ihr Schwung läuft, weg zwischen den Schwüngen. Im Kampf: alle deine Leisten, während du kämpfst."
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "Während der Stärkungs- oder Schwächungszauber nicht aktiv ist, behält er seinen Platz als ausgegrautes Symbol oder leere Leiste, damit du siehst, was fehlt."
L["While the panel is away, how long each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "Während das Panel weg ist, wie lange jede Nachricht bleibt, bevor sie verblasst. Eine neue Nachricht holt alte nicht zurück. Bewege die Maus über den Chat, um alle wiederzusehen."
L["While you cast, the power the spell will use is shaded on your power bar."] = "Während du zauberst, ist die Ressource, die der Zauber verbrauchen wird, auf deiner Ressourcenleiste schattiert."
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "Während du einen Bogen, ein Gewehr, eine Armbrust, eine Wurfwaffe oder einen Zauberstab hast."
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "Während du ein Ziel hast, blenden alle anderen Plaketten aus, damit dein Ziel hervorsticht. Eine Plakette, die zu zaubern beginnt, kommt zurück zu voll."
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Width, Health bar height and Scale)."] = "Während du ein Ziel hast, verwenden die Plakette deines Ziels und alle anderen die Größen darunter (relativ zu Breite, Höhe der Gesundheitsleiste und Skalierung)."
L["While you have a weapon in your off hand."] = "Während du eine Waffe in der Nebenhand hast."
L["Whisper"] = "Flüstern"
L["Whisper %s"] = "%s anflüstern"
L["Whisper color"] = "Flüsterfarbe"
L["Whisper sound"] = "Flüsterton"
L["Whisper tiles"] = "Flüsterkacheln"
L["Whisper tiles show"] = "Flüsterkacheln zeigen"
L["Whispered"] = "Geflüstert"
L["Whispers"] = "Flüstern"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "Flüstern sind Teil der Daylight-Chatbox: /dui chat daylight, um sie zu nutzen."
L["Whispers button"] = "Flüstern-Button"
L["Whispers from your Battle.net friends, and yours to them."] = "Flüstern von deinen Battle.net-Freunden und deine an sie."
L["Whispers in their own tab"] = "Flüstern in ihrem eigenen Tab"
L["Whispers open on the"] = "Flüstern öffnen sich auf der"
L["Whispers show in"] = "Flüstern erscheinen in"
L["Whispers you get and send."] = "Flüstern, die du erhältst und sendest."
L["White"] = "Weiß"
L["White, the unit's class color, or one you pick."] = "Weiß, die Klassenfarbe der Einheit oder eine deiner Wahl."
L["Who"] = "Wer"
L["Who a player or creature is targeting, in their color (\">> You <<\" when it's you)."] = "Wen ein Spieler oder eine Kreatur anvisiert, in ihrer Farbe („>> Du <<“ wenn du es bist)."
L["Who interrupted position"] = "Position des Unterbrechers"
L["Who to whisper?"] = "Wen anflüstern?"
L["Who your target is looking at."] = "Wen dein Ziel anschaut."
L["Who's closest to pulling your target, in a small window that slides out of the damage meter's left edge, along its bottom, or anywhere on its own."] = "Wer am nächsten daran ist, dein Ziel zu ziehen, in einem kleinen Fenster, das aus dem linken Rand des Schadensmeters, entlang seines unteren Rands oder irgendwo eigenständig herausgleitet."
L["Whole bar"] = "Ganze Leiste"
L["Whole group"] = "Ganze Gruppe"
L["Whole row in full color at max points"] = "Ganze Reihe in voller Farbe bei maximalen Punkten"
L["Width"] = "Breite"
L["William Pestle"] = "William Pestle"
L["Window"] = "Fenster"
L["Window background opacity"] = "Deckkraft des Fensterhintergrunds"
L["Window bar background"] = "Hintergrund der Fensterleiste"
L["Window bar texture"] = "Textur der Fensterleiste"
L["Window border"] = "Fensterrand"
L["Window font"] = "Fensterschrift"
L["Window height"] = "Fensterhöhe"
L["Window scale"] = "Fensterskalierung"
L["Window: talking opens a window at the side. Immersive: the talk is a card on the right, the camera comes in over your shoulder and the rest of the UI fades away until you're done. Vendors and trainers stay a window."] = "Fenster: Sprechen öffnet ein Fenster an der Seite. Immersiv: Das Gespräch ist eine Karte rechts, die Kamera kommt über deine Schulter und der Rest der UI blendet aus, bis du fertig bist. Händler und Lehrer bleiben ein Fenster."
L["Windows"] = "Fenster"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "Fenster gleiten herein und heraus, Tooltips blenden ein, das Symbol eines Zaubers springt, wenn er bereit ist, Gold und EP zählen hoch. Wenn aus, rastet alles sofort ein."
L["Windows open & close"] = "Fenster öffnen & schließen"
L["Wisdom"] = "Weisheit"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "Mit „Seinen Platz behalten“ (Stärkungszauber fehlt) zeigt er sich nur, wenn du ihn wirken musst, wie Kampfschrei."
L["With Show under Buff missing, Hide makes it appear only when you need to cast it, like Battle Shout."] = "Mit Anzeigen unter Stärkungszauber fehlt lässt Verstecken ihn nur erscheinen, wenn du ihn wirken musst, wie Kampfschrei."
L["With a fishing pole equipped, a quick right-click on the world casts Fishing. With no bait on the pole, the first click puts on the best bait in your bags. Holding the button still turns the camera, and clicking an NPC, an object or the bobber works as usual. Hold Shift, Ctrl or Alt to skip the cast."] = "Mit einer Angel ausgerüstet wirkt ein schneller Rechtsklick auf die Welt Angeln. Ohne Köder an der Angel legt der erste Klick den besten Köder aus deinen Taschen auf. Den Button halten dreht weiterhin die Kamera, und Klicken auf einen NSC, einen Gegenstand oder den Schwimmer funktioniert wie üblich. Halte Umschalt, Strg oder Alt, um den Zauber zu überspringen."
L["With a pet"] = "Mit einem Begleiter"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "Mit beiden an zeigt er sich nur, wenn du in einer Gruppe und im Kampf bist. Der zweite Meter folgt dem auch."
L["With chat open, Shift-click links the quest first."] = "Mit offenem Chat verlinkt Umschalt-Klick zuerst die Quest."
L["With items in categories, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "Mit Gegenständen in Kategorien zeigen sich Stapel desselben Gegenstands als einer, mit der Gesamtzahl. Sie zeigen sich getrennt, während du handelst oder den Briefkasten oder das Auktionshaus offen hast, damit du einen per Umschalt-Klick teilen kannst."
L["With items in categories, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "Mit Gegenständen in Kategorien zeigen sich deine Seelensplitter als einer, mit wie vielen du hast, obwohl jeder weiterhin seinen eigenen Platz einnimmt."
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "Ohne Porträt und ohne Namens-Tab sitzen die Rollen-, Marker-, Kronen- und Dispel-Symbole in den Ecken des Rahmens."
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "Mit der Chat-Eingabe unten: Während du tippst, gleiten die Nachrichten nach oben und das Feld, in das du tippst, sitzt darunter, damit es nie eine Zeile verdeckt."
L["With the immersive look, the NPC's words appear letter by letter and the choices drift in after them. Click or press the accept key to see them all at once."] = "Mit dem immersiven Aussehen erscheinen die Worte des NSC Buchstabe für Buchstabe und die Auswahl schwebt danach herein. Klicke oder drücke die Annehmen-Taste, um alle auf einmal zu sehen."
L["With the immersive look, the camera comes in over your shoulder and looks at the NPC while you talk, then goes back to how you had it. Not while mounted or in a fight."] = "Mit dem immersiven Aussehen kommt die Kamera über deine Schulter und schaut auf den NSC, während du sprichst, dann geht sie zurück, wie du sie hattest. Nicht auf dem Reittier oder im Kampf."
L["With the immersive look, the whole UI fades away while you talk, so only the NPC and the talk are left. A fight brings everything back at once."] = "Mit dem immersiven Aussehen blendet die ganze UI aus, während du sprichst, sodass nur der NSC und das Gespräch übrig bleiben. Ein Kampf bringt alles sofort zurück."
L["Withdraw"] = "Abheben"
L["Withdraw gold"] = "Gold abheben"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "Innerhalb jeder Zone. „Fortschritt zuletzt“ rückt eine Quest nach oben, wenn ein Kill, Gegenstand oder Ziel zählt. „Nächste zuerst“ schaut alle paar Sekunden erneut, während du dich bewegst, nie im Kampf oder in einem Dungeon. Im Kampf bewegt sich nichts."
L["Wood pop"] = "Holzknacken"
L["Words to light up"] = "Wörter zum Hervorheben"
L["Words to light up, separated by commas"] = "Wörter zum Hervorheben, getrennt durch Kommas"
L["World"] = "Welt"
L["World map"] = "Weltkarte"
L["World markers"] = "Weltmarker"
L["World of Warcraft"] = "World of Warcraft"
L["Wowhead link"] = "Wowhead-Link"
L["Wowhead link (Ctrl+C copies it):"] = "Wowhead-Link (Strg+C kopiert ihn):"
L["Wrists"] = "Handgelenke"
L["Write a letter..."] = "Einen Brief schreiben..."
L["Write a note to list for %s."] = "Schreibe eine Notiz zur Auflistung für %s."
L["Write a subject."] = "Schreibe einen Betreff."
L["Write the full name: first and last."] = "Schreibe den vollständigen Namen: Vor- und Nachname."
L["Writes zone names in capital letters. When off, they're written as the game writes them."] = "Schreibt Zonennamen in Großbuchstaben. Wenn aus, werden sie geschrieben, wie das Spiel sie schreibt."
L["XP"] = "EP"
L["XP bar"] = "Erfahrungsleiste"
L["XP bar position"] = "Position der Erfahrungsleiste"
L["XP bar, damage meter and a square minimap in one corner panel."] = "Erfahrungsleiste, Schadensmeter und eine quadratische Minikarte in einem Eckpanel."
L["XP gain effects"] = "Effekte bei EP-Gewinn"
L["XP, reputation and skills"] = "EP, Ruf und Fertigkeiten"
L["Yards under the arrow"] = "Meter unter dem Pfeil"
L["Yell"] = "Schreien"
L["Yell color"] = "Schreiffarbe"
L["Yes"] = "Ja"
L["You"] = "Du"
L["You block about 1 in %d attacks with your shield."] = "Du blockst etwa 1 von %d Angriffen mit deinem Schild."
L["You can also drag the chat's bottom-right corner to size it."] = "Du kannst auch die untere rechte Ecke des Chats ziehen, um ihn zu skalieren."
L["You can also switch with the button next to the search box."] = "Du kannst auch mit dem Button neben dem Suchfeld wechseln."
L["You can make %d"] = "Du kannst %d herstellen"
L["You can reach rank %d this week"] = "Du kannst diese Woche Rang %d erreichen"
L["You can track up to %d quests."] = "Du kannst bis zu %d Quests verfolgen."
L["You can't parry yet."] = "Du kannst noch nicht parieren."
L["You carry %s."] = "Du trägst %s."
L["You choose one of these:"] = "Du wählst eine davon:"
L["You dodge about 1 in %d attacks."] = "Du weichst etwa 1 von %d Angriffen aus."
L["You don't block yet."] = "Du blockst noch nicht."
L["You don't dodge attacks yet."] = "Du weichst noch keinen Angriffen aus."
L["You don't have that much gold."] = "Du hast nicht so viel Gold."
L["You get back %.0f mana every 5 seconds while not casting."] = "Du erhältst alle 5 Sekunden %.0f Mana zurück, während du nicht zauberst."
L["You keep"] = "Du behältst"
L["You parry about 1 in %d attacks from the front."] = "Du parierst etwa 1 von %d Angriffen von vorne."
L["You shoot every %.2f seconds. Lower is faster."] = "Du schießt alle %.2f Sekunden. Niedriger ist schneller."
L["You'll also get:"] = "Du erhältst außerdem:"
L["You'll choose one of these:"] = "Du wählst eine davon:"
L["You're in a group: the leader tools work for real. Leave the group to practice with sample members."] = "Du bist in einer Gruppe: Die Anführer-Werkzeuge funktionieren echt. Verlasse die Gruppe, um mit Beispielmitgliedern zu üben."
L["You're in combat; this finishes as soon as it ends."] = "Du bist im Kampf; das endet, sobald er vorbei ist."
L["You're not in a guild."] = "Du bist in keiner Gilde."
L["You're not in a raid."] = "Du bist in keinem Schlachtzug."
L["You've already learned talents this build doesn't have. A trainer can reset them."] = "Du hast bereits Talente gelernt, die dieser Build nicht hat. Ein Lehrer kann sie zurücksetzen."
L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in DaylightUI style."] = "Deine Erbe-Punkte, ihre Belohnungen, die Herausforderungen, die sie einbringen, und die Erbe-Bäume, in einem Fenster, im DaylightUI-Stil."
L["Your accent, when the accent color is set to Custom color."] = "Dein Akzent, wenn die Akzentfarbe auf „Benutzerdefinierte Farbe“ steht."
L["Your action bars and their buttons."] = "Deine Aktionsleisten und ihre Buttons."
L["Your attacks and spells miss %.1f%% less often."] = "Deine Angriffe und Zauber verfehlen %.1f%% seltener."
L["Your attacks don't land critical hits yet."] = "Deine Angriffe landen noch keine kritischen Treffer."
L["Your bags are full."] = "Deine Taschen sind voll."
L["Your bank from anywhere, and your other characters' bags and banks."] = "Deine Bank von überall und die Taschen und Banken deiner anderen Charaktere."
L["Your bindings"] = "Deine Belegungen"
L["Your buffs"] = "Deine Stärkungszauber"
L["Your buffs and debuffs."] = "Deine Stärkungs- und Schwächungszauber."
L["Your buffs grow direction"] = "Wachstumsrichtung deiner Stärkungszauber"
L["Your buffs left / right"] = "Deine Stärkungszauber links / rechts"
L["Your buffs position"] = "Position deiner Stärkungszauber"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "Deine Stärkungszauber sortiert in farbcodierte Gruppen; Schwächungszauber nach Typ umrandet."
L["Your buffs up / down"] = "Deine Stärkungszauber oben / unten"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "Deine Stärkungszauber, Minikarte und Info-Panel, Questverfolger und Chat blenden auch aus, sodass nur das Feuer und die Welt übrig bleiben. Zeige auf eines davon, um es zu sehen."
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "Deine Stärkungszauber, sortiert in farbige Kategorien. Rechtsklick auf einen Stärkungszauber, um ihn abzubrechen; Umschalt-Klick, um ihn in eine andere Kategorie zu verschieben. Die Leiste sitzt neben dem Info-Panel; um sie zu verschieben, schalte „An das Info-Panel anhängen“ aus."
L["Your cast bar's color for a moment after your cast is interrupted."] = "Die Farbe deiner Zauberleiste für einen Moment, nachdem dein Zauber unterbrochen wurde."
L["Your cast bar's color while you cast."] = "Die Farbe deiner Zauberleiste, während du zauberst."
L["Your cast bar's color while you channel."] = "Die Farbe deiner Zauberleiste, während du kanalisierst."
L["Your cast bar's colors"] = "Die Farben deiner Zauberleiste"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "Deine Zauber und Kanalisierungen in deiner Klassenfarbe oder dem Verlauf deiner Klasse mit zweistufiger Füllung. Nicht mit dem Daylight-Verlauf."
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "Dein Charakterfenster: Ausrüstung, Modell, Werte und die anderen Seiten. Es öffnet sich mit C, wie immer."
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "Dein Chat kommt auch beim nächsten Einloggen auf diesem Charakter zurück, unter einer grauen Linie mit dem Zeitpunkt, zu dem du gegangen bist."
L["Your class"] = "Deine Klasse"
L["Your class can heal; pick Healer if you do."] = "Deine Klasse kann heilen; wähle Heiler, wenn du das tust."
L["Your class's pick"] = "Die Wahl deiner Klasse"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "„Die Wahl deiner Klasse“ folgt deiner Klasse auf jedem Charakter. Wähle eine, um sie stattdessen zu beobachten."
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "Deine Schaden-über-Zeit-Zauber: Das Ende der Gesundheit, die sie noch nehmen werden, ist dunkler schattiert."
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Colors."] = "Deine Schaden-über-Zeit-Zauber: Das Ende der Gesundheit, die sie noch nehmen werden, ist dunkler schattiert. Die Farbe ist unter Einheitenrahmen > Farben."
L["Your debuffs"] = "Deine Schwächungszauber"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "Deine Schwächungszauber, Massenkontrolle und Stärkungszauber, die du entfernen kannst, auf feindlichen Plaketten."
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "Die Zauberleiste deines Fokus füllt sich von rechts. Nicht, während sie im Rahmen sitzt."
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "Die Zauber deines Fokus, solange sie dauern. Sie verwendet die Farben der Ziel-Zauberleiste."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "Die eigene Gesundheitsfarbe deines Rahmens, damit er anders aussehen kann als die anderen. „Wie die Farben-Seite“ folgt der Farbe, die alle Rahmen teilen; Daylight-Verlauf geht vom Blau zum Orange des Logos."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange; Accent color follows your accent on General > Appearance, gradient included."] = "Die eigene Gesundheitsfarbe deines Rahmens, damit er anders aussehen kann als die anderen. Wie die Farben-Seite folgt der Farbe, die alle Rahmen teilen; Daylight-Verlauf geht vom Blau zum Orange des Logos; Akzentfarbe folgt deinem Akzent unter Allgemein > Erscheinungsbild, inklusive Verlauf."
L["Your frames"] = "Deine Rahmen"
L["Your frames per second beside the clock."] = "Deine Bilder pro Sekunde neben der Uhr."
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "Deine Bilder pro Sekunde neben der Uhr. Bewege die Maus darüber für Latenz, Addon-CPU und Speicher."
L["Your friends, recent allies, friend requests and the raid, in one window, in DaylightUI style."] = "Deine Freunde, kürzliche Verbündete, Freundschaftsanfragen und der Schlachtzug, in einem Fenster, im DaylightUI-Stil."
L["Your group is too big for a %d-player activity."] = "Deine Gruppe ist zu groß für eine Aktivität mit %d Spielern."
L["Your guild's officer chat."] = "Der Offizierschat deiner Gilde."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals sees everything it casts."] = "Deine Heilungen über Zeit und Schilde, alles was du wirkst, oder alle. Eine Klasse ohne Heilungen sieht alles, was sie wirkt."
L["Your health and mana come back faster while you're not fighting or casting."] = "Deine Gesundheit und dein Mana kommen schneller zurück, während du nicht kämpfst oder zauberst."
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "Deine Gesundheit und Ressource direkt unter deinem Charakter, so wie die persönliche Anzeige von Legion zu deinen Füßen saß."
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "Deine Gesundheitsleiste, deine Ressource darunter und, für Schurken und Druiden, deine Combopunkte, direkt unter deinem Charakter. Sie folgt der Kamera, während du zoomst."
L["Your health. Each point adds about 10; you have %.0f."] = "Deine Gesundheit. Jeder Punkt fügt etwa 10 hinzu; du hast %.0f."
L["Your last name after your first, at the top of the window."] = "Dein Nachname nach deinem Vornamen, oben im Fenster."
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in DaylightUI style."] = "Deine Briefe, das Senden und was du über die Post und das Auktionshaus verdient hast, in einem Fenster, im DaylightUI-Stil."
L["Your listing"] = "Deine Anzeige"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "Deine Haupthand schlägt alle %.2f Sekunden. Niedriger ist schneller."
L["Your mana, rage or energy under the health bar."] = "Dein Mana, Wut oder Energie unter der Gesundheitsleiste."
L["Your melee attacks hit harder: Strength adds attack power."] = "Deine Nahkampfangriffe treffen härter: Stärke erhöht die Angriffskraft."
L["Your own buffs and heals over time, in a row above the name."] = "Deine eigenen Stärkungszauber und Heilungen über Zeit, in einer Reihe über dem Namen."
L["Your own color"] = "Deine eigene Farbe"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "Dein eigenes Abklingzeit-Layout: jeder Zauber, den der Cooldown-Manager als Symbol oder Leiste verfolgt, platziert, wo du willst, und zusammengefügt. Ein Layout pro Talentbaum, für diesen Charakter."
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "Dein eigener Rahmen sitzt bei dem der Gruppe. Wenn aus, zeigt sich nur der Rest der Gruppe."
L["Your own frame."] = "Dein eigener Rahmen."
L["Your own groups"] = "Deine eigenen Gruppen"
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in DaylightUI's look. Saved for this character."] = "Dein eigenes Layout auf diesem Charakter. Wenn aus, zeigen sich die Zauber dieses Charakters dort, wo das Spiel sie hinsetzt, weiterhin im Aussehen von DaylightUI. Für diesen Charakter gespeichert."
L["Your own tile sits with the raid's. When off, only the rest of the raid shows."] = "Deine eigene Kachel sitzt bei denen des Schlachtzugs. Wenn aus, zeigt sich nur der Rest des Schlachtzugs."
L["Your party and raid as square tiles under you, dispels easy to spot."] = "Deine Gruppe und dein Schlachtzug als quadratische Kacheln unter dir, Dispels leicht zu erkennen."
L["Your party: bars like your own frame, or square tiles. Set how they line up, what shows, and move them as one in unlock mode."] = "Deine Gruppe: Leisten wie dein eigener Rahmen, oder quadratische Kacheln. Stelle ein, wie sie sich ausrichten, was angezeigt wird, und verschiebe sie als Einheit im Entsperrmodus."
L["Your pet"] = "Dein Begleiter"
L["Your pet or minion."] = "Dein Begleiter oder Diener."
L["Your pet's damage"] = "Der Schaden deines Begleiters"
L["Your pet's or totem's hits too."] = "Die Treffer deines Begleiters oder Totems auch."
L["Your picks are saved into %s."] = "Deine Auswahlen werden in %s gespeichert."
L["Your portrait ring, or your name tab without a portrait, turns red while you're in combat."] = "Dein Porträtring, oder dein Namens-Tab ohne Porträt, wird rot, während du im Kampf bist."
L["Your priority quest is the one the marker and arrow lead to."] = "Deine Prioritätsquest ist die, zu der Marker und Pfeil führen."
L["Your profession's recipes in one window, in DaylightUI style."] = "Die Rezepte deines Berufs in einem Fenster, im DaylightUI-Stil."
L["Your quest tracker."] = "Dein Questverfolger."
L["Your quests in the DaylightUI look, with item buttons and smooth motion."] = "Deine Quests im DaylightUI-Aussehen, mit Gegenstand-Buttons und flüssiger Bewegung."
L["Your role"] = "Deine Rolle"
L["Your setup"] = "Dein Setup"
L["Your shots don't land critical hits yet."] = "Deine Schüsse landen noch keine kritischen Treffer."
L["Your spellbook and talents in one window, in DaylightUI style."] = "Dein Zauberbuch und deine Talente in einem Fenster, im DaylightUI-Stil."
L["Your spells don't land critical hits yet."] = "Deine Zauber landen noch keine kritischen Treffer."
L["Your target's cast bar fills from the right. Not while it sits inside the frame."] = "Die Zauberleiste deines Ziels füllt sich von rechts. Nicht, während sie im Rahmen sitzt."
L["Your target's casts, while they last."] = "Die Zauber deines Ziels, solange sie dauern."
L["Your unit frames, shown here with sample units so you can see each choice."] = "Deine Einheitenrahmen, hier mit Beispiel-Einheiten gezeigt, damit du jede Wahl siehst."
L["Your watched quests, under the info panel. Move it in unlock mode."] = "Deine beobachteten Quests, unter dem Info-Panel. Verschiebe es im Entsperrmodus."
L["Your x, y position at the top of the map. Blank in dungeons and raids."] = "Deine x-, y-Position oben auf der Karte. Leer in Dungeons und Schlachtzügen."
L["Your x, y position at the top of the minimap. Blank in dungeons and raids."] = "Deine x-, y-Position oben an der Minikarte. Leer in Dungeons und Schlachtzügen."
L["Zeppelin to %s"] = "Zeppelin nach %s"
