L["Zzz on your portrait ring while you rest in an inn or city."] = "Zzz auf deinem Porträtring, während du dich in einem Gasthaus oder einer Stadt ausruhst."
L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were."] = "[G] für Allgemein, [T] für Handel, [G] für Gilde (in Gildengrün), [P] für Gruppe, [S] für Sagen, [Y] für Schreien, [W] für Flüstern. Zeilen, die bereits im Chat sind, bleiben wie sie waren."
L["[G] for General, [T] for Trade, [G] for guild (in guild green), [P] for party, [S] for say, [Y] for yell, [W] for whispers. Lines already in chat stay as they were. A chat tab's Show window sets your own tags."] = "[G] für Allgemein, [T] für Handel, [G] für Gilde (in Gildengrün), [P] für Gruppe, [S] für Sagen, [Y] für Schreien, [W] für Flüstern. Zeilen, die bereits im Chat sind, bleiben wie sie waren. Das Anzeigen-Fenster eines Chat-Tabs legt deine eigenen Etiketten fest."
